// Compute a single athlete's weekly adherence the SAME way the athlete-detail
// "Weekly Adherence" view does — so the roster and the detail can never disagree.
// Reads /macro-plans (targets per weekday) plus /daily-totals AND /food-logs
// (food logs fill any day missing from daily-totals, exactly like the detail).
// For each macro: a logged day counts as adhered if actual is within ±10% of
// target (the 90–110% green band). % is over LOGGED days only.
async function computeWeeklyAdherence(athleteId, token) {
  try {
    const plans = await apiFetch(`/macro-plans/${athleteId}`, token);
    const byDay = {};
    (Array.isArray(plans) ? plans : []).forEach((r) => {
      byDay[r.day_of_week] = {
        calories: Math.round(Number(r.calories || 0)),
        protein: Math.round(Number(r.protein_g || 0)),
        carbs: Math.round(Number(r.carbs_g || 0)),
        fat: Math.round(Number(r.fat_g || 0)),
      };
    });

    const today = new Date();
    const start = new Date(today); start.setDate(today.getDate() - 6);
    const fmt = (d) => `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}-${String(d.getDate()).padStart(2, "0")}`;

    let totals = [], foodLogs = [];
    try { totals = await apiFetch(`/daily-totals/${athleteId}?start=${fmt(start)}&end=${fmt(today)}`, token); } catch {}
    try { foodLogs = await apiFetch(`/food-logs/${athleteId}?start=${fmt(start)}&end=${fmt(today)}`, token); } catch {}

    // Normalize any date shape (a plain "2026-06-26", a full ISO timestamp,
    // or a Date) down to a "YYYY-MM-DD" key so logged days reliably match the
    // day-by-day lookup below. A mismatch here silently drops a logged day.
    const dayKeyOf = (v) => String(v).slice(0, 10);

    const byDate = {};
    (Array.isArray(totals) ? totals : []).forEach((r) => {
      byDate[dayKeyOf(r.date)] = {
        calories: Math.round(Number(r.calories || 0)),
        protein: Math.round(Number(r.protein_g || 0)),
        carbs: Math.round(Number(r.carbs_g || 0)),
        fat: Math.round(Number(r.fat_g || 0)),
      };
    });
    (Array.isArray(foodLogs) ? foodLogs : []).forEach((fl) => {
      const k = dayKeyOf(fl.date);
      if (byDate[k]) return;
      const foods = fl.foods || [];
      if (foods.length === 0) return;
      byDate[k] = {
        calories: Math.round(foods.reduce((s, f) => s + Number(f.calories || 0), 0)),
        protein: Math.round(foods.reduce((s, f) => s + Number(f.protein_g || f.protein || 0), 0)),
        carbs: Math.round(foods.reduce((s, f) => s + Number(f.carbs_g || f.carbs || 0), 0)),
        fat: Math.round(foods.reduce((s, f) => s + Number(f.fat_g || f.fat || 0), 0)),
      };
    });

    const DAYS_MF = ["MON", "TUE", "WED", "THU", "FRI", "SAT", "SUN"];
    // Average-of-daily-percentages over LOGGED days only. For each logged day we
    // take actual ÷ target × 100, then average those across the days logged.
    // This reflects "on average, how close to target are they" — so a string of
    // low days (e.g. 18%, 30%) averages to a low number rather than collapsing
    // to a pass/fail count.
    const acc = {
      daysLogged: 0,
      cal: { sum: 0, n: 0 }, p: { sum: 0, n: 0 }, c: { sum: 0, n: 0 }, f: { sum: 0, n: 0 },
    };

    for (let i = 6; i >= 0; i--) {
      const d = new Date(); d.setDate(d.getDate() - i);
      const dow = d.getDay();
      const dayKey = DAYS_MF[dow === 0 ? 6 : dow - 1];
      const dateStr = fmt(d);
      const target = byDay[dayKey];
      const actual = byDate[dateStr];
      const isLogged = actual && actual.calories > 0;
      if (!isLogged) continue;
      acc.daysLogged += 1;
      if (target) {
        if (target.calories > 0) { acc.cal.sum += (actual.calories / target.calories) * 100; acc.cal.n += 1; }
        if (target.protein > 0) { acc.p.sum += (actual.protein / target.protein) * 100; acc.p.n += 1; }
        if (target.carbs > 0) { acc.c.sum += (actual.carbs / target.carbs) * 100; acc.c.n += 1; }
        if (target.fat > 0) { acc.f.sum += (actual.fat / target.fat) * 100; acc.f.n += 1; }
      }
    }

    const pct = (o) => (o.n > 0 ? o.sum / o.n : null);
    return {
      adherencePct: pct(acc.cal),
      proteinPct: pct(acc.p),
      carbsPct: pct(acc.c),
      fatPct: pct(acc.f),
      daysLogged: acc.daysLogged,
    };
  } catch {
    return null;
  }
}

// Weekly adherence cells shown on each roster row: calories + P/C/F adherence.
// Each % is the AVERAGE of that macro's daily (actual ÷ target) over the days
// the athlete logged — so it reflects how close to target they run on average.
//
// IMPORTANT — days-logged governs the row. An average built on a single logged
// day is thin evidence. So unless the athlete has logged a meaningful chunk of
// the week, the percentages are dimmed to grey and the days-logged figure
// (shown in red/amber) drives the signal. Only when logging is solid do the
// percentages earn their colour bands, which match the athlete-detail view:
// 90–110% green, 75–125% amber, otherwise red — so BOTH under- and over-target
// (e.g. 18% or 140%) read as red.
function AdherenceCells({ a }) {
  const dl = a.daysLogged;
  // How trustworthy is the % given how much was logged this week?
  // trusted (≥5/7): show real colour bands. partial (3–4): show but tinted.
  // weak (<3): dim the %s entirely so a value can't read as "good" on thin data.
  const trust = dl == null ? "none" : dl >= 5 ? "full" : dl >= 3 ? "partial" : "weak";

  const bandColour = (p) => {
    if (p == null) return T.muted;
    if (p >= 90 && p <= 110) return T.coachGreen; // on target
    if (p >= 75 && p <= 125) return T.warn;       // close
    return T.danger;                              // well under or well over
  };
  // When logging is too thin, the % is greyed regardless of its value.
  const pctColour = (p) => (trust === "full" ? bandColour(p) : trust === "partial" ? (p == null ? T.muted : `${bandColour(p)}cc`) : T.muted);
  const fmt = (p) => (p == null ? "—" : `${Math.round(p)}%`);

  const cell = (label, p) => (
    <div style={{ textAlign: "center", minWidth: 42 }}>
      <div style={{ fontFamily: "Bebas Neue, system-ui", fontSize: 15, color: pctColour(p), lineHeight: 1, opacity: trust === "weak" ? 0.5 : 1 }}>{fmt(p)}</div>
      <div style={{ fontFamily: "DM Sans", fontSize: 8, color: T.muted, letterSpacing: 0.5, marginTop: 2 }}>{label}</div>
    </div>
  );

  // Days-logged is the dominant signal: green only when logging is solid.
  const dlColour = dl == null ? T.muted : dl >= 5 ? T.coachGreen : dl >= 3 ? T.warn : T.danger;

  return (
    <div style={{ display: "flex", alignItems: "center", gap: 10 }}>
      {cell("CAL", a.adherencePct)}
      {cell("P", a.proteinPct)}
      {cell("C", a.carbsPct)}
      {cell("F", a.fatPct)}
      <div style={{ textAlign: "center", minWidth: 50, paddingLeft: 8, borderLeft: `1px solid ${T.border}` }}>
        <div style={{ fontFamily: "Bebas Neue, system-ui", fontSize: 17, color: dlColour, lineHeight: 1, fontWeight: 700 }}>
          {dl == null ? "—" : `${dl}/7`}
        </div>
        <div style={{ fontFamily: "DM Sans", fontSize: 8, color: dl != null && dl < 3 ? T.danger : T.muted, letterSpacing: 0.5, marginTop: 2 }}>LOGGED</div>
      </div>
    </div>
  );
}

/* ─────────────────────────────────────────────────────────────────────────────
   Coach Login
────────────────────────────────────────────────────────────────────────────── */
function CoachLogin({ onLoggedIn }) {
  const [email, setEmail] = useState("");
  const [pass, setPass] = useState("");
  const [err, setErr] = useState("");
  const [loading, setLoading] = useState(false);
  const [showPass, setShowPass] = useState(false);

  const handleLogin = async () => {
    setErr("");
    if (!email.trim() || !pass) {
      setErr("Enter your coach credentials.");
      return;
    }
    setLoading(true);
    try {
      const data = await apiFetch("/auth/login", null, {
        method: "POST",
        body: JSON.stringify({ email: email.trim().toLowerCase(), password: pass }),
      });

      // data: { token, user }  (your backend returns this) [1](https://github.com/orgs/community/discussions/151670)
      localStorage.setItem(TOKEN_KEY, data.token);
      onLoggedIn({ ...data.user, token: data.token });
    } catch (e) {
      setErr(e.message);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div
      style={{
        minHeight: "100vh",
        background: T.bg,
        display: "flex",
        flexDirection: "column",
        alignItems: "center",
        justifyContent: "center",
        padding: 24,
        fontFamily: "DM Sans",
      }}
    >
      <style>{`
        *{box-sizing:border-box;margin:0;padding:0}
        input::placeholder{color:${T.muted}}
        input{caret-color:${T.accent}}
        @keyframes fadeUp{from{opacity:0;transform:translateY(16px)}to{opacity:1;transform:translateY(0)}}
      `}</style>

      <div style={{ width: "100%", maxWidth: 440, animation: "fadeUp .35s ease" }}>
        <div style={{ textAlign: "center", marginBottom: 34 }}>
          <div style={{ display: "flex", justifyContent: "center", marginBottom: 10 }}>
            <img
              src={LOGO_SRC}
              alt="No Rules Nutrition"
              style={{
                width: 120,
                height: 120,
                borderRadius: "50%",
                objectFit: "contain",
                border: `3px solid ${T.accent}44`,
                boxShadow: `0 0 32px ${T.accent}22`,
              }}
            />
          </div>

          <div
            style={{
              display: "inline-flex",
              alignItems: "center",
              gap: 8,
              background: `${T.coachGreen}18`,
              border: `1px solid ${T.coachGreen}44`,
              borderRadius: 999,
              padding: "4px 14px",
            }}
          >
            <div style={{ width: 6, height: 6, borderRadius: "50%", background: T.coachGreen }} />
            <span style={{ fontSize: 11, color: T.coachGreen, letterSpacing: 1.5, textTransform: "uppercase" }}>
              Coach Portal
            </span>
          </div>
        </div>

        <div style={{ background: T.card, border: `1px solid ${T.border}`, borderRadius: 20, padding: 30 }}>
          <div style={{ fontFamily: "Bebas Neue, system-ui", fontSize: 22, letterSpacing: 2, color: T.text, marginBottom: 22 }}>
            COACH SIGN IN
          </div>

          <div style={{ marginBottom: 14 }}>
            <label style={labelStyle}>Email</label>
            <input
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              onKeyDown={(e) => e.key === "Enter" && handleLogin()}
              placeholder="coach@norules.com"
              type="email"
              style={inputStyle}
            />
          </div>

          <div style={{ marginBottom: 18 }}>
            <label style={labelStyle}>Password</label>
            <div style={{ position: "relative" }}>
              <input
                value={pass}
                onChange={(e) => setPass(e.target.value)}
                onKeyDown={(e) => e.key === "Enter" && handleLogin()}
                placeholder="••••••••"
                type={showPass ? "text" : "password"}
                style={{ ...inputStyle, paddingRight: 52 }}
              />
              <button
                onClick={() => setShowPass((p) => !p)}
                style={{
                  position: "absolute",
                  right: 10,
                  top: "50%",
                  transform: "translateY(-50%)",
                  background: "none",
                  border: "none",
                  color: T.muted,
                  cursor: "pointer",
                  fontSize: 12,
                  fontFamily: "DM Sans",
                }}
                type="button"
              >
                {showPass ? "hide" : "show"}
              </button>
            </div>
          </div>

          {err && (
            <div
              style={{
                background: `${T.danger}18`,
                border: `1px solid ${T.danger}44`,
                borderRadius: 10,
                padding: "10px 14px",
                marginBottom: 14,
                fontSize: 12,
                color: T.danger,
              }}
            >
              {err}
            </div>
          )}

          <button
            onClick={handleLogin}
            disabled={loading}
            style={{
              width: "100%",
              background: loading ? T.border : T.accent,
              color: loading ? T.muted : T.bg,
              border: "none",
              borderRadius: 12,
              padding: 14,
              fontFamily: "Bebas Neue, system-ui",
              fontSize: 18,
              letterSpacing: 2,
              cursor: loading ? "default" : "pointer",
              transition: "all .2s",
            }}
            type="button"
          >
            {loading ? "SIGNING IN…" : "ACCESS COACH PORTAL"}
          </button>
        </div>

      </div>
    </div>
  );
}

