/* ─────────────────────────────────────────────────────────────────────────────
   Weekly Macro Plan — Rows per day
   - GET /macro-plans/:athleteId (optional but recommended)
   - PUT /macro-plans/:athleteId
────────────────────────────────────────────────────────────────────────────── */
function WeeklyMacroPlan({ athleteId, baseTargets, token, onSaved }) {
  const [loading, setLoading] = useState(false);
  const [saving, setSaving] = useState(false);
  const [err, setErr] = useState("");
  const [saved, setSaved] = useState(false);

  const emptyWeek = () =>
    DAYS.reduce((acc, d) => {
      acc[d] = {
        calories: baseTargets?.calories ?? 2000,
        protein: baseTargets?.protein ?? 150,
        carbs: baseTargets?.carbs ?? 200,
        fat: baseTargets?.fat ?? 70,
      };
      return acc;
    }, {});

  const [plan, setPlan] = useState(emptyWeek());

  useEffect(() => {
    // refresh defaults when athlete changes
    setPlan(emptyWeek());
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [athleteId]);

  // Load weekly macro plan from backend
  useEffect(() => {
    let ignore = false;
    (async () => {
      if (!athleteId || !token) return;
      setLoading(true);
      setErr("");
      try {
        const rows = await apiFetch(`/macro-plans/${athleteId}`, token);
        if (ignore) return;
        const byDay = {};
        (Array.isArray(rows) ? rows : []).forEach((r) => {
          const d = r.day_of_week;
          if (!d) return;
          byDay[d] = {
            calories: Number(r.calories || 0),
            protein: Number(r.protein_g || 0),
            carbs: Number(r.carbs_g || 0),
            fat: Number(r.fat_g || 0),
          };
        });
        setPlan((prev) => {
          const next = { ...prev };
          DAYS.forEach((d) => {
            if (byDay[d]) next[d] = { ...next[d], ...byDay[d] };
          });
          return next;
        });
      } catch (e) {
        if (!ignore) setErr(e.message || "Could not load macro plan");
      } finally {
        if (!ignore) setLoading(false);
      }
    })();
    return () => {
      ignore = true;
    };
  }, [athleteId, token]);

  const setCell = (day, key, value) => {
    const n = Math.max(0, Math.min(20000, Number(value) || 0));
    setPlan((prev) => ({
      ...prev,
      [day]: { ...prev[day], [key]: n },
    }));
  };

  const save = async () => {
    if (!athleteId) return;
    setSaving(true);
    setErr("");
    try {
      const plans = DAYS.map((d) => ({
        dayOfWeek: d,
        calories: Number(plan[d]?.calories || 0),
        protein_g: Number(plan[d]?.protein || 0),
        carbs_g: Number(plan[d]?.carbs || 0),
        fat_g: Number(plan[d]?.fat || 0),
      }));
      await apiFetch(`/macro-plans/${athleteId}`, token, {
        method: "PUT",
        body: JSON.stringify({ plans }),
      });
      setSaved(true);
      setTimeout(() => setSaved(false), 1500);
      onSaved?.();
    } catch (e) {
      setErr(e.message || "Could not save macro plan");
    } finally {
      setSaving(false);
    }
  };

  return (
    <div style={{ background: T.card, border: `1px solid ${T.border}`, borderRadius: 16, padding: 16 }}>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", gap: 10, flexWrap: "wrap" }}>
        <div>
          <div style={{ fontFamily: "Bebas Neue, system-ui", fontSize: 18, letterSpacing: 2, color: T.text }}>MACRO PLAN</div>
          <div style={{ fontFamily: "DM Sans", fontSize: 12, color: T.muted }}>Set targets per day (saved to backend)</div>
        </div>
        <div style={{ display: "flex", gap: 8, alignItems: "center" }}>
          <button onClick={save} disabled={saving || loading} style={{ ...miniBtnStyle(), borderColor: `${T.accent}55`, color: T.accent }} type="button">
            {saving ? "SAVING…" : loading ? "LOADING…" : "SAVE"}
          </button>
        </div>
      </div>

      {err ? (
        <div style={{ marginTop: 12, background: `${T.warn}18`, border: `1px solid ${T.warn}44`, borderRadius: 12, padding: 12, color: T.warn, fontFamily: "DM Sans", fontSize: 12 }}>{err}</div>
      ) : null}
      {saved ? (
        <div style={{ marginTop: 12, background: `${T.coachGreen}18`, border: `1px solid ${T.coachGreen}44`, borderRadius: 12, padding: 12, color: T.coachGreen, fontFamily: "DM Sans", fontSize: 12 }}>✓ Saved</div>
      ) : null}

      <div style={{ marginTop: 14, overflowX: "auto" }}>
        <table style={{ width: "100%", borderCollapse: "separate", borderSpacing: 0 }}>
          <thead>
            <tr>
              <th style={thStyle()}>DAY</th>
              <th style={thStyle()}>CAL</th>
              <th style={thStyle()}>P</th>
              <th style={thStyle()}>C</th>
              <th style={thStyle()}>F</th>
            </tr>
          </thead>
          <tbody>
            {DAYS.map((d) => (
              <tr key={d}>
                <td style={tdStyle()}>{d}</td>
                <td style={tdStyle()}><input value={plan[d]?.calories ?? 0} onChange={(e) => setCell(d, "calories", e.target.value)} style={cellInput()} /></td>
                <td style={tdStyle()}><input value={plan[d]?.protein ?? 0} onChange={(e) => setCell(d, "protein", e.target.value)} style={cellInput()} /></td>
                <td style={tdStyle()}><input value={plan[d]?.carbs ?? 0} onChange={(e) => setCell(d, "carbs", e.target.value)} style={cellInput()} /></td>
                <td style={tdStyle()}><input value={plan[d]?.fat ?? 0} onChange={(e) => setCell(d, "fat", e.target.value)} style={cellInput()} /></td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
}
/* ─────────────────────────────────────────────────────────────────────────────
   Athlete Mood Viewer — shows mood history for coach
────────────────────────────────────────────────────────────────────────────── */
/* ─────────────────────────────────────────────────────────────────────────────
   SVG Line Chart — reusable for mood & weight graphs
────────────────────────────────────────────────────────────────────────────── */
function TimeSeriesChart({ data, color, yLabel, yUnit, width = 560, height = 200, yMin: yMinProp, yMax: yMaxProp, formatY, emptyLabel }) {
  // data: [{ date: 'YYYY-MM-DD', value: number }] sorted by date ascending
  if (!data || data.length === 0) return <div style={{ color: T.muted, fontSize: 12 }}>{emptyLabel || "No data yet."}</div>;

  const pad = { top: 20, right: 16, bottom: 36, left: 44 };
  const w = width - pad.left - pad.right;
  const h = height - pad.top - pad.bottom;

  const vals = data.map(d => d.value);
  const yMin = yMinProp !== undefined ? yMinProp : Math.min(...vals) - (Math.max(...vals) - Math.min(...vals)) * 0.1;
  const yMax = yMaxProp !== undefined ? yMaxProp : Math.max(...vals) + (Math.max(...vals) - Math.min(...vals)) * 0.1;
  const yRange = yMax - yMin || 1;

  const xScale = (i) => pad.left + (data.length === 1 ? w / 2 : (i / (data.length - 1)) * w);
  const yScale = (v) => pad.top + h - ((v - yMin) / yRange) * h;

  const points = data.map((d, i) => `${xScale(i)},${yScale(d.value)}`);
  const line = points.join(" ");
  const areaPath = `M${xScale(0)},${yScale(data[0].value)} ` +
    data.map((d, i) => `L${xScale(i)},${yScale(d.value)}`).join(" ") +
    ` L${xScale(data.length - 1)},${pad.top + h} L${xScale(0)},${pad.top + h} Z`;

  // Y-axis labels (5 ticks)
  const yTicks = Array.from({ length: 5 }, (_, i) => yMin + (yRange * i) / 4);
  // X-axis labels (show ~6 dates)
  const step = Math.max(1, Math.floor(data.length / 6));
  const xLabels = data.filter((_, i) => i % step === 0 || i === data.length - 1);

  const dispY = formatY || ((v) => `${v}${yUnit || ""}`);

  return (
    <svg viewBox={`0 0 ${width} ${height}`} style={{ width: "100%", height: "auto", overflow: "visible" }}>
      {/* Grid lines */}
      {yTicks.map((t, i) => (
        <line key={i} x1={pad.left} x2={width - pad.right} y1={yScale(t)} y2={yScale(t)} stroke={T.border} strokeWidth={0.5} />
      ))}
      {/* Area fill */}
      <path d={areaPath} fill={`${color}15`} />
      {/* Line */}
      <polyline points={line} fill="none" stroke={color} strokeWidth={2} strokeLinejoin="round" strokeLinecap="round" />
      {/* Dots */}
      {data.map((d, i) => (
        <circle key={i} cx={xScale(i)} cy={yScale(d.value)} r={data.length > 60 ? 1.5 : 3} fill={color} stroke={T.card} strokeWidth={1} />
      ))}
      {/* Y-axis labels */}
      {yTicks.map((t, i) => (
        <text key={i} x={pad.left - 6} y={yScale(t) + 3} textAnchor="end" fill={T.muted} fontSize={9} fontFamily="JetBrains Mono, ui-monospace">
          {dispY(Math.round(t * 10) / 10)}
        </text>
      ))}
      {/* X-axis labels */}
      {xLabels.map((d) => {
        const idx = data.indexOf(d);
        const short = String(d.date).slice(5).split("-").reverse().join("/"); // DD/MM
        return (
          <text key={d.date} x={xScale(idx)} y={height - 6} textAnchor="middle" fill={T.muted} fontSize={8} fontFamily="JetBrains Mono, ui-monospace">
            {short}
          </text>
        );
      })}
      {/* Axis label */}
      <text x={8} y={pad.top - 6} fill={T.muted} fontSize={9} fontFamily="DM Sans">{yLabel || ""}</text>
    </svg>
  );
}

/* ─────────────────────────────────────────────────────────────────────────────
   Athlete Mood Graph — SVG time-series over extended period
────────────────────────────────────────────────────────────────────────────── */
function AthleteMoodViewer({ athleteId, token }) {
  const [moods, setMoods] = useState([]);
  const [loading, setLoading] = useState(true);
  const [range, setRange] = useState(30);

  const load = async () => {
    if (!athleteId || !token) return;
    try {
      const rows = await apiFetch(`/moods/${athleteId}`, token);
      setMoods(Array.isArray(rows) ? rows : []);
    } catch { setMoods([]); }
    setLoading(false);
  };

  useEffect(() => { setLoading(true); load(); }, [athleteId, token]);

  // Filter by range, sort ascending by date
  const filtered = moods
    .filter(m => {
      const d = new Date(m.date);
      const cutoff = new Date(); cutoff.setDate(cutoff.getDate() - range);
      return d >= cutoff;
    })
    .sort((a, b) => a.date.localeCompare(b.date));

  const chartData = filtered.map(m => ({ date: m.date, value: Number(m.mood_id || 0) }));
  const avgScore = chartData.length > 0 ? (chartData.reduce((a, d) => a + d.value, 0) / chartData.length).toFixed(1) : "—";
  const latestMood = filtered[filtered.length - 1];

  const rangeOptions = [{ v: 7, l: "7D" }, { v: 14, l: "14D" }, { v: 30, l: "30D" }, { v: 90, l: "90D" }];

  return (
    <div style={{ background: T.card, border: `1px solid ${T.border}`, borderRadius: 16, padding: 18 }}>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 14 }}>
        <div>
          <div style={{ fontFamily: "Bebas Neue, system-ui", fontSize: 18, letterSpacing: 2, color: T.text }}>MOOD TRACKING</div>
          <div style={{ fontFamily: "DM Sans", fontSize: 11, color: T.muted, marginTop: 2 }}>
            Avg: <span style={{ color: Number(avgScore) >= 4 ? T.coachGreen : Number(avgScore) >= 3 ? T.accent : T.danger, fontWeight: 700 }}>{avgScore}/5</span>
            {latestMood && <> · Latest: <span style={{ fontSize: 14 }}>{latestMood.emoji || "😶"}</span> {latestMood.label}</>}
            {latestMood?.note && <> — <span style={{ fontStyle: "italic" }}>"{latestMood.note}"</span></>}
          </div>
        </div>
        <div style={{ display: "flex", gap: 4 }}>
          {rangeOptions.map(r => (
            <button key={r.v} onClick={() => setRange(r.v)} style={{
              background: range === r.v ? `${T.accent}22` : "none",
              border: `1px solid ${range === r.v ? T.accent + "55" : T.border}`,
              borderRadius: 6, padding: "4px 10px", color: range === r.v ? T.accent : T.muted,
              fontFamily: "JetBrains Mono, ui-monospace", fontSize: 10, cursor: "pointer",
            }} type="button">{r.l}</button>
          ))}
        </div>
      </div>
      {loading ? <div style={{ color: T.muted, fontSize: 12 }}>Loading…</div> : (
        <TimeSeriesChart
          data={chartData}
          color="#f59e0b"
          yLabel="Mood Score"
          yUnit=""
          yMin={0.5}
          yMax={5.5}
          formatY={(v) => {
            const labels = { 1: "😞", 2: "😔", 3: "😐", 4: "🙂", 5: "😄" };
            return labels[Math.round(v)] || `${Math.round(v)}`;
          }}
          emptyLabel="No mood entries logged yet."
        />
      )}
    </div>
  );
}

/* ─────────────────────────────────────────────────────────────────────────────
   Athlete Weight Graph — SVG time-series over extended period
────────────────────────────────────────────────────────────────────────────── */
function AthleteWeightViewer({ athleteId, token }) {
  const [weights, setWeights] = useState([]);
  const [loading, setLoading] = useState(true);
  const [range, setRange] = useState(30);
  // Coach weight entry (today or backdated)
  const todayISO = (() => { const d = new Date(); return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,"0")}-${String(d.getDate()).padStart(2,"0")}`; })();
  const [entryDate, setEntryDate] = useState(todayISO);
  const [entryKg, setEntryKg] = useState("");
  const [savingW, setSavingW] = useState(false);
  const [entryMsg, setEntryMsg] = useState("");

  const saveWeight = async () => {
    const kg = Number(entryKg);
    if (!entryDate || !Number.isFinite(kg) || kg <= 0) { setEntryMsg("Enter a date and a weight in kg."); return; }
    if (kg > 400) { setEntryMsg("That weight looks wrong — check the number."); return; }
    setSavingW(true); setEntryMsg("");
    try {
      const rows = await apiFetch(`/weights/${athleteId}`, token, {
        method: "POST",
        body: JSON.stringify({ date: entryDate, kg }),
      });
      if (Array.isArray(rows)) setWeights(rows);
      const uk = entryDate.split("-").reverse().join("/");
      setEntryMsg(`Saved ${kg} kg for ${uk}.`);
      setEntryKg("");
      setTimeout(() => setEntryMsg(""), 3000);
    } catch (e) { setEntryMsg(e.message || "Could not save the weight"); }
    setSavingW(false);
  };

  const load = async () => {
    if (!athleteId || !token) return;
    try {
      const rows = await apiFetch(`/weights/${athleteId}`, token);
      setWeights(Array.isArray(rows) ? rows : []);
    } catch { setWeights([]); }
    setLoading(false);
  };

  useEffect(() => { setLoading(true); load(); }, [athleteId, token]);

  const filtered = weights
    .filter(w => {
      const d = new Date(w.date);
      const cutoff = new Date(); cutoff.setDate(cutoff.getDate() - range);
      return d >= cutoff;
    })
    .sort((a, b) => a.date.localeCompare(b.date));

  const chartData = filtered.map(w => ({ date: w.date, value: Number(w.kg) }));
  const latest = chartData[chartData.length - 1]?.value;
  const oldest = chartData[0]?.value;
  const change = (latest && oldest) ? (latest - oldest).toFixed(1) : null;

  const rangeOptions = [{ v: 7, l: "7D" }, { v: 14, l: "14D" }, { v: 30, l: "30D" }, { v: 90, l: "90D" }, { v: 365, l: "1Y" }];

  return (
    <div style={{ background: T.card, border: `1px solid ${T.border}`, borderRadius: 16, padding: 18 }}>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 14 }}>
        <div>
          <div style={{ fontFamily: "Bebas Neue, system-ui", fontSize: 18, letterSpacing: 2, color: T.text }}>WEIGHT TRACKING</div>
          <div style={{ fontFamily: "DM Sans", fontSize: 11, color: T.muted, marginTop: 2 }}>
            {latest ? <>Current: <span style={{ color: T.accent, fontWeight: 700 }}>{latest.toFixed(1)} kg</span></> : "No data"}
            {change !== null && <> · Change: <span style={{ color: Number(change) > 0 ? T.danger : Number(change) < 0 ? T.coachGreen : T.muted, fontWeight: 700 }}>{Number(change) >= 0 ? "+" : ""}{change} kg</span></>}
            {chartData.length > 0 && <> · {chartData.length} entries</>}
          </div>
        </div>
        <div style={{ display: "flex", gap: 4 }}>
          {rangeOptions.map(r => (
            <button key={r.v} onClick={() => setRange(r.v)} style={{
              background: range === r.v ? `${T.accent}22` : "none",
              border: `1px solid ${range === r.v ? T.accent + "55" : T.border}`,
              borderRadius: 6, padding: "4px 10px", color: range === r.v ? T.accent : T.muted,
              fontFamily: "JetBrains Mono, ui-monospace", fontSize: 10, cursor: "pointer",
            }} type="button">{r.l}</button>
          ))}
        </div>
      </div>
      {/* Coach weight entry — today or any past date */}
      <div style={{ background: T.surface, border: `1px solid ${T.border}`, borderRadius: 12, padding: 12, marginBottom: 14 }}>
        <div style={{ display: "flex", gap: 8, alignItems: "end", flexWrap: "wrap" }}>
          <div>
            <label style={labelStyle}>Date</label>
            <input
              type="date"
              value={entryDate}
              max={todayISO}
              onChange={(e) => setEntryDate(e.target.value)}
              style={{ ...inputStyle, width: 150, padding: "7px 10px", fontSize: 12 }}
            />
          </div>
          <div>
            <label style={labelStyle}>Weight (kg)</label>
            <input
              type="number"
              step="0.1"
              value={entryKg}
              onChange={(e) => setEntryKg(e.target.value)}
              onKeyDown={(e) => e.key === "Enter" && saveWeight()}
              placeholder="e.g. 82.4"
              style={{ ...inputStyle, width: 110, padding: "7px 10px", fontSize: 12 }}
            />
          </div>
          <button
            onClick={saveWeight}
            disabled={savingW}
            style={{
              background: T.accent, color: T.bg, border: "none", borderRadius: 8,
              padding: "9px 16px", fontFamily: "Bebas Neue, system-ui", fontSize: 12,
              letterSpacing: 1.5, cursor: savingW ? "default" : "pointer", opacity: savingW ? 0.6 : 1,
            }}
            type="button"
          >
            {savingW ? "SAVING…" : "ADD WEIGHT"}
          </button>
          {(() => {
            const existing = weights.find((w) => w.date === entryDate);
            if (!existing) return null;
            return (
              <span style={{ fontFamily: "DM Sans", fontSize: 10, color: "#f59e0b" }}>
                {Number(existing.kg).toFixed(1)} kg already logged for this date — saving overwrites it
              </span>
            );
          })()}
        </div>
        {entryMsg && (
          <div style={{ fontFamily: "DM Sans", fontSize: 11, color: entryMsg.startsWith("Saved") ? T.coachGreen : T.danger, marginTop: 8 }}>
            {entryMsg}
          </div>
        )}
        <div style={{ fontFamily: "DM Sans", fontSize: 10, color: T.muted, marginTop: 6 }}>
          Backdate the date field to add historic weigh-ins. Athlete entries and coach entries share the same record.
        </div>
      </div>

      {loading ? <div style={{ color: T.muted, fontSize: 12 }}>Loading…</div> : (
        <TimeSeriesChart
          data={chartData}
          color={T.accent}
          yLabel="Weight (kg)"
          yUnit=" kg"
          emptyLabel="No weight entries logged yet."
        />
      )}
    </div>
  );
}

/* ─────────────────────────────────────────────────────────────────────────────
   Athlete Food Log — auto-refreshes every 30s, shows daily cal bar chart + items
────────────────────────────────────────────────────────────────────────────── */
function AthleteFoodLogViewer({ athleteId, token, macroTarget }) {
  const [foodLogs, setFoodLogs] = useState([]);
  const [dailyTotals, setDailyTotals] = useState([]);
  const [plans, setPlans] = useState([]);           // reserved
  const [dateTargets, setDateTargets] = useState([]); // merged per-date targets (override ?? weekday plan)
  const [loading, setLoading] = useState(true);
  const [range, setRange] = useState(7);
  const [expandedDay, setExpandedDay] = useState(null);

  const load = async () => {
    if (!athleteId || !token) return;
    try {
      const today = new Date();
      const start = new Date(today); start.setDate(today.getDate() - range);
      const fmt = (d) => `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
      // Fetch independently so one failing doesn't break the others.
      // /macro-targets returns the MERGED per-date target (per-date override if
      // set, otherwise the coach's per-weekday plan) — the single source of truth.
      let logs = [], totals = [], dts = [];
      try { logs = await apiFetch(`/food-logs/${athleteId}?start=${fmt(start)}&end=${fmt(today)}`, token); } catch {}
      try { totals = await apiFetch(`/daily-totals/${athleteId}?start=${fmt(start)}&end=${fmt(today)}`, token); } catch {}
      try { dts = await apiFetch(`/macro-targets/${athleteId}?start=${fmt(start)}&end=${fmt(today)}`, token); } catch {}
      setFoodLogs(Array.isArray(logs) ? logs : []);
      setDailyTotals(Array.isArray(totals) ? totals : []);
      setDateTargets(Array.isArray(dts) ? dts : []);
    } catch { setFoodLogs([]); setDailyTotals([]); }
    setLoading(false);
  };

  useEffect(() => { setLoading(true); load(); }, [athleteId, token, range]);

  // Auto-refresh every 15s
  useEffect(() => {
    if (!athleteId || !token) return;
    const interval = setInterval(load, 15 * 1000);
    return () => clearInterval(interval);
  }, [athleteId, token, range]);

  // Build merged data: prefer daily_totals, fallback to computing from food items
  const foodsByDate = {};
  foodLogs.forEach(dl => { foodsByDate[dl.date] = dl.foods || []; });

  const totalsMap = {};
  dailyTotals.forEach(d => { totalsMap[d.date] = d; });

  // Merge all dates that have either food logs or daily totals
  const allDates = new Set([
    ...Object.keys(foodsByDate),
    ...Object.keys(totalsMap),
  ]);

  // Merged per-date targets keyed by date
  const targetMap = {};
  dateTargets.forEach((t) => { targetMap[t.date] = t; });

  // UK date helpers
  const ukShort = (iso) => { const [y, m, d] = String(iso).split("-"); return `${d}/${m}`; };
  const ukLong = (iso) => { const [y, m, d] = String(iso).split("-"); return `${d}/${m}/${y}`; };

  // Build unified day data sorted by date
  const dayData = [...allDates].sort().map(date => {
    const foods = foodsByDate[date] || [];
    const dt = totalsMap[date];
    // Compute from food items if daily totals missing
    const cal = dt ? Number(dt.calories || 0) : foods.reduce((s, f) => s + Number(f.calories || 0), 0);
    const p = dt ? Number(dt.protein_g || 0) : foods.reduce((s, f) => s + Number(f.protein_g || f.protein || 0), 0);
    const c = dt ? Number(dt.carbs_g || 0) : foods.reduce((s, f) => s + Number(f.carbs_g || f.carbs || 0), 0);
    const f = dt ? Number(dt.fat_g || 0) : foods.reduce((s, f) => s + Number(f.fat_g || f.fat || 0), 0);
    // Per-day target: coach's per-date override ?? weekday plan ?? header goals fallback
    const t = targetMap[date];
    const target = t ? Number(t.calories || 0) : (macroTarget?.calories || 2000);
    return { date, calories: Math.round(cal), protein: Math.round(p), carbs: Math.round(c), fat: Math.round(f), target, foods };
  });

  const maxTarget = Math.max(...dayData.map(d => d.target), macroTarget?.calories || 2000);
  const barMax = Math.max(maxTarget, ...dayData.map(d => d.calories)) * 1.1 || maxTarget * 1.1;

  const rangeOptions = [{ v: 7, l: "7D" }, { v: 14, l: "14D" }, { v: 30, l: "30D" }];

  return (
    <div style={{ background: T.card, border: `1px solid ${T.border}`, borderRadius: 16, padding: 18 }}>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 14 }}>
        <div>
          <div style={{ fontFamily: "Bebas Neue, system-ui", fontSize: 18, letterSpacing: 2, color: T.text }}>FOOD LOG</div>
          <div style={{ fontFamily: "DM Sans", fontSize: 11, color: T.muted, marginTop: 2 }}>
            Auto-refreshes every 15s · Click a day to expand items
          </div>
        </div>
        <div style={{ display: "flex", gap: 4, alignItems: "center" }}>
          <div style={{ width: 6, height: 6, borderRadius: "50%", background: T.coachGreen, animation: "pulse 2s infinite" }} />
          <span style={{ fontFamily: "DM Sans", fontSize: 10, color: T.coachGreen, marginRight: 8 }}>LIVE</span>
          {rangeOptions.map(r => (
            <button key={r.v} onClick={() => setRange(r.v)} style={{
              background: range === r.v ? `${T.accent}22` : "none",
              border: `1px solid ${range === r.v ? T.accent + "55" : T.border}`,
              borderRadius: 6, padding: "4px 10px", color: range === r.v ? T.accent : T.muted,
              fontFamily: "JetBrains Mono, ui-monospace", fontSize: 10, cursor: "pointer",
            }} type="button">{r.l}</button>
          ))}
        </div>
      </div>

      {loading ? <div style={{ color: T.muted, fontSize: 12 }}>Loading…</div> : dayData.length === 0 ? (
        <div style={{ color: T.muted, fontSize: 12 }}>No food logged in this period.</div>
      ) : (
        <>
          {/* Daily calorie bar chart */}
          <div style={{ marginBottom: 16 }}>
            <div style={{ display: "flex", alignItems: "flex-end", gap: 2, height: 100 }}>
              {dayData.map((d) => {
                const pct = (d.calories / barMax) * 100;
                const over = d.calories > d.target;
                const targetPct = (d.target / barMax) * 100;
                const isExpanded = expandedDay === d.date;
                return (
                  <div key={d.date} style={{ flex: 1, display: "flex", flexDirection: "column", alignItems: "center", cursor: "pointer" }}
                    onClick={() => setExpandedDay(isExpanded ? null : d.date)}>
                    <div style={{ fontSize: 8, fontFamily: "JetBrains Mono, ui-monospace", color: T.muted, marginBottom: 2 }}>
                      {d.calories > 0 ? d.calories : ""}
                    </div>
                    <div style={{ width: "100%", position: "relative", height: 70 }}>
                      <div style={{ position: "absolute", bottom: `${targetPct * 0.7}%`, left: 0, right: 0, height: 1, background: `${T.coachGreen}66`, zIndex: 2 }} />
                      <div style={{
                        position: "absolute", bottom: 0, left: "10%", right: "10%",
                        height: `${Math.max(pct * 0.7, 2)}%`,
                        background: over ? `${T.danger}cc` : isExpanded ? T.accent : `${T.accent}88`,
                        borderRadius: "3px 3px 0 0", transition: "all .2s",
                      }} />
                    </div>
                    <div style={{ fontSize: 7, fontFamily: "JetBrains Mono, ui-monospace", color: isExpanded ? T.accent : T.muted, marginTop: 2 }}>
                      {ukShort(d.date)}
                    </div>
                  </div>
                );
              })}
            </div>
            <div style={{ display: "flex", gap: 14, marginTop: 6 }}>
              <span style={{ fontSize: 9, color: T.muted, fontFamily: "DM Sans" }}>
                <span style={{ display: "inline-block", width: 10, height: 2, background: T.coachGreen, marginRight: 4, verticalAlign: "middle" }} />
                Target line per day — from your macro plan{dateTargets.some(t => t.source === "override") ? " (incl. day overrides)" : ""}
              </span>
            </div>
          </div>

          {/* Expanded food items for selected day */}
          {expandedDay && (
            <div style={{ background: T.surface, border: `1px solid ${T.border}`, borderRadius: 12, padding: 14, marginBottom: 12, animation: "fadeUp .15s ease" }}>
              <div style={{ fontFamily: "Bebas Neue, system-ui", fontSize: 14, letterSpacing: 1.5, color: T.accent, marginBottom: 8 }}>{ukLong(expandedDay)}</div>
              {(() => {
                const dd = dayData.find(d => d.date === expandedDay);
                const foods = dd?.foods || [];
                if (foods.length === 0) return <div style={{ fontSize: 11, color: T.muted }}>No individual food items recorded.</div>;

                // Group foods by meal so light meals (e.g. pre-training) stand out.
                const MEAL_ORDER = ["Breakfast", "Lunch", "Dinner", "Snacks"];
                const norm = (m) => {
                  const s = String(m || "").toLowerCase();
                  if (s.startsWith("break")) return "Breakfast";
                  if (s.startsWith("lunch")) return "Lunch";
                  if (s.startsWith("dinner") || s.startsWith("tea")) return "Dinner";
                  if (s.startsWith("snack")) return "Snacks";
                  return "Other";
                };
                const groups = {};
                foods.forEach((f) => {
                  const g = norm(f.meal);
                  (groups[g] = groups[g] || []).push(f);
                });
                const mealNames = [...MEAL_ORDER.filter((m) => groups[m]), ...(groups["Other"] ? ["Other"] : [])];
                const mealTotals = (items) => items.reduce((a, f) => ({
                  cal: a.cal + Number(f.calories || 0),
                  p: a.p + Number(f.protein_g || f.protein || 0),
                  c: a.c + Number(f.carbs_g || f.carbs || 0),
                  f: a.f + Number(f.fat_g || f.fat || 0),
                }), { cal: 0, p: 0, c: 0, f: 0 });

                return (
                  <>
                    {/* Day totals vs that day's target */}
                    <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", background: T.card, border: `1px solid ${T.border}`, borderRadius: 8, padding: "8px 10px", marginBottom: 10 }}>
                      <span style={{ fontSize: 10, color: T.text, fontFamily: "JetBrains Mono, ui-monospace" }}>
                        DAY: {dd.calories} cal · P {dd.protein}g · C {dd.carbs}g · F {dd.fat}g
                      </span>
                      <span style={{ fontSize: 10, fontFamily: "JetBrains Mono, ui-monospace", color: dd.calories > dd.target ? T.danger : T.coachGreen }}>
                        target {dd.target}
                      </span>
                    </div>

                    {mealNames.map((mealName) => {
                      const items = groups[mealName];
                      const mt = mealTotals(items);
                      return (
                        <div key={mealName} style={{ marginBottom: 10 }}>
                          <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 4 }}>
                            <span style={{ fontFamily: "Bebas Neue, system-ui", fontSize: 12, letterSpacing: 1.5, color: T.text }}>{mealName.toUpperCase()}</span>
                            <span style={{ fontSize: 9, color: T.accent, fontFamily: "JetBrains Mono, ui-monospace" }}>
                              {Math.round(mt.cal)} cal · {Math.round(mt.p)}p · {Math.round(mt.c)}c · {Math.round(mt.f)}f
                            </span>
                          </div>
                          {items.map((f, j) => (
                            <div key={j} style={{ display: "flex", justifyContent: "space-between", padding: "3px 0 3px 10px", borderBottom: `1px solid ${T.border}20`, fontSize: 11 }}>
                              <span style={{ color: T.text }}>{f.name}</span>
                              <span style={{ color: T.muted, fontFamily: "JetBrains Mono, ui-monospace", fontSize: 10 }}>
                                {Math.round(f.calories || 0)} · {Math.round(Number(f.protein_g || f.protein || 0))}p · {Math.round(Number(f.carbs_g || f.carbs || 0))}c · {Math.round(Number(f.fat_g || f.fat || 0))}f
                              </span>
                            </div>
                          ))}
                        </div>
                      );
                    })}
                  </>
                );
              })()}
            </div>
          )}
        </>
      )}
    </div>
  );
}

/* ─────────────────────────────────────────────────────────────────────────────
   Athlete Video Manager — send YouTube videos to athlete
────────────────────────────────────────────────────────────────────────────── */
function AthleteVideoManager({ athleteId, token }) {
  const [videos, setVideos] = useState([]);
  const [loading, setLoading] = useState(true);
  const [form, setForm] = useState({ title: "", url: "", category: "General", notes: "" });
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState("");

  const loadVideos = async () => {
    try {
      const rows = await apiFetch(`/coach-videos/${athleteId}`, token);
      setVideos(Array.isArray(rows) ? rows : []);
    } catch { setVideos([]); }
  };

  useEffect(() => {
    if (!athleteId || !token) return;
    (async () => {
      setLoading(true);
      await loadVideos();
      setLoading(false);
    })();
  }, [athleteId, token]);

  // Extract the 11-char YouTube ID from any valid URL/ID for preview purposes
  const extractId = (input) => {
    if (!input) return null;
    const s = String(input).trim();
    if (/^[A-Za-z0-9_-]{11}$/.test(s)) return s;
    let m = s.match(/[?&]v=([A-Za-z0-9_-]{11})/);
    if (m) return m[1];
    m = s.match(/youtu\.be\/([A-Za-z0-9_-]{11})/);
    if (m) return m[1];
    m = s.match(/\/(?:embed|shorts|v)\/([A-Za-z0-9_-]{11})/);
    if (m) return m[1];
    return null;
  };

  const previewId = extractId(form.url);

  const addVideo = async () => {
    setError("");
    if (!form.title.trim()) { setError("Title is required"); return; }
    if (!previewId) { setError("Paste a valid YouTube URL (e.g. https://youtu.be/…) "); return; }
    setSaving(true);
    try {
      await apiFetch(`/coach-videos/${athleteId}`, token, {
        method: "POST",
        body: JSON.stringify({
          title: form.title.trim(),
          url: form.url.trim(),
          category: form.category,
          notes: form.notes.trim() || null,
        }),
      });
      setForm({ title: "", url: "", category: "General", notes: "" });
      await loadVideos();
    } catch (e) { setError(e.message || "Could not send video"); }
    setSaving(false);
  };

  const deleteVideo = async (id) => {
    if (!confirm("Remove this video from the athlete's dashboard?")) return;
    try {
      await apiFetch(`/coach-videos/${athleteId}/${id}`, token, { method: "DELETE" });
      await loadVideos();
    } catch (e) { alert(e.message || "Could not delete"); }
  };

  const CATEGORIES = ["General", "Technique", "Nutrition", "Mindset", "Recovery", "Warmup"];

  return (
    <div style={{ background: T.card, border: `1px solid ${T.border}`, borderRadius: 16, padding: 18 }}>
      <div style={{ fontFamily: "Bebas Neue, system-ui", fontSize: 18, letterSpacing: 2, color: T.text, marginBottom: 4 }}>SEND VIDEO</div>
      <div style={{ fontFamily: "DM Sans", fontSize: 11, color: T.muted, marginBottom: 16 }}>
        Share a YouTube video with the athlete — it'll appear on their dashboard.
      </div>

      {/* Add video form */}
      <div style={{ background: T.surface, border: `1px solid ${T.border}`, borderRadius: 12, padding: 14, marginBottom: 16 }}>
        <div style={{ display: "grid", gridTemplateColumns: "2fr 1fr", gap: 8, marginBottom: 8 }}>
          <div>
            <label style={labelStyle}>Title *</label>
            <input value={form.title} onChange={(e) => setForm(p => ({ ...p, title: e.target.value }))} placeholder="e.g. Squat technique breakdown" style={inputStyle} />
          </div>
          <div>
            <label style={labelStyle}>Category</label>
            <select value={form.category} onChange={(e) => setForm(p => ({ ...p, category: e.target.value }))} style={inputStyle}>
              {CATEGORIES.map(c => <option key={c} value={c}>{c}</option>)}
            </select>
          </div>
        </div>
        <div style={{ marginBottom: 8 }}>
          <label style={labelStyle}>YouTube URL *</label>
          <input
            value={form.url}
            onChange={(e) => setForm(p => ({ ...p, url: e.target.value }))}
            placeholder="https://www.youtube.com/watch?v=… or https://youtu.be/…"
            style={inputStyle}
          />
        </div>
        {previewId && (
          <div style={{ marginBottom: 8, display: "flex", gap: 10, alignItems: "center", background: T.bg, border: `1px solid ${T.border}`, borderRadius: 8, padding: 8 }}>
            <img src={`https://img.youtube.com/vi/${previewId}/default.jpg`} alt="Preview" style={{ width: 80, height: 60, borderRadius: 4, objectFit: "contain" }} />
            <div style={{ fontFamily: "DM Sans", fontSize: 11, color: T.coachGreen }}>
              ✓ Video detected — ID: <span style={{ fontFamily: "JetBrains Mono, ui-monospace" }}>{previewId}</span>
            </div>
          </div>
        )}
        <div style={{ marginBottom: 10 }}>
          <label style={labelStyle}>Notes (optional)</label>
          <input value={form.notes} onChange={(e) => setForm(p => ({ ...p, notes: e.target.value }))} placeholder="Any context or instructions for the athlete" style={inputStyle} />
        </div>
        {error && (
          <div style={{ background: `${T.danger}18`, border: `1px solid ${T.danger}44`, borderRadius: 8, padding: "8px 12px", marginBottom: 10, fontSize: 11, color: T.danger, fontFamily: "DM Sans" }}>
            {error}
          </div>
        )}
        <div style={{ display: "flex", justifyContent: "flex-end" }}>
          <button onClick={addVideo} disabled={saving || !form.title.trim() || !previewId} style={{
            background: form.title.trim() && previewId ? T.accent : T.border,
            color: form.title.trim() && previewId ? T.bg : T.muted,
            border: "none", borderRadius: 10, padding: "10px 20px",
            fontFamily: "Bebas Neue, system-ui", fontSize: 13, letterSpacing: 1.5,
            cursor: form.title.trim() && previewId && !saving ? "pointer" : "default",
          }} type="button">{saving ? "SENDING…" : "📹 SEND VIDEO"}</button>
        </div>
      </div>

      {/* Existing videos list */}
      <div style={{ fontFamily: "DM Sans", fontSize: 10, color: T.muted, letterSpacing: 1, textTransform: "uppercase", marginBottom: 8 }}>
        Sent videos ({videos.length})
      </div>
      {loading ? (
        <div style={{ color: T.muted, fontSize: 12 }}>Loading…</div>
      ) : videos.length === 0 ? (
        <div style={{ color: T.muted, fontSize: 12, textAlign: "center", padding: 20 }}>
          No videos sent yet. Share one above to get started.
        </div>
      ) : (
        <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fill, minmax(220px, 1fr))", gap: 10, maxHeight: 500, overflowY: "auto" }}>
          {videos.map((v) => (
            <div key={v.id} style={{ background: T.surface, border: `1px solid ${T.border}`, borderRadius: 10, overflow: "hidden", position: "relative" }}>
              <div style={{ position: "relative", paddingBottom: "56.25%", background: "#000" }}>
                <img
                  src={`https://img.youtube.com/vi/${v.youtube_id}/mqdefault.jpg`}
                  alt={v.title}
                  style={{ position: "absolute", inset: 0, width: "100%", height: "100%", objectFit: "contain" }}
                />
                <a
                  href={`https://www.youtube.com/watch?v=${v.youtube_id}`}
                  target="_blank"
                  rel="noopener noreferrer"
                  style={{ position: "absolute", inset: 0, display: "flex", alignItems: "center", justifyContent: "center", textDecoration: "none" }}
                >
                  <div style={{ width: 42, height: 42, borderRadius: "50%", background: "rgba(0,0,0,0.7)", display: "flex", alignItems: "center", justifyContent: "center", fontSize: 18, color: "#fff" }}>▶</div>
                </a>
              </div>
              <div style={{ padding: 10 }}>
                <div style={{ fontFamily: "DM Sans", fontSize: 12, fontWeight: 600, color: T.text, lineHeight: 1.3, marginBottom: 6, display: "-webkit-box", WebkitLineClamp: 2, WebkitBoxOrient: "vertical", overflow: "hidden" }}>
                  {v.title}
                </div>
                <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", gap: 6 }}>
                  <span style={{ background: `${T.accent}22`, color: T.accent, borderRadius: 4, padding: "2px 6px", fontFamily: "DM Sans", fontSize: 9, fontWeight: 600 }}>
                    {v.category || "General"}
                  </span>
                  <button onClick={() => deleteVideo(v.id)} style={{
                    background: "none", border: `1px solid ${T.danger}44`, borderRadius: 4,
                    padding: "2px 8px", color: T.danger, fontSize: 9, cursor: "pointer",
                  }} type="button">✕</button>
                </div>
                {v.notes && (
                  <div style={{ fontFamily: "DM Sans", fontSize: 10, color: T.muted, marginTop: 6, lineHeight: 1.4 }}>
                    {v.notes}
                  </div>
                )}
                {v.created_at && (
                  <div style={{ fontFamily: "JetBrains Mono, ui-monospace", fontSize: 9, color: T.border, marginTop: 6 }}>
                    {new Date(v.created_at).toLocaleDateString("en-GB", { day: "numeric", month: "short", year: "numeric" })}
                  </div>
                )}
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

/* ─────────────────────────────────────────────────────────────────────────────
   Athlete Check-in Manager — view + add coach check-in notes
────────────────────────────────────────────────────────────────────────────── */
function AthleteCheckInManager({ athleteId, token }) {
  const [checkins, setCheckins] = useState([]);
  const [loading, setLoading] = useState(true);
  const [form, setForm] = useState({ date: "", time: "", title: "", notes: "", linkUrl: "", repeatWeekly: false, repeatWeeks: 12 });
  const [saving, setSaving] = useState(false);

  const loadCheckins = async () => {
    try {
      const rows = await apiFetch(`/checkins/${athleteId}`, token);
      setCheckins(Array.isArray(rows) ? rows : []);
    } catch { setCheckins([]); }
  };

  useEffect(() => {
    if (!athleteId || !token) return;
    (async () => {
      setLoading(true);
      await loadCheckins();
      setLoading(false);
    })();
  }, [athleteId, token]);

  const addCheckin = async () => {
    if (!form.date || !form.notes.trim()) return;
    setSaving(true);
    try {
      await apiFetch(`/checkins/${athleteId}`, token, {
        method: "POST",
        body: JSON.stringify({
          date: form.date,
          time: form.time || null,
          title: form.title.trim() || "Check-in",
          notes: form.notes.trim(),
          linkUrl: form.linkUrl.trim() || null,
        }),
      });
      setForm({ date: "", time: "", title: "", notes: "", linkUrl: "" });
      await loadCheckins();
    } catch (e) { alert(e.message || "Could not save check-in"); }
    setSaving(false);
  };

  const deleteCheckin = async (id) => {
    if (!confirm("Delete this check-in note?")) return;
    try {
      await apiFetch(`/checkins/${athleteId}/${id}`, token, { method: "DELETE" });
      await loadCheckins();
    } catch (e) { alert(e.message || "Could not delete"); }
  };

  return (
    <div style={{ background: T.card, border: `1px solid ${T.border}`, borderRadius: 16, padding: 18 }}>
      <div style={{ fontFamily: "Bebas Neue, system-ui", fontSize: 18, letterSpacing: 2, color: T.text, marginBottom: 4 }}>CHECK-IN NOTES</div>
      <div style={{ fontFamily: "DM Sans", fontSize: 11, color: T.muted, marginBottom: 16 }}>
        Notes logged after each check-in call or review. Visible to the athlete in their Check-ins tab.
      </div>

      {/* Add check-in form */}
      <div style={{ background: T.surface, border: `1px solid ${T.border}`, borderRadius: 12, padding: 14, marginBottom: 16 }}>
        <div style={{ fontFamily: "DM Sans", fontSize: 11, color: T.accent, fontWeight: 600, marginBottom: 10, letterSpacing: 1, textTransform: "uppercase" }}>+ NEW CHECK-IN</div>
        <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr 2fr", gap: 8, marginBottom: 8 }}>
          <div>
            <label style={labelStyle}>Date *</label>
            <input type="date" value={form.date} onChange={(e) => setForm(p => ({ ...p, date: e.target.value }))} style={inputStyle} />
          </div>
          <div>
            <label style={labelStyle}>Time</label>
            <input type="time" value={form.time} onChange={(e) => setForm(p => ({ ...p, time: e.target.value }))} style={inputStyle} />
          </div>
          <div>
            <label style={labelStyle}>Title</label>
            <input value={form.title} onChange={(e) => setForm(p => ({ ...p, title: e.target.value }))} placeholder="e.g. Weekly Review" style={inputStyle} />
          </div>
        </div>
        <div style={{ marginBottom: 8 }}>
          <label style={labelStyle}>Notes *</label>
          <textarea
            value={form.notes}
            onChange={(e) => setForm(p => ({ ...p, notes: e.target.value }))}
            placeholder="What did you discuss? What's the plan going forward?"
            rows={4}
            style={{ ...inputStyle, resize: "vertical", minHeight: 80, fontFamily: "DM Sans" }}
          />
        </div>
        <div style={{ display: "flex", gap: 10, alignItems: "center", marginBottom: 8, flexWrap: "wrap" }}>
          <label style={{ display: "flex", alignItems: "center", gap: 6, fontFamily: "DM Sans", fontSize: 12, color: T.text, cursor: "pointer" }}>
            <input
              type="checkbox"
              checked={!!form.repeatWeekly}
              onChange={(e) => setForm(p => ({ ...p, repeatWeekly: e.target.checked }))}
            />
            ↻ Repeat weekly (same day &amp; time)
          </label>
          {form.repeatWeekly && (
            <select
              value={form.repeatWeeks}
              onChange={(e) => setForm(p => ({ ...p, repeatWeeks: Number(e.target.value) }))}
              style={{ background: T.surface, border: `1px solid ${T.border}`, borderRadius: 8, padding: "6px 8px", color: T.text, fontFamily: "DM Sans", fontSize: 11 }}
            >
              <option value={4}>for 4 weeks</option>
              <option value={8}>for 8 weeks</option>
              <option value={12}>for 12 weeks</option>
              <option value={26}>for 26 weeks</option>
              <option value={52}>for 52 weeks</option>
            </select>
          )}
        </div>
        <div style={{ display: "flex", gap: 8, alignItems: "end" }}>
          <div style={{ flex: 1 }}>
            <label style={labelStyle}>Google Meet / video link (optional)</label>
            <input value={form.linkUrl} onChange={(e) => setForm(p => ({ ...p, linkUrl: e.target.value }))} placeholder="https://meet.google.com/…" style={inputStyle} />
          </div>
          <button onClick={addCheckin} disabled={saving || !form.date || !form.notes.trim()} style={{
            background: form.date && form.notes.trim() ? T.accent : T.border,
            color: form.date && form.notes.trim() ? T.bg : T.muted,
            border: "none", borderRadius: 10, padding: "11px 18px",
            fontFamily: "Bebas Neue, system-ui", fontSize: 13, letterSpacing: 1.5,
            cursor: form.date && form.notes.trim() && !saving ? "pointer" : "default",
          }} type="button">{saving ? "SAVING…" : "SAVE"}</button>
        </div>
      </div>

      {/* List existing check-ins */}
      {loading ? (
        <div style={{ color: T.muted, fontSize: 12 }}>Loading…</div>
      ) : checkins.length === 0 ? (
        <div style={{ color: T.muted, fontSize: 12, textAlign: "center", padding: 20 }}>No check-ins logged yet.</div>
      ) : (
        <div style={{ maxHeight: 500, overflowY: "auto", display: "flex", flexDirection: "column", gap: 10 }}>
          {[...checkins].reverse().map((c) => (
            <div key={c.id} style={{ background: T.surface, border: `1px solid ${T.border}`, borderRadius: 12, padding: 14 }}>
              <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 8 }}>
                <div style={{ display: "flex", alignItems: "center", gap: 10 }}>
                  <span style={{ background: `${T.coachGreen}22`, border: `1px solid ${T.coachGreen}44`, borderRadius: 6, padding: "3px 10px", fontFamily: "JetBrains Mono, ui-monospace", fontSize: 10, color: T.coachGreen, fontWeight: 600 }}>
                    {String(c.date).split("-").reverse().join("/")}
                  </span>
                  <span style={{ fontFamily: "Bebas Neue, system-ui", fontSize: 14, letterSpacing: 1, color: T.text }}>{c.title}</span>
                  {c.seriesId && (
                    <span style={{ fontFamily: "DM Sans", fontSize: 9, color: T.coachGreen, border: `1px solid ${T.coachGreen}55`, borderRadius: 6, padding: "1px 6px" }}>
                      ↻ WEEKLY
                    </span>
                  )}
                </div>
                <span style={{ display: "flex", gap: 5 }}>
                  {c.seriesId && (
                    <button
                      onClick={async () => {
                        if (!window.confirm("End this weekly series? This and all FUTURE occurrences are removed; past check-ins are kept.")) return;
                        try {
                          await apiFetch(`/checkins/${athleteId}/series/${c.seriesId}?from=${c.date}`, token, { method: "DELETE" });
                          loadCheckins();
                        } catch (e) { alert(e.message || "Could not end the series"); }
                      }}
                      style={{ background: "none", border: `1px solid ${T.border}`, borderRadius: 6, padding: "4px 8px", color: T.muted, fontSize: 10, cursor: "pointer" }}
                      type="button"
                      title="End the weekly series from this date"
                    >
                      ↻ end series
                    </button>
                  )}
                  <button onClick={() => deleteCheckin(c.id)} style={{
                    background: "none", border: `1px solid ${T.danger}44`, borderRadius: 6,
                    padding: "4px 8px", color: T.danger, fontSize: 10, cursor: "pointer",
                  }} type="button" title="Delete just this occurrence">✕</button>
                </span>
              </div>
              {c.notes && (
                <div style={{ fontFamily: "DM Sans", fontSize: 12, color: T.text, lineHeight: 1.6, whiteSpace: "pre-wrap", marginBottom: c.linkUrl ? 8 : 0 }}>
                  {c.notes}
                </div>
              )}
              {c.linkUrl && (
                <a href={c.linkUrl} target="_blank" rel="noopener noreferrer" style={{ fontFamily: "DM Sans", fontSize: 11, color: T.accent, textDecoration: "none" }}>
                  🔗 {c.linkUrl}
                </a>
              )}
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

/* ─────────────────────────────────────────────────────────────────────────────
   Meal Planner — coach plans meals per date (month ahead) with batch copy.
   Sources: athlete's logged history, custom foods DB, OpenFoodFacts.
────────────────────────────────────────────────────────────────────────────── */
const PLAN_SLOTS = ["Breakfast", "Lunch", "Dinner", "Snack"];
const emptyPlanDay = () => ({ Breakfast: [], Lunch: [], Dinner: [], Snack: [] });

function MealPlannerTab({ athleteId, token }) {
  const fmt = (d) => `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
  const ukShort = (iso) => { const [, m, d] = String(iso).split("-"); return `${d}/${m}`; };
  const ukLong = (iso) => String(iso).split("-").reverse().join("/");
  const addDays = (iso, n) => { const d = new Date(iso + "T00:00:00"); d.setDate(d.getDate() + n); return fmt(d); };
  const todayStr = fmt(new Date());

  // 31-day window from today
  const dates = [...Array(31)].map((_, i) => addDays(todayStr, i));

  const [planned, setPlanned] = useState({});      // date -> meals
  const [selDate, setSelDate] = useState(todayStr);
  const [dayMeals, setDayMeals] = useState(emptyPlanDay());
  const [dirty, setDirty] = useState(false);
  const [saving, setSaving] = useState(false);
  const [loading, setLoading] = useState(true);

  // Picker state
  const [pickerSlot, setPickerSlot] = useState(null); // which meal slot the picker is open for
  const [q, setQ] = useState("");
  const [results, setResults] = useState([]);
  const [searching, setSearching] = useState(false);
  const [grams, setGrams] = useState("100");
  const [selFood, setSelFood] = useState(null);     // per-100g food selected from search
  const [recentFoods, setRecentFoods] = useState([]); // athlete's logged foods (fixed portions)
  const [historyDays, setHistoryDays] = useState([]); // athlete's logged days for import
  const [showImport, setShowImport] = useState(false);
  const [copyMsg, setCopyMsg] = useState("");

  const load = async () => {
    setLoading(true);
    try {
      let rows = [], logs = [];
      try { rows = await apiFetch(`/planned-meals/${athleteId}?start=${dates[0]}&end=${dates[30]}`, token); } catch {}
      const histStart = addDays(todayStr, -30);
      try { logs = await apiFetch(`/food-logs/${athleteId}?start=${histStart}&end=${todayStr}`, token); } catch {}
      const map = {};
      (Array.isArray(rows) ? rows : []).forEach((r) => { map[r.date] = r.meals || {}; });
      setPlanned(map);
      // Recent foods: dedupe athlete's logged items by name (fixed portions)
      const seen = new Set(); const rec = [];
      (Array.isArray(logs) ? logs : []).sort((a,b) => b.date.localeCompare(a.date)).forEach((dl) => {
        (dl.foods || []).forEach((f) => {
          const key = String(f.name || "").toLowerCase();
          if (!key || seen.has(key)) return;
          seen.add(key);
          rec.push({ name: f.name, grams: Number(f.grams || 0) || null, calories: Number(f.calories || 0), protein_g: Number(f.protein_g ?? f.protein ?? 0), carbs_g: Number(f.carbs_g ?? f.carbs ?? 0), fat_g: Number(f.fat_g ?? f.fat ?? 0) });
        });
      });
      setRecentFoods(rec.slice(0, 30));
      setHistoryDays((Array.isArray(logs) ? logs : []).filter((dl) => (dl.foods || []).length > 0).map((dl) => dl.date).sort().reverse());
    } catch {}
    setLoading(false);
  };
  useEffect(() => { if (athleteId && token) load(); }, [athleteId, token]);

  // Sync editor when the selected date or loaded plans change
  useEffect(() => {
    const m = planned[selDate];
    setDayMeals(m ? { ...emptyPlanDay(), ...m } : emptyPlanDay());
    setDirty(false);
    setPickerSlot(null);
  }, [selDate, planned]);

  // Debounced food search (custom foods DB + OpenFoodFacts)
  useEffect(() => {
    const term = q.trim();
    if (term.length < 2) { setResults([]); setSearching(false); return; }
    setSearching(true);
    const t = setTimeout(async () => {
      try {
        let custom = [], off = [];
        try { const r = await apiFetch(`/foods/search?q=${encodeURIComponent(term)}`, token); custom = Array.isArray(r) ? r : (r?.foods || []); } catch {}
        try { const r = await apiFetch(`/off/search?q=${encodeURIComponent(term)}`, token); off = r?.products || []; } catch {}
        const mapped = [
          ...custom.map((f) => ({ name: f.name, per100: { calories: Number(f.calories || 0), protein_g: Number(f.protein_g || 0), carbs_g: Number(f.carbs_g || 0), fat_g: Number(f.fat_g || 0) }, src: "DB" })),
          ...off.map((p) => ({ name: p.brand ? `${p.name} (${p.brand})` : p.name, per100: { calories: Number(p.calories || 0), protein_g: Number(p.protein || 0), carbs_g: Number(p.carbs || 0), fat_g: Number(p.fat || 0) }, src: "OFF" })),
        ].filter((x) => x.name);
        setResults(mapped.slice(0, 20));
      } catch {}
      setSearching(false);
    }, 400);
    return () => clearTimeout(t);
  }, [q, token]);

  const dayTotals = PLAN_SLOTS.reduce((a, s) => {
    (dayMeals[s] || []).forEach((i) => { a.cal += i.calories; a.p += i.protein_g; a.c += i.carbs_g; a.f += i.fat_g; });
    return a;
  }, { cal: 0, p: 0, c: 0, f: 0 });

  const addItem = (slot, item) => {
    setDayMeals((prev) => ({ ...prev, [slot]: [...(prev[slot] || []), item] }));
    setDirty(true);
  };
  const removeItem = (slot, idx) => {
    setDayMeals((prev) => ({ ...prev, [slot]: prev[slot].filter((_, i) => i !== idx) }));
    setDirty(true);
  };

  const addSearchFood = () => {
    if (!selFood || !pickerSlot) return;
    const g = Math.max(1, Number(grams) || 100);
    const r = g / 100;
    addItem(pickerSlot, {
      name: `${selFood.name} (${g}g)`,
      grams: g,
      calories: Math.round(selFood.per100.calories * r),
      protein_g: Math.round(selFood.per100.protein_g * r * 10) / 10,
      carbs_g: Math.round(selFood.per100.carbs_g * r * 10) / 10,
      fat_g: Math.round(selFood.per100.fat_g * r * 10) / 10,
    });
    setSelFood(null); setQ(""); setResults([]); setGrams("100");
  };

  const saveDay = async () => {
    setSaving(true);
    try {
      await apiFetch(`/planned-meals/${athleteId}`, token, {
        method: "PUT",
        body: JSON.stringify({ date: selDate, meals: dayMeals }),
      });
      setPlanned((prev) => ({ ...prev, [selDate]: dayMeals }));
      setDirty(false);
    } catch (e) { alert(e.message || "Could not save"); }
    setSaving(false);
  };

  const clearDay = async () => {
    if (!window.confirm(`Clear the planned meals for ${ukLong(selDate)}?`)) return;
    try {
      await apiFetch(`/planned-meals/${athleteId}/${selDate}`, token, { method: "DELETE" });
      setPlanned((prev) => { const n = { ...prev }; delete n[selDate]; return n; });
    } catch (e) { alert(e.message); }
  };

  const importLoggedDay = async (fromDate) => {
    try {
      const logs = await apiFetch(`/food-logs/${athleteId}?start=${fromDate}&end=${fromDate}`, token);
      const dl = (Array.isArray(logs) ? logs : [])[0];
      if (!dl || !(dl.foods || []).length) { alert("Nothing logged that day."); return; }
      const next = emptyPlanDay();
      dl.foods.forEach((f) => {
        const slot = PLAN_SLOTS.includes(f.meal) ? f.meal : (String(f.meal || "").toLowerCase().startsWith("snack") ? "Snack" : "Snack");
        next[slot].push({ name: f.name, grams: Number(f.grams || 0) || null, calories: Number(f.calories || 0), protein_g: Number(f.protein_g ?? f.protein ?? 0), carbs_g: Number(f.carbs_g ?? f.carbs ?? 0), fat_g: Number(f.fat_g ?? f.fat ?? 0) });
      });
      setDayMeals(next);
      setDirty(true);
      setShowImport(false);
    } catch (e) { alert(e.message); }
  };

  const doCopy = async (toDates, label) => {
    if (dirty) { alert("Save this day first, then copy it."); return; }
    if (!planned[selDate]) { alert("Nothing saved on this day to copy yet — save it first."); return; }
    try {
      const r = await apiFetch(`/planned-meals/${athleteId}/copy`, token, {
        method: "POST",
        body: JSON.stringify({ fromDate: selDate, toDates }),
      });
      setCopyMsg(`Copied to ${r.copied} day(s) — ${label}`);
      setTimeout(() => setCopyMsg(""), 3000);
      await load();
    } catch (e) { alert(e.message || "Copy failed"); }
  };

  const copyNextNDays = (n) => doCopy([...Array(n)].map((_, i) => addDays(selDate, i + 1)), `next ${n} days`);
  const copyWeekForward = (weeks) => {
    // Copy this date's WHOLE WEEK (each saved day of the week containing selDate)
    // onto the following N weeks, weekday-for-weekday.
    const d = new Date(selDate + "T00:00:00");
    const daysSinceMon = (d.getDay() + 6) % 7;
    const monday = addDays(selDate, -daysSinceMon);
    (async () => {
      let copiedTotal = 0;
      for (let i = 0; i < 7; i++) {
        const src = addDays(monday, i);
        if (!planned[src]) continue;
        const targets = [...Array(weeks)].map((_, w) => addDays(src, 7 * (w + 1)));
        try {
          const r = await apiFetch(`/planned-meals/${athleteId}/copy`, token, {
            method: "POST",
            body: JSON.stringify({ fromDate: src, toDates: targets }),
          });
          copiedTotal += r.copied || 0;
        } catch {}
      }
      setCopyMsg(`Week copied forward ${weeks} week(s) — ${copiedTotal} day(s) written`);
      setTimeout(() => setCopyMsg(""), 3500);
      await load();
    })();
  };

  return (
    <div style={{ background: T.card, border: `1px solid ${T.border}`, borderRadius: 16, padding: 18 }}>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 4 }}>
        <div style={{ fontFamily: "Bebas Neue, system-ui", fontSize: 18, letterSpacing: 2, color: T.text }}>MEAL PLANNER</div>
        {copyMsg && <span style={{ fontSize: 11, color: T.coachGreen, fontFamily: "DM Sans" }}>{copyMsg}</span>}
      </div>
      <div style={{ fontFamily: "DM Sans", fontSize: 11, color: T.muted, marginBottom: 12 }}>
        Plan meals up to a month ahead. Build a day, save it, then copy it across days or weeks.
      </div>

      {/* Date strip */}
      <div style={{ display: "flex", gap: 4, overflowX: "auto", paddingBottom: 8, marginBottom: 14 }}>
        {dates.map((d) => {
          const has = !!planned[d];
          const sel = d === selDate;
          return (
            <button key={d} onClick={() => { if (dirty && !window.confirm("Discard unsaved changes on this day?")) return; setSelDate(d); }} style={{
              minWidth: 52, padding: "7px 4px", borderRadius: 9,
              border: `1px solid ${sel ? T.accent : has ? T.coachGreen + "66" : T.border}`,
              background: sel ? `${T.accent}22` : "none",
              color: sel ? T.accent : T.text, cursor: "pointer",
            }} type="button">
              <div style={{ fontSize: 8, fontFamily: "DM Sans", color: T.muted }}>
                {new Date(d + "T00:00:00").toLocaleDateString("en-GB", { weekday: "short" }).toUpperCase()}
              </div>
              <div style={{ fontSize: 11, fontFamily: "JetBrains Mono, ui-monospace" }}>{ukShort(d)}</div>
              {has && <div style={{ width: 5, height: 5, borderRadius: "50%", background: T.coachGreen, margin: "3px auto 0" }} />}
            </button>
          );
        })}
      </div>

      {loading ? <div style={{ color: T.muted, fontSize: 12 }}>Loading…</div> : (
        <>
          {/* Day header + totals + actions */}
          <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", flexWrap: "wrap", gap: 8, marginBottom: 12 }}>
            <div>
              <span style={{ fontFamily: "Bebas Neue, system-ui", fontSize: 16, letterSpacing: 1.5, color: T.accent }}>{ukLong(selDate)}</span>
              <span style={{ fontSize: 10, color: T.muted, fontFamily: "JetBrains Mono, ui-monospace", marginLeft: 10 }}>
                {Math.round(dayTotals.cal)} cal · {Math.round(dayTotals.p)}p · {Math.round(dayTotals.c)}c · {Math.round(dayTotals.f)}f
              </span>
            </div>
            <div style={{ display: "flex", gap: 6, flexWrap: "wrap" }}>
              <button onClick={() => setShowImport(!showImport)} style={{ background: "none", border: `1px solid ${T.border}`, borderRadius: 8, padding: "6px 12px", color: T.text, fontSize: 11, fontFamily: "DM Sans", cursor: "pointer" }} type="button">
                📋 Import a logged day
              </button>
              <button onClick={saveDay} disabled={saving || !dirty} style={{
                background: dirty ? T.accent : T.border, color: dirty ? T.bg : T.muted,
                border: "none", borderRadius: 8, padding: "6px 16px",
                fontFamily: "Bebas Neue, system-ui", fontSize: 12, letterSpacing: 1.5, cursor: dirty ? "pointer" : "default",
              }} type="button">{saving ? "SAVING…" : dirty ? "SAVE DAY" : "SAVED"}</button>
              {planned[selDate] && (
                <button onClick={clearDay} style={{ background: "none", border: `1px solid ${T.danger}44`, borderRadius: 8, padding: "6px 10px", color: T.danger, fontSize: 11, fontFamily: "DM Sans", cursor: "pointer" }} type="button">Clear</button>
              )}
            </div>
          </div>

          {/* Import from athlete's logged history */}
          {showImport && (
            <div style={{ background: T.surface, border: `1px solid ${T.border}`, borderRadius: 12, padding: 12, marginBottom: 12 }}>
              <div style={{ fontSize: 11, color: T.muted, fontFamily: "DM Sans", marginBottom: 8 }}>
                Pull everything the athlete logged on a previous day into this planned day (last 30 days):
              </div>
              <div style={{ display: "flex", gap: 6, flexWrap: "wrap" }}>
                {historyDays.length === 0 ? <span style={{ fontSize: 11, color: T.muted }}>No logged days found.</span> :
                  historyDays.map((d) => (
                    <button key={d} onClick={() => importLoggedDay(d)} style={{ background: "none", border: `1px solid ${T.coachGreen}55`, borderRadius: 7, padding: "5px 10px", color: T.coachGreen, fontSize: 10, fontFamily: "JetBrains Mono, ui-monospace", cursor: "pointer" }} type="button">
                      {ukShort(d)}
                    </button>
                  ))}
              </div>
            </div>
          )}

          {/* Meal slots */}
          {PLAN_SLOTS.map((slot) => {
            const items = dayMeals[slot] || [];
            const st = items.reduce((a, i) => ({ cal: a.cal + i.calories, p: a.p + i.protein_g, c: a.c + i.carbs_g, f: a.f + i.fat_g }), { cal: 0, p: 0, c: 0, f: 0 });
            return (
              <div key={slot} style={{ background: T.surface, border: `1px solid ${T.border}`, borderRadius: 12, padding: 12, marginBottom: 10 }}>
                <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 6 }}>
                  <span style={{ fontFamily: "Bebas Neue, system-ui", fontSize: 13, letterSpacing: 1.5, color: T.text }}>{slot.toUpperCase()}</span>
                  <span style={{ fontSize: 9, color: T.accent, fontFamily: "JetBrains Mono, ui-monospace" }}>
                    {Math.round(st.cal)} cal · {Math.round(st.p)}p · {Math.round(st.c)}c · {Math.round(st.f)}f
                  </span>
                </div>
                {items.map((i, idx) => (
                  <div key={idx} style={{ display: "flex", justifyContent: "space-between", alignItems: "center", padding: "4px 0", borderBottom: `1px solid ${T.border}20`, fontSize: 11 }}>
                    <span style={{ color: T.text }}>{i.name}</span>
                    <span style={{ display: "flex", gap: 10, alignItems: "center" }}>
                      <span style={{ color: T.muted, fontFamily: "JetBrains Mono, ui-monospace", fontSize: 10 }}>
                        {i.calories} · {i.protein_g}p · {i.carbs_g}c · {i.fat_g}f
                      </span>
                      <button onClick={() => removeItem(slot, idx)} style={{ background: "none", border: "none", color: T.muted, cursor: "pointer", fontSize: 12 }} type="button">✕</button>
                    </span>
                  </div>
                ))}

                {pickerSlot === slot ? (
                  <div style={{ marginTop: 8 }}>
                    <input value={q} onChange={(e) => { setQ(e.target.value); setSelFood(null); }} placeholder="Search foods (DB + OpenFoodFacts)…" autoFocus style={{ ...inputStyle, marginBottom: 6 }} />
                    {searching && <div style={{ fontSize: 10, color: T.muted, marginBottom: 6 }}>Searching…</div>}
                    {!selFood && results.length > 0 && (
                      <div style={{ maxHeight: 160, overflowY: "auto", border: `1px solid ${T.border}`, borderRadius: 8, marginBottom: 6 }}>
                        {results.map((r, i) => (
                          <button key={i} onClick={() => setSelFood(r)} style={{ display: "flex", justifyContent: "space-between", width: "100%", padding: "6px 10px", background: "none", border: "none", borderBottom: `1px solid ${T.border}20`, color: T.text, fontSize: 11, cursor: "pointer", textAlign: "left" }} type="button">
                            <span>{r.name} <span style={{ color: T.muted, fontSize: 9 }}>({r.src})</span></span>
                            <span style={{ color: T.muted, fontFamily: "JetBrains Mono, ui-monospace", fontSize: 10 }}>{Math.round(r.per100.calories)}/100g</span>
                          </button>
                        ))}
                      </div>
                    )}
                    {selFood && (
                      <div style={{ display: "flex", gap: 6, alignItems: "center", marginBottom: 6 }}>
                        <span style={{ fontSize: 11, color: T.text, flex: 1 }}>{selFood.name}</span>
                        <input type="number" value={grams} onChange={(e) => setGrams(e.target.value)} style={{ ...inputStyle, width: 70, textAlign: "center" }} />
                        <span style={{ fontSize: 10, color: T.muted }}>g</span>
                        <button onClick={addSearchFood} style={{ background: T.accent, color: T.bg, border: "none", borderRadius: 7, padding: "7px 12px", fontFamily: "Bebas Neue, system-ui", fontSize: 11, letterSpacing: 1, cursor: "pointer" }} type="button">ADD</button>
                      </div>
                    )}
                    {q.trim().length < 2 && recentFoods.length > 0 && (
                      <>
                        <div style={{ fontSize: 9, color: T.muted, fontFamily: "DM Sans", margin: "4px 0" }}>ATHLETE'S RECENT FOODS — tap to add as eaten:</div>
                        <div style={{ display: "flex", gap: 5, flexWrap: "wrap", marginBottom: 6 }}>
                          {recentFoods.slice(0, 12).map((f, i) => (
                            <button key={i} onClick={() => addItem(slot, f)} style={{ background: "none", border: `1px solid ${T.coachGreen}44`, borderRadius: 7, padding: "4px 9px", color: T.coachGreen, fontSize: 10, fontFamily: "DM Sans", cursor: "pointer" }} type="button">
                              + {f.name.length > 34 ? f.name.slice(0, 32) + "…" : f.name}
                            </button>
                          ))}
                        </div>
                      </>
                    )}
                    <button onClick={() => { setPickerSlot(null); setQ(""); setSelFood(null); setResults([]); }} style={{ background: "none", border: "none", color: T.muted, fontSize: 10, cursor: "pointer" }} type="button">close</button>
                  </div>
                ) : (
                  <button onClick={() => { setPickerSlot(slot); setQ(""); setSelFood(null); setResults([]); }} style={{ width: "100%", marginTop: 6, padding: "7px", background: "none", border: `1px dashed ${T.border}`, borderRadius: 8, color: T.muted, fontSize: 11, fontFamily: "DM Sans", cursor: "pointer" }} type="button">
                    + Add food
                  </button>
                )}
              </div>
            );
          })}

          {/* Copy tools */}
          <div style={{ background: T.surface, border: `1px solid ${T.border}`, borderRadius: 12, padding: 12, marginTop: 4 }}>
            <div style={{ fontFamily: "Bebas Neue, system-ui", fontSize: 12, letterSpacing: 1.5, color: T.text, marginBottom: 8 }}>COPY THIS DAY</div>
            <div style={{ display: "flex", gap: 6, flexWrap: "wrap" }}>
              <button onClick={() => copyNextNDays(7)} style={{ background: "none", border: `1px solid ${T.accent}55`, borderRadius: 8, padding: "6px 12px", color: T.accent, fontSize: 11, fontFamily: "DM Sans", cursor: "pointer" }} type="button">→ Next 7 days</button>
              <button onClick={() => copyNextNDays(14)} style={{ background: "none", border: `1px solid ${T.accent}55`, borderRadius: 8, padding: "6px 12px", color: T.accent, fontSize: 11, fontFamily: "DM Sans", cursor: "pointer" }} type="button">→ Next 14 days</button>
              <button onClick={() => copyNextNDays(30)} style={{ background: "none", border: `1px solid ${T.accent}55`, borderRadius: 8, padding: "6px 12px", color: T.accent, fontSize: 11, fontFamily: "DM Sans", cursor: "pointer" }} type="button">→ Next 30 days (whole month)</button>
              <button onClick={() => copyWeekForward(1)} style={{ background: "none", border: `1px solid ${T.coachGreen}55`, borderRadius: 8, padding: "6px 12px", color: T.coachGreen, fontSize: 11, fontFamily: "DM Sans", cursor: "pointer" }} type="button">Copy this WEEK → next week</button>
              <button onClick={() => copyWeekForward(4)} style={{ background: "none", border: `1px solid ${T.coachGreen}55`, borderRadius: 8, padding: "6px 12px", color: T.coachGreen, fontSize: 11, fontFamily: "DM Sans", cursor: "pointer" }} type="button">Copy this WEEK → next 4 weeks</button>
            </div>
            <div style={{ fontSize: 9, color: T.muted, fontFamily: "DM Sans", marginTop: 8 }}>
              Save the day first, then copy. Week copy repeats each saved day of this week onto the same weekday ahead.
            </div>
          </div>
        </>
      )}
    </div>
  );
}

/* ─────────────────────────────────────────────────────────────────────────────
   Workout Viewer — training sessions synced from the athlete's Apple Health.
────────────────────────────────────────────────────────────────────────────── */
function WorkoutViewer({ athleteId, token }) {
  const [rows, setRows] = useState([]);
  const [loading, setLoading] = useState(true);
  const [days, setDays] = useState(14);

  const fmt = (d) => `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
  const ukShort = (iso) => { const [, m, d] = String(iso).split("-"); return `${d}/${m}`; };

  useEffect(() => {
    if (!athleteId || !token) return;
    (async () => {
      setLoading(true);
      try {
        const end = new Date();
        const start = new Date(); start.setDate(start.getDate() - (days - 1));
        const r = await apiFetch(`/workout-logs/${athleteId}?start=${fmt(start)}&end=${fmt(end)}`, token);
        setRows(Array.isArray(r) ? r : []);
      } catch { setRows([]); }
      setLoading(false);
    })();
  }, [athleteId, token, days]);

  const totalMins = rows.reduce((a, w) => a + Number(w.minutes || 0), 0);
  const totalKcal = rows.reduce((a, w) => a + Number(w.calories || 0), 0);
  const totalKm = rows.reduce((a, w) => a + Number(w.distanceKm || 0), 0);

  // Group by activity type for a quick "what are they actually doing" summary
  const byType = {};
  rows.forEach((w) => {
    const t = w.type || "Workout";
    byType[t] = byType[t] || { count: 0, mins: 0 };
    byType[t].count += 1;
    byType[t].mins += Number(w.minutes || 0);
  });
  const types = Object.entries(byType).sort((a, b) => b[1].mins - a[1].mins);

  return (
    <div style={{ background: T.card, border: `1px solid ${T.border}`, borderRadius: 16, padding: 18 }}>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", flexWrap: "wrap", gap: 8, marginBottom: 4 }}>
        <div style={{ fontFamily: "Bebas Neue, system-ui", fontSize: 18, letterSpacing: 2, color: T.text }}>TRAINING &amp; ACTIVITY</div>
        <div style={{ display: "flex", gap: 4 }}>
          {[7, 14, 30].map((d) => (
            <button key={d} onClick={() => setDays(d)} style={{
              background: days === d ? `${T.accent}22` : "none",
              border: `1px solid ${days === d ? T.accent : T.border}`,
              borderRadius: 7, padding: "4px 10px",
              color: days === d ? T.accent : T.muted,
              fontFamily: "JetBrains Mono, ui-monospace", fontSize: 10, cursor: "pointer",
            }} type="button">{d}D</button>
          ))}
        </div>
      </div>
      <div style={{ fontFamily: "DM Sans", fontSize: 11, color: T.muted, marginBottom: 12 }}>
        Runs, rides, gym sessions and other workouts — synced from the athlete's Apple Health.
      </div>

      {loading ? <div style={{ color: T.muted, fontSize: 12 }}>Loading…</div> : rows.length === 0 ? (
        <div style={{ color: T.muted, fontSize: 12, fontFamily: "DM Sans" }}>
          No workouts synced for this period.
        </div>
      ) : (
        <>
          {/* Totals */}
          <div style={{ display: "flex", gap: 10, flexWrap: "wrap", marginBottom: 12 }}>
            {[
              { l: "SESSIONS", v: rows.length },
              { l: "ACTIVE MINS", v: Math.round(totalMins) },
              { l: "KCAL", v: Math.round(totalKcal) || "—" },
              { l: "DISTANCE", v: totalKm > 0 ? `${Math.round(totalKm * 10) / 10} km` : "—" },
            ].map((c) => (
              <div key={c.l} style={{ flex: "1 1 90px", background: T.surface, border: `1px solid ${T.border}`, borderRadius: 10, padding: "8px 10px", textAlign: "center" }}>
                <div style={{ fontFamily: "Bebas Neue, system-ui", fontSize: 17, color: T.accent }}>{c.v}</div>
                <div style={{ fontFamily: "DM Sans", fontSize: 8, letterSpacing: 0.5, color: T.muted }}>{c.l}</div>
              </div>
            ))}
          </div>

          {/* Activity mix */}
          <div style={{ display: "flex", gap: 6, flexWrap: "wrap", marginBottom: 12 }}>
            {types.map(([t, v]) => (
              <span key={t} style={{ background: T.surface, border: `1px solid ${T.coachGreen}44`, borderRadius: 8, padding: "3px 9px", fontFamily: "DM Sans", fontSize: 10, color: T.text }}>
                {t} <span style={{ color: T.muted }}>×{v.count} · {Math.round(v.mins)}min</span>
              </span>
            ))}
          </div>

          {/* Session list */}
          <div style={{ maxHeight: 260, overflowY: "auto" }}>
            {rows.map((w, i) => (
              <div key={i} style={{ display: "flex", justifyContent: "space-between", alignItems: "center", padding: "6px 0", borderBottom: `1px solid ${T.border}25` }}>
                <div>
                  <span style={{ fontFamily: "DM Sans", fontSize: 12, color: T.text }}>{w.type || "Workout"}</span>
                  <span style={{ fontFamily: "JetBrains Mono, ui-monospace", fontSize: 9, color: T.muted, marginLeft: 8 }}>
                    {ukShort(w.date)}{w.startTime ? ` · ${w.startTime}` : ""}
                  </span>
                </div>
                <span style={{ fontFamily: "JetBrains Mono, ui-monospace", fontSize: 10, color: T.accent, whiteSpace: "nowrap" }}>
                  {Math.round(Number(w.minutes || 0))}min
                  {Number(w.distanceKm) > 0 ? ` · ${Number(w.distanceKm)}km` : ""}
                  {Number(w.calories) > 0 ? ` · ${Math.round(Number(w.calories))}kcal` : ""}
                  {Number(w.avgHr) > 0 ? ` · ${Math.round(Number(w.avgHr))}bpm` : ""}
                </span>
              </div>
            ))}
          </div>
        </>
      )}
    </div>
  );
}

/* ─────────────────────────────────────────────────────────────────────────────
   Sleep Viewer — nightly sleep patterns synced from the athlete's Apple Health.
────────────────────────────────────────────────────────────────────────────── */
function SleepViewer({ athleteId, token }) {
  const [nights, setNights] = useState([]);
  const [loading, setLoading] = useState(true);

  const fmt = (d) => `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
  const last7 = [...Array(7)].map((_, i) => { const d = new Date(); d.setDate(d.getDate() - (6 - i)); return fmt(d); });
  const ukShort = (iso) => { const [, m, d] = String(iso).split("-"); return `${d}/${m}`; };

  useEffect(() => {
    if (!athleteId || !token) return;
    (async () => {
      setLoading(true);
      try {
        const rows = await apiFetch(`/sleep-logs/${athleteId}?start=${last7[0]}&end=${last7[6]}`, token);
        const map = {};
        (Array.isArray(rows) ? rows : []).forEach((r) => { map[r.date] = r; });
        setNights(last7.map((d) => map[d] ? { ...map[d], empty: false } : { date: d, empty: true }));
      } catch { setNights([]); }
      setLoading(false);
    })();
  }, [athleteId, token]);

  const STAGE_COLOR = { awake: "#fb923c", rem: "#38bdf8", light: "#3b82f6", deep: "#4f46e5", asleep: "#3b82f6" };
  const STAGE_LABEL = { awake: "Awake", rem: "REM", light: "Core", deep: "Deep", asleep: "Asleep" };
  const anyData = nights.some((n) => !n.empty);
  const anyStages = nights.some((n) => !n.empty && (n.segments || []).some((g) => ["awake", "rem", "deep", "light"].includes(g.stage)));

  return (
    <div style={{ background: T.card, border: `1px solid ${T.border}`, borderRadius: 16, padding: 18 }}>
      <div style={{ fontFamily: "Bebas Neue, system-ui", fontSize: 18, letterSpacing: 2, color: T.text, marginBottom: 4 }}>SLEEP</div>
      <div style={{ fontFamily: "DM Sans", fontSize: 11, color: T.muted, marginBottom: 12 }}>
        Nightly patterns from the athlete's Apple Health — updates when they open the app.
      </div>
      {loading ? <div style={{ color: T.muted, fontSize: 12 }}>Loading…</div> : !anyData ? (
        <div style={{ color: T.muted, fontSize: 12, fontFamily: "DM Sans" }}>
          No sleep data synced yet — it appears after the athlete connects Apple Health and opens their Wellbeing tab.
        </div>
      ) : (
        <div style={{ maxWidth: 520 }}>
          {nights.map((n) => (
            <div key={n.date} style={{ marginBottom: 9 }}>
              <div style={{ display: "flex", justifyContent: "space-between", alignItems: "baseline", marginBottom: 2 }}>
                <span style={{ fontFamily: "JetBrains Mono, ui-monospace", fontSize: 9, color: T.muted }}>{ukShort(n.date)}</span>
                {!n.empty && (
                  <span style={{ fontFamily: "JetBrains Mono, ui-monospace", fontSize: 9, color: T.muted }}>
                    🛏 {n.bed} → ⏰ {n.wake} · <span style={{ color: T.accent }}>{Number(n.hours)}h</span>
                  </span>
                )}
              </div>
              <div style={{ position: "relative", height: 13, background: T.surface, border: `1px solid ${T.border}40`, borderRadius: 6, overflow: "hidden" }}>
                {n.empty ? (
                  <div style={{ position: "absolute", inset: 0, display: "flex", alignItems: "center", justifyContent: "center", fontFamily: "JetBrains Mono, ui-monospace", fontSize: 8, color: T.border }}>—</div>
                ) : (
                  (n.segments || []).map((g, i) => (
                    <div key={i} style={{
                      position: "absolute", left: `${g.leftPct}%`, width: `${Math.max(g.widthPct, 0.6)}%`,
                      top: 0, bottom: 0, background: STAGE_COLOR[g.stage] || STAGE_COLOR.asleep,
                    }} title={STAGE_LABEL[g.stage] || "Asleep"} />
                  ))
                )}
              </div>
            </div>
          ))}
          <div style={{ display: "flex", gap: 12, flexWrap: "wrap", marginTop: 8 }}>
            {(anyStages ? ["deep", "light", "rem", "awake"] : ["asleep"]).map((k) => (
              <span key={k} style={{ fontFamily: "DM Sans", fontSize: 9, color: T.muted }}>
                <span style={{ display: "inline-block", width: 10, height: 10, borderRadius: 3, background: STAGE_COLOR[k], marginRight: 4, verticalAlign: "middle" }} />
                {STAGE_LABEL[k]}
              </span>
            ))}
            <span style={{ fontFamily: "DM Sans", fontSize: 9, color: T.border }}>gaps = out of bed</span>
          </div>
        </div>
      )}
    </div>
  );
}

/* ─────────────────────────────────────────────────────────────────────────────
   Steps Manager — coach sets a daily step target and sees the athlete's
   synced step counts (uploaded by the athlete's app from Apple Health).
────────────────────────────────────────────────────────────────────────────── */
function StepsManager({ athleteId, token }) {
  const [target, setTarget] = useState(null);
  const [draft, setDraft] = useState("");
  const [savingT, setSavingT] = useState(false);
  const [days, setDays] = useState([]);
  const [loading, setLoading] = useState(true);

  const fmt = (d) => `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
  const last7 = [...Array(7)].map((_, i) => { const d = new Date(); d.setDate(d.getDate() - (6 - i)); return fmt(d); });
  const ukShort = (iso) => { const [, m, d] = String(iso).split("-"); return `${d}/${m}`; };

  const load = async () => {
    try {
      let t = null, rows = [];
      try { const r = await apiFetch(`/step-target/${athleteId}`, token); t = r?.steps ?? null; } catch {}
      try { rows = await apiFetch(`/step-logs/${athleteId}?start=${last7[0]}&end=${last7[6]}`, token); } catch {}
      setTarget(t);
      setDraft(t != null ? String(t) : "");
      const map = {};
      (Array.isArray(rows) ? rows : []).forEach((r) => { map[r.date] = Number(r.steps || 0); });
      setDays(last7.map((d) => ({ date: d, steps: map[d] || 0 })));
    } catch {}
    setLoading(false);
  };
  useEffect(() => { if (athleteId && token) { setLoading(true); load(); } }, [athleteId, token]);

  const saveTarget = async () => {
    setSavingT(true);
    try {
      const steps = draft.trim() === "" ? null : Math.max(0, Number(draft) || 0);
      await apiFetch(`/athletes/${athleteId}/step-target`, token, {
        method: "PUT",
        body: JSON.stringify({ steps }),
      });
      setTarget(steps);
    } catch (e) { alert(e.message || "Could not save step target"); }
    setSavingT(false);
  };

  const maxVal = Math.max(...days.map((d) => d.steps), target || 0, 1) * 1.05;
  const ragColor = (v) => {
    if (!target || target <= 0) return null;
    const pct = (v / target) * 100;
    if (pct >= 90) return T.coachGreen;
    if (pct >= 75) return "#f59e0b";
    return T.danger;
  };
  const targetPct = target > 0 ? (target / maxVal) * 100 : null;

  return (
    <div style={{ background: T.card, border: `1px solid ${T.border}`, borderRadius: 16, padding: 18 }}>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", flexWrap: "wrap", gap: 8, marginBottom: 4 }}>
        <div style={{ fontFamily: "Bebas Neue, system-ui", fontSize: 18, letterSpacing: 2, color: T.text }}>STEPS</div>
        <div style={{ display: "flex", gap: 6, alignItems: "center" }}>
          <input
            type="number"
            value={draft}
            onChange={(e) => setDraft(e.target.value)}
            placeholder="Daily target"
            style={{ ...inputStyle, width: 110, padding: "7px 10px", fontSize: 12 }}
          />
          <button onClick={saveTarget} disabled={savingT} style={{
            background: T.accent, color: T.bg, border: "none", borderRadius: 8, padding: "8px 14px",
            fontFamily: "Bebas Neue, system-ui", fontSize: 12, letterSpacing: 1.5, cursor: "pointer", opacity: savingT ? 0.6 : 1,
          }} type="button">{savingT ? "…" : "SET TARGET"}</button>
        </div>
      </div>
      <div style={{ fontFamily: "DM Sans", fontSize: 11, color: T.muted, marginBottom: 12 }}>
        {target > 0
          ? <>Target: <span style={{ color: T.coachGreen }}>{Number(target).toLocaleString()} steps/day</span> — green ≥90%, amber ≥75%, red below. Data syncs from the athlete's Apple Health.</>
          : "No target set. Steps sync from the athlete's Apple Health when they open the app."}
      </div>

      {loading ? <div style={{ color: T.muted, fontSize: 12 }}>Loading…</div> :
        days.every((d) => d.steps === 0) ? (
          <div style={{ color: T.muted, fontSize: 12, fontFamily: "DM Sans" }}>
            No step data synced yet — it appears after the athlete connects Apple Health and opens their Wellbeing tab.
          </div>
        ) : (
        <div style={{ position: "relative", maxWidth: 480 }}>
          {targetPct != null && (
            <div style={{ position: "absolute", left: 0, right: 0, bottom: `${16 + targetPct * 0.56}px`, borderTop: `2px dotted ${T.coachGreen}99`, zIndex: 2, pointerEvents: "none" }} />
          )}
          <div style={{ display: "flex", alignItems: "flex-end", gap: 8, height: 84 }}>
            {days.map((d) => {
              const rag = d.steps > 0 ? ragColor(d.steps) : null;
              return (
                <div key={d.date} style={{ flex: 1, textAlign: "center" }}>
                  <div style={{ fontFamily: "JetBrains Mono, ui-monospace", fontSize: 8, color: T.muted, marginBottom: 2 }}>
                    {d.steps > 0 ? (d.steps >= 1000 ? `${Math.round(d.steps / 100) / 10}k` : d.steps) : ""}
                  </div>
                  <div style={{
                    height: Math.max((d.steps / maxVal) * 56, 2),
                    background: rag || `${T.accent}88`,
                    borderRadius: 3,
                  }} title={`${d.steps.toLocaleString()} steps`} />
                  <div style={{ fontFamily: "JetBrains Mono, ui-monospace", fontSize: 8, color: T.muted, marginTop: 3 }}>{ukShort(d.date)}</div>
                </div>
              );
            })}
          </div>
        </div>
      )}
    </div>
  );
}

/* ─────────────────────────────────────────────────────────────────────────────
   Wellbeing Manager — coach sets habits, sees athlete RAG ratings + weight/mood
────────────────────────────────────────────────────────────────────────────── */
function WellbeingManager({ athleteId, token }) {
  const [habits, setHabits] = useState([]);
  const [ratings, setRatings] = useState([]);
  const [loading, setLoading] = useState(true);
  const [newHabit, setNewHabit] = useState("");
  const [saving, setSaving] = useState(false);

  const fmt = (d) => `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
  const last7 = [...Array(7)].map((_, i) => { const d = new Date(); d.setDate(d.getDate() - (6 - i)); return fmt(d); });
  const ukShort = (iso) => { const [, m, d] = String(iso).split("-"); return `${d}/${m}`; };

  const load = async () => {
    try {
      const start = last7[0], end = last7[6];
      let h = [], r = [];
      try { h = await apiFetch(`/habits/${athleteId}`, token); } catch {}
      try { r = await apiFetch(`/habit-ratings/${athleteId}?start=${start}&end=${end}`, token); } catch {}
      setHabits(Array.isArray(h) ? h : []);
      setRatings(Array.isArray(r) ? r : []);
    } catch {}
    setLoading(false);
  };

  useEffect(() => { if (athleteId && token) { setLoading(true); load(); } }, [athleteId, token]);

  const addHabit = async () => {
    const title = newHabit.trim();
    if (!title) return;
    setSaving(true);
    try {
      await apiFetch(`/habits/${athleteId}`, token, { method: "POST", body: JSON.stringify({ title }) });
      setNewHabit("");
      await load();
    } catch (e) { alert(e.message || "Could not add habit"); }
    setSaving(false);
  };

  const deleteHabit = async (id) => {
    try {
      await apiFetch(`/habits/${athleteId}/${id}`, token, { method: "DELETE" });
      await load();
    } catch (e) { alert(e.message); }
  };

  const ratingMap = {};
  ratings.forEach((r) => { ratingMap[`${r.habit_id}|${r.date}`] = r.rating; });
  const RAG_COLOR = { G: T.coachGreen, A: "#f59e0b", R: T.danger };

  return (
    <div style={{ display: "grid", gap: 14 }}>
      {/* Habits + RAG grid */}
      <div style={{ background: T.card, border: `1px solid ${T.border}`, borderRadius: 16, padding: 18 }}>
        <div style={{ fontFamily: "Bebas Neue, system-ui", fontSize: 18, letterSpacing: 2, color: T.text, marginBottom: 4 }}>HABITS</div>
        <div style={{ fontFamily: "DM Sans", fontSize: 11, color: T.muted, marginBottom: 12 }}>
          Set habits for this athlete — they rate each one Red / Amber / Green daily.
        </div>

        <div style={{ display: "flex", gap: 8, marginBottom: 14 }}>
          <input
            value={newHabit}
            onChange={(e) => setNewHabit(e.target.value)}
            onKeyDown={(e) => { if (e.key === "Enter") addHabit(); }}
            placeholder="e.g. 8k steps · 2L water · In bed by 10:30"
            style={{ ...inputStyle, flex: 1 }}
          />
          <button onClick={addHabit} disabled={saving || !newHabit.trim()} style={{
            background: newHabit.trim() ? T.accent : T.border,
            color: newHabit.trim() ? T.bg : T.muted,
            border: "none", borderRadius: 10, padding: "10px 18px",
            fontFamily: "Bebas Neue, system-ui", fontSize: 13, letterSpacing: 1.5,
            cursor: newHabit.trim() && !saving ? "pointer" : "default",
          }} type="button">{saving ? "…" : "ADD"}</button>
        </div>

        {loading ? <div style={{ color: T.muted, fontSize: 12 }}>Loading…</div> : habits.length === 0 ? (
          <div style={{ color: T.muted, fontSize: 12 }}>No habits set yet. Add the first one above.</div>
        ) : (
          <div style={{ overflowX: "auto" }}>
            {/* Header: dates */}
            <div style={{ display: "grid", gridTemplateColumns: `minmax(140px, 1.6fr) repeat(7, 34px) 28px`, gap: 4, alignItems: "center", marginBottom: 6 }}>
              <span />
              {last7.map((d) => (
                <span key={d} style={{ fontSize: 8, color: T.muted, fontFamily: "JetBrains Mono, ui-monospace", textAlign: "center" }}>{ukShort(d)}</span>
              ))}
              <span />
            </div>
            {habits.map((h) => (
              <div key={h.id} style={{ display: "grid", gridTemplateColumns: `minmax(140px, 1.6fr) repeat(7, 34px) 28px`, gap: 4, alignItems: "center", padding: "5px 0", borderBottom: `1px solid ${T.border}20` }}>
                <span style={{ fontSize: 12, color: T.text, fontFamily: "DM Sans" }}>{h.title}</span>
                {last7.map((d) => {
                  const rag = ratingMap[`${h.id}|${d}`];
                  return (
                    <span key={d} style={{
                      width: 22, height: 22, borderRadius: 6, margin: "0 auto",
                      background: rag ? `${RAG_COLOR[rag]}cc` : T.surface,
                      border: `1px solid ${rag ? RAG_COLOR[rag] : T.border}`,
                    }} title={rag || "not rated"} />
                  );
                })}
                <button onClick={() => deleteHabit(h.id)} style={{ background: "none", border: "none", color: T.muted, cursor: "pointer", fontSize: 13 }} title="Remove habit" type="button">✕</button>
              </div>
            ))}
            <div style={{ display: "flex", gap: 12, marginTop: 10 }}>
              {[["G", "On track"], ["A", "Partly"], ["R", "Missed"]].map(([k, l]) => (
                <span key={k} style={{ fontSize: 9, color: T.muted, fontFamily: "DM Sans" }}>
                  <span style={{ display: "inline-block", width: 10, height: 10, borderRadius: 3, background: RAG_COLOR[k], marginRight: 4, verticalAlign: "middle" }} />{l}
                </span>
              ))}
            </div>
          </div>
        )}
      </div>

      {/* Steps: coach-set daily target + athlete's synced HealthKit data */}
      <StepsManager athleteId={athleteId} token={token} />

      {/* Sleep: nightly patterns synced from the athlete's Apple Health */}
      <SleepViewer athleteId={athleteId} token={token} />

      {/* Workouts: sessions synced from the athlete's Apple Health */}
      <WorkoutViewer athleteId={athleteId} token={token} />

      {/* Weight + Mood graphs (moved from the old MOOD & WEIGHT tab) */}
      <AthleteMoodViewer athleteId={athleteId} token={token} />
      <AthleteWeightViewer athleteId={athleteId} token={token} />
    </div>
  );
}

/* ─────────────────────────────────────────────────────────────────────────────
   Athlete Calendar Manager — view + add events for athlete
────────────────────────────────────────────────────────────────────────────── */
function AthleteCalendarManager({ athleteId, token }) {
  const [events, setEvents] = useState([]);
  const [loading, setLoading] = useState(true);
  const [form, setForm] = useState({ date: "", startTime: "", endTime: "", title: "", notes: "" });
  const [saving, setSaving] = useState(false);

  const loadEvents = async () => {
    try {
      const rows = await apiFetch(`/calendar-events/${athleteId}`, token);
      setEvents(Array.isArray(rows) ? rows : []);
    } catch { setEvents([]); }
  };

  useEffect(() => {
    if (!athleteId || !token) return;
    (async () => {
      setLoading(true);
      await loadEvents();
      setLoading(false);
    })();
  }, [athleteId, token]);

  const addEvent = async () => {
    if (!form.date || !form.title.trim()) return;
    setSaving(true);
    try {
      // Build full ISO timestamps if a time was provided; otherwise fall back to date-only
      const startISO = form.startTime
        ? new Date(`${form.date}T${form.startTime}:00`).toISOString()
        : form.date;
      const endISO = form.endTime
        ? new Date(`${form.date}T${form.endTime}:00`).toISOString()
        : startISO;
      await apiFetch(`/calendar-events/${athleteId}`, token, {
        method: "POST",
        body: JSON.stringify({
          date: form.date,
          title: form.title,
          startISO,
          endISO,
          notes: form.notes,
        }),
      });
      setForm({ date: "", startTime: "", endTime: "", title: "", notes: "" });
      await loadEvents();
    } catch (e) { alert(e.message); }
    setSaving(false);
  };

  const deleteEvent = async (id) => {
    try {
      await apiFetch(`/calendar-events/${athleteId}/${id}`, token, { method: "DELETE" });
      await loadEvents();
    } catch (e) { alert(e.message); }
  };

  // Format a stored event's time range for display
  const formatEventTime = (ev) => {
    if (!ev.startISO) return null;
    try {
      const s = new Date(ev.startISO);
      // If it's just a date (no time), the ISO parsing gives midnight UTC — skip display
      if (ev.startISO.length <= 10) return null;
      const sStr = s.toLocaleTimeString("en-GB", { hour: "2-digit", minute: "2-digit" });
      if (ev.endISO && ev.endISO !== ev.startISO && ev.endISO.length > 10) {
        const e = new Date(ev.endISO);
        const eStr = e.toLocaleTimeString("en-GB", { hour: "2-digit", minute: "2-digit" });
        return `${sStr}–${eStr}`;
      }
      return sStr;
    } catch { return null; }
  };

  return (
    <div style={{ background: T.card, border: `1px solid ${T.border}`, borderRadius: 16, padding: 18 }}>
      <div style={{ fontFamily: "Bebas Neue, system-ui", fontSize: 18, letterSpacing: 2, color: T.text, marginBottom: 14 }}>CALENDAR EVENTS</div>

      {/* Add event form */}
      <div style={{ background: T.surface, border: `1px solid ${T.border}`, borderRadius: 12, padding: 14, marginBottom: 14 }}>
        <div style={{ display: "grid", gridTemplateColumns: "1.2fr 1fr 1fr", gap: 8, marginBottom: 8 }}>
          <div>
            <label style={labelStyle}>Date *</label>
            <input type="date" value={form.date} onChange={(e) => setForm(p => ({ ...p, date: e.target.value }))} style={inputStyle} />
          </div>
          <div>
            <label style={labelStyle}>Start time</label>
            <input type="time" value={form.startTime} onChange={(e) => setForm(p => ({ ...p, startTime: e.target.value }))} style={inputStyle} />
          </div>
          <div>
            <label style={labelStyle}>End time</label>
            <input type="time" value={form.endTime} onChange={(e) => setForm(p => ({ ...p, endTime: e.target.value }))} style={inputStyle} />
          </div>
        </div>
        <div style={{ display: "grid", gridTemplateColumns: "2fr 2fr auto", gap: 8, alignItems: "end" }}>
          <div>
            <label style={labelStyle}>Title *</label>
            <input value={form.title} onChange={(e) => setForm(p => ({ ...p, title: e.target.value }))} placeholder="e.g. Check-in call" style={inputStyle} />
          </div>
          <div>
            <label style={labelStyle}>Notes</label>
            <textarea
              value={form.notes}
              onChange={(e) => setForm(p => ({ ...p, notes: e.target.value }))}
              placeholder="Optional notes — new lines are kept"
              rows={3}
              style={{ ...inputStyle, resize: "vertical", minHeight: 64, fontFamily: "DM Sans" }}
            />
          </div>
          <button onClick={addEvent} disabled={saving || !form.date || !form.title.trim()} style={{
            background: form.date && form.title.trim() ? T.accent : T.border,
            color: form.date && form.title.trim() ? T.bg : T.muted,
            border: "none", borderRadius: 10, padding: "11px 18px",
            fontFamily: "Bebas Neue, system-ui", fontSize: 13, letterSpacing: 1.5,
            cursor: form.date && form.title.trim() && !saving ? "pointer" : "default",
          }} type="button">{saving ? "…" : "ADD"}</button>
        </div>
      </div>

      {loading ? <div style={{ color: T.muted, fontSize: 12 }}>Loading…</div> : events.length === 0 ? (
        <div style={{ color: T.muted, fontSize: 12 }}>No calendar events yet. Add one above.</div>
      ) : (
        <div style={{ maxHeight: 300, overflowY: "auto" }}>
          {events.map((ev) => {
            const timeStr = formatEventTime(ev);
            return (
              <div key={ev.id} style={{ display: "flex", alignItems: "center", gap: 10, padding: "8px 0", borderBottom: `1px solid ${T.border}20` }}>
                <span style={{ fontFamily: "JetBrains Mono, ui-monospace", fontSize: 10, color: T.accent, whiteSpace: "nowrap" }}>{String(ev.date).split("-").reverse().join("/")}</span>
                {timeStr && <span style={{ fontFamily: "JetBrains Mono, ui-monospace", fontSize: 10, color: T.coachGreen, whiteSpace: "nowrap" }}>{timeStr}</span>}
                <div style={{ flex: 1 }}>
                  <div style={{ fontSize: 12, color: T.text, fontWeight: 600 }}>{ev.title}</div>
                  {ev.notes && <div style={{ fontSize: 11, color: T.muted, marginTop: 1, whiteSpace: "pre-wrap" }}>{ev.notes}</div>}
                </div>
                <button onClick={() => deleteEvent(ev.id)} style={{ background: "none", border: `1px solid ${T.danger}44`, borderRadius: 6, padding: "4px 8px", color: T.danger, fontSize: 10, cursor: "pointer" }} type="button">✕</button>
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
}

/* ─────────────────────────────────────────────────────────────────────────────
   Weekly Adherence Dashboard — shows each day's targets vs actuals as % bars
────────────────────────────────────────────────────────────────────────────── */
function WeeklyAdherenceView({ athleteId, token }) {
  const [targets, setTargets] = useState({}); // { MON: {cal,p,c,f}, ... }
  const [actuals, setActuals] = useState({}); // { '2025-03-10': {cal,p,c,f}, ... }
  const [loading, setLoading] = useState(true);

  const loadData = async (ignore) => {
    try {
      // Get macro plans (targets per day of week)
      const plans = await apiFetch(`/macro-plans/${athleteId}`, token);
      const byDay = {};
      (Array.isArray(plans) ? plans : []).forEach(r => {
        byDay[r.day_of_week] = {
          calories: Math.round(Number(r.calories || 0)),
          protein: Math.round(Number(r.protein_g || 0)),
          carbs: Math.round(Number(r.carbs_g || 0)),
          fat: Math.round(Number(r.fat_g || 0)),
        };
      });
      if (!ignore?.current) setTargets(byDay);

      // Get daily totals + food logs for last 7 days
      const today = new Date();
      const start = new Date(today); start.setDate(today.getDate() - 6);
      const fmt = (d) => `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;

      let totals = [], foodLogs = [];
      try { totals = await apiFetch(`/daily-totals/${athleteId}?start=${fmt(start)}&end=${fmt(today)}`, token); } catch {}
      try { foodLogs = await apiFetch(`/food-logs/${athleteId}?start=${fmt(start)}&end=${fmt(today)}`, token); } catch {}

      const byDate = {};
      // First, index daily totals
      (Array.isArray(totals) ? totals : []).forEach(r => {
        byDate[r.date] = {
          calories: Math.round(Number(r.calories || 0)),
          protein: Math.round(Number(r.protein_g || 0)),
          carbs: Math.round(Number(r.carbs_g || 0)),
          fat: Math.round(Number(r.fat_g || 0)),
        };
      });
      // Then, fill in from food logs if daily totals missing for a date
      (Array.isArray(foodLogs) ? foodLogs : []).forEach(fl => {
        if (byDate[fl.date]) return; // already have totals
        const foods = fl.foods || [];
        if (foods.length === 0) return;
        byDate[fl.date] = {
          calories: Math.round(foods.reduce((s, f) => s + Number(f.calories || 0), 0)),
          protein: Math.round(foods.reduce((s, f) => s + Number(f.protein_g || f.protein || 0), 0)),
          carbs: Math.round(foods.reduce((s, f) => s + Number(f.carbs_g || f.carbs || 0), 0)),
          fat: Math.round(foods.reduce((s, f) => s + Number(f.fat_g || f.fat || 0), 0)),
        };
      });
      if (!ignore?.current) setActuals(byDate);
    } catch {}
  };

  useEffect(() => {
    if (!athleteId || !token) return;
    const ignore = { current: false };
    (async () => {
      setLoading(true);
      await loadData(ignore);
      setLoading(false);
    })();
    return () => { ignore.current = true; };
  }, [athleteId, token]);

  // Auto-refresh every 15s
  useEffect(() => {
    if (!athleteId || !token) return;
    const interval = setInterval(() => loadData(), 15 * 1000);
    return () => clearInterval(interval);
  }, [athleteId, token]);

  // Build last 7 days with day key + date
  const days = [];
  for (let i = 6; i >= 0; i--) {
    const d = new Date(); d.setDate(d.getDate() - i);
    const dow = d.getDay();
    const dayKey = DAYS[dow === 0 ? 6 : dow - 1];
    const dateStr = `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
    days.push({ dayKey, dateStr, isToday: i === 0 });
  }

  const pctColor = (pct) => {
    if (pct === null) return T.muted;
    if (pct >= 90 && pct <= 110) return T.coachGreen;
    if (pct >= 75 && pct <= 125) return T.warn;
    return T.danger;
  };

  const macros = [
    { key: "calories", label: "CAL", color: T.accent },
    { key: "protein", label: "P", color: T.protein },
    { key: "carbs", label: "C", color: T.carbs },
    { key: "fat", label: "F", color: T.fat },
  ];

  // Overall adherence for the week
  let adheredDays = 0;
  let totalTracked = 0;
  days.forEach(({ dayKey, dateStr }) => {
    const target = targets[dayKey];
    const actual = actuals[dateStr];
    if (target && actual && target.calories > 0 && actual.calories > 0) {
      totalTracked++;
      const calPct = (actual.calories / target.calories) * 100;
      if (calPct >= 80 && calPct <= 120) adheredDays++;
    }
  });
  const weekPct = totalTracked > 0 ? Math.round((adheredDays / totalTracked) * 100) : null;

  if (loading) return <div style={{ color: T.muted, fontSize: 12, padding: 18 }}>Loading weekly overview…</div>;

  return (
    <div style={{ background: T.card, border: `1px solid ${T.border}`, borderRadius: 16, padding: 18 }}>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 16 }}>
        <div>
          <div style={{ fontFamily: "Bebas Neue, system-ui", fontSize: 18, letterSpacing: 2, color: T.text }}>WEEKLY ADHERENCE</div>
          <div style={{ fontFamily: "DM Sans", fontSize: 11, color: T.muted, marginTop: 2 }}>
            Target vs actual for each day · Auto-refreshes every 30s
          </div>
        </div>
        <div style={{ display: "flex", gap: 8, alignItems: "center" }}>
          <div style={{ width: 6, height: 6, borderRadius: "50%", background: T.coachGreen, animation: "pulse 2s infinite" }} />
          <span style={{ fontFamily: "DM Sans", fontSize: 10, color: T.coachGreen }}>LIVE</span>
          {weekPct !== null && (
            <span style={{
              fontFamily: "Bebas Neue, system-ui", fontSize: 22,
              color: weekPct >= 80 ? T.coachGreen : weekPct >= 60 ? T.warn : T.danger,
            }}>{weekPct}%</span>
          )}
        </div>
      </div>

      {/* Legend */}
      <div style={{ display: "flex", gap: 16, marginBottom: 14, fontSize: 10, fontFamily: "DM Sans" }}>
        <span><span style={{ display: "inline-block", width: 8, height: 8, borderRadius: 2, background: T.coachGreen, marginRight: 4, verticalAlign: "middle" }} />90–110%</span>
        <span><span style={{ display: "inline-block", width: 8, height: 8, borderRadius: 2, background: T.warn, marginRight: 4, verticalAlign: "middle" }} />75–125%</span>
        <span><span style={{ display: "inline-block", width: 8, height: 8, borderRadius: 2, background: T.danger, marginRight: 4, verticalAlign: "middle" }} />Outside</span>
        <span style={{ color: T.muted }}><span style={{ display: "inline-block", width: 8, height: 8, borderRadius: 2, background: T.border, marginRight: 4, verticalAlign: "middle" }} />No data</span>
      </div>

      {/* Day rows */}
      <div style={{ display: "flex", flexDirection: "column", gap: 6 }}>
        {days.map(({ dayKey, dateStr, isToday }) => {
          const target = targets[dayKey] || {};
          const actual = actuals[dateStr] || {};
          const hasData = actual.calories > 0;

          return (
            <div key={dateStr} style={{
              background: isToday ? `${T.accent}08` : "transparent",
              border: isToday ? `1px solid ${T.accent}22` : `1px solid transparent`,
              borderRadius: 10, padding: "10px 12px",
            }}>
              <div style={{ display: "flex", alignItems: "center", gap: 10, marginBottom: 6 }}>
                <span style={{
                  fontFamily: "Bebas Neue, system-ui", fontSize: 14, letterSpacing: 1.5,
                  color: isToday ? T.accent : T.text, minWidth: 36,
                }}>{dayKey}</span>
                <span style={{ fontFamily: "JetBrains Mono, ui-monospace", fontSize: 9, color: T.muted }}>{String(dateStr).slice(5).split("-").reverse().join("/")}</span>
                {isToday && <span style={{ fontSize: 9, color: T.accent, fontFamily: "DM Sans", fontWeight: 700 }}>TODAY</span>}
                {!hasData && <span style={{ fontSize: 9, color: T.muted, fontFamily: "DM Sans", fontStyle: "italic" }}>No food logged</span>}
              </div>

              {hasData && (
                <div style={{ display: "grid", gridTemplateColumns: "repeat(4, 1fr)", gap: 6 }}>
                  {macros.map(m => {
                    const tgt = target[m.key] || 0;
                    const act = actual[m.key] || 0;
                    const pct = tgt > 0 ? Math.round((act / tgt) * 100) : null;
                    const barPct = pct !== null ? Math.min(pct, 150) : 0;
                    const col = pctColor(pct);

                    return (
                      <div key={m.key}>
                        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 3 }}>
                          <span style={{ fontSize: 9, fontFamily: "DM Sans", color: T.muted, fontWeight: 600 }}>{m.label}</span>
                          <span style={{ fontSize: 10, fontFamily: "JetBrains Mono, ui-monospace", color: col, fontWeight: 700 }}>
                            {pct !== null ? `${pct}%` : "—"}
                          </span>
                        </div>
                        {/* Bar */}
                        <div style={{ height: 6, background: T.border, borderRadius: 3, overflow: "hidden", position: "relative" }}>
                          {/* Target marker at 100% */}
                          <div style={{ position: "absolute", left: `${Math.min(100 / 1.5, 100)}%`, top: 0, bottom: 0, width: 1, background: `${T.text}33`, zIndex: 2 }} />
                          <div style={{
                            height: "100%", borderRadius: 3,
                            width: `${Math.min(barPct / 1.5, 100)}%`,
                            background: col,
                            transition: "width .3s ease",
                          }} />
                        </div>
                        <div style={{ display: "flex", justifyContent: "space-between", marginTop: 2 }}>
                          <span style={{ fontSize: 8, fontFamily: "JetBrains Mono, ui-monospace", color: T.muted }}>
                            {Math.round(act)}{m.key === "calories" ? "" : "g"}
                          </span>
                          <span style={{ fontSize: 8, fontFamily: "JetBrains Mono, ui-monospace", color: T.muted }}>
                            /{Math.round(tgt)}{m.key === "calories" ? "" : "g"}
                          </span>
                        </div>
                      </div>
                    );
                  })}
                </div>
              )}

              {!hasData && (
                <div style={{ display: "grid", gridTemplateColumns: "repeat(4, 1fr)", gap: 6 }}>
                  {macros.map(m => (
                    <div key={m.key}>
                      <div style={{ height: 6, background: T.border, borderRadius: 3 }} />
                      <div style={{ fontSize: 8, color: T.muted, marginTop: 2, fontFamily: "JetBrains Mono, ui-monospace", textAlign: "center" }}>—</div>
                    </div>
                  ))}
                </div>
              )}
            </div>
          );
        })}
      </div>
    </div>
  );
}

/* ─────────────────────────────────────────────────────────────────────────────
   Coach Messaging — 1-on-1 with athlete
────────────────────────────────────────────────────────────────────────────── */
function CoachMessaging({ athleteId, athleteName, token }) {
  // Threaded email-style messaging — mirrors the athlete inbox.
  const [threads, setThreads] = useState([]);
  const [threadsLoading, setThreadsLoading] = useState(true);
  const [view, setView] = useState("list"); // "list" | "thread" | "compose"
  const [activeThread, setActiveThread] = useState(null); // { threadId, subject }
  const [threadMessages, setThreadMessages] = useState([]);
  const [threadLoading, setThreadLoading] = useState(false);
  const [input, setInput] = useState("");
  const [composeSubject, setComposeSubject] = useState("");
  const [sending, setSending] = useState(false);
  const bottomRef = useRef(null);

  const loadThreads = async () => {
    try {
      const rows = await apiFetch(`/messages/threads/${athleteId}`, token);
      if (Array.isArray(rows)) setThreads(rows);
    } catch {}
    setThreadsLoading(false);
  };

  useEffect(() => { loadThreads(); }, [athleteId, token]);
  useEffect(() => {
    const i = setInterval(loadThreads, 15000);
    return () => clearInterval(i);
  }, [athleteId, token]);

  const openThread = async (thread) => {
    setActiveThread(thread);
    setView("thread");
    setInput("");
    setThreadLoading(true);
    try {
      const msgs = await apiFetch(`/messages/thread/${athleteId}/${thread.threadId}`, token);
      if (Array.isArray(msgs)) setThreadMessages(msgs);
    } catch { setThreadMessages([]); }
    setThreadLoading(false);
    loadThreads();
  };

  // Poll active thread
  useEffect(() => {
    if (view !== "thread" || !activeThread) return;
    const i = setInterval(async () => {
      try {
        const msgs = await apiFetch(`/messages/thread/${athleteId}/${activeThread.threadId}`, token);
        if (Array.isArray(msgs)) setThreadMessages(msgs);
      } catch {}
    }, 10000);
    return () => clearInterval(i);
  }, [view, activeThread?.threadId, athleteId, token]);

  useEffect(() => { bottomRef.current?.scrollIntoView({ behavior: "smooth" }); }, [threadMessages]);

  const sendReply = async () => {
    if (!input.trim() || sending || !activeThread) return;
    setSending(true);
    try {
      const msg = await apiFetch(`/messages/${athleteId}`, token, {
        method: "POST",
        body: JSON.stringify({
          content: input.trim(),
          threadId: activeThread.threadId > 0 ? activeThread.threadId : undefined,
          subject: activeThread.subject,
        }),
      });
      setThreadMessages(prev => [...prev, msg]);
      setInput("");
      loadThreads();
    } catch (e) { alert(e.message || "Send failed"); }
    setSending(false);
  };

  const sendNewThread = async () => {
    if (!input.trim() || !composeSubject.trim() || sending) return;
    setSending(true);
    try {
      const msg = await apiFetch(`/messages/${athleteId}`, token, {
        method: "POST",
        body: JSON.stringify({
          content: input.trim(),
          subject: composeSubject.trim(),
        }),
      });
      setInput("");
      setComposeSubject("");
      await loadThreads();
      setActiveThread({ threadId: msg.threadId, subject: msg.subject || composeSubject.trim() });
      setThreadMessages([msg]);
      setView("thread");
    } catch (e) { alert(e.message || "Send failed"); }
    setSending(false);
  };

  const handleSend = () => {
    if (view === "thread") sendReply();
    else if (view === "compose") sendNewThread();
  };

  const totalUnread = threads.reduce((n, t) => n + (t.unreadCount || 0), 0);

  return (
    <div style={{ display: "flex", height: 540, background: T.bg, borderRadius: 16, overflow: "hidden", border: `1px solid ${T.border}` }}>
      {/* Thread list */}
      <div style={{ width: 280, flexShrink: 0, borderRight: `1px solid ${T.border}`, display: "flex", flexDirection: "column", background: T.card }}>
        <div style={{ padding: "14px 16px", borderBottom: `1px solid ${T.border}`, display: "flex", justifyContent: "space-between", alignItems: "center" }}>
          <div>
            <div style={{ fontFamily: "Bebas Neue, system-ui", fontSize: 16, letterSpacing: 2, color: T.text }}>INBOX</div>
            <div style={{ fontFamily: "DM Sans", fontSize: 10, color: T.muted }}>
              {threads.length} thread{threads.length !== 1 ? "s" : ""}{totalUnread > 0 ? ` · ${totalUnread} unread` : ""}
            </div>
          </div>
          <button onClick={() => { setView("compose"); setActiveThread(null); setInput(""); setComposeSubject(""); }} style={{
            background: T.accent, color: T.bg, border: "none", borderRadius: 8,
            padding: "6px 12px", fontFamily: "Bebas Neue, system-ui", fontSize: 11, letterSpacing: 1, cursor: "pointer",
          }} type="button">✉ NEW</button>
        </div>

        <div style={{ overflowY: "auto", flex: 1 }}>
          {threadsLoading ? (
            <div style={{ padding: 20, color: T.muted, fontSize: 11, textAlign: "center" }}>Loading…</div>
          ) : threads.length === 0 ? (
            <div style={{ padding: 20, color: T.muted, fontSize: 11, textAlign: "center" }}>
              No messages yet. Click "NEW" to start a conversation.
            </div>
          ) : threads.map((t, idx) => {
            const isActive = view === "thread" && activeThread?.threadId === t.threadId;
            const hasUnread = (t.unreadCount || 0) > 0;
            return (
              <div key={t.threadId} onClick={() => openThread(t)} style={{
                padding: "12px 16px", borderBottom: idx < threads.length - 1 ? `1px solid ${T.border}15` : "none",
                background: isActive ? T.surface : hasUnread ? `${T.coachGreen}08` : "transparent",
                cursor: "pointer", position: "relative",
              }}
                onMouseEnter={(e) => { if (!isActive) e.currentTarget.style.background = T.surface; }}
                onMouseLeave={(e) => { if (!isActive) e.currentTarget.style.background = hasUnread ? `${T.coachGreen}08` : "transparent"; }}
              >
                {hasUnread && <div style={{ position: "absolute", left: 0, top: 0, bottom: 0, width: 3, background: T.coachGreen }} />}
                <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 3 }}>
                  <div style={{ fontFamily: "DM Sans", fontSize: 12, fontWeight: hasUnread ? 700 : 600, color: T.text, flex: 1, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>
                    {t.subject || "Conversation"}
                  </div>
                  {hasUnread && (
                    <div style={{ background: T.coachGreen, borderRadius: "50%", width: 16, height: 16, display: "flex", alignItems: "center", justifyContent: "center", marginLeft: 6, flexShrink: 0 }}>
                      <span style={{ fontFamily: "JetBrains Mono, ui-monospace", fontSize: 8, color: "#fff", fontWeight: 700 }}>{t.unreadCount}</span>
                    </div>
                  )}
                </div>
                <div style={{ fontFamily: "DM Sans", fontSize: 10, color: hasUnread ? T.text : T.muted, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>
                  {t.lastMessage || "No messages"}
                </div>
                <div style={{ display: "flex", justifyContent: "space-between", marginTop: 3 }}>
                  <span style={{ fontFamily: "JetBrains Mono, ui-monospace", fontSize: 8, color: T.border }}>
                    {t.messageCount} message{t.messageCount !== 1 ? "s" : ""}
                  </span>
                  {t.lastAt && (
                    <span style={{ fontFamily: "JetBrains Mono, ui-monospace", fontSize: 8, color: T.muted }}>
                      {new Date(t.lastAt).toLocaleDateString("en-GB", { day: "numeric", month: "short" })}
                    </span>
                  )}
                </div>
              </div>
            );
          })}
        </div>
      </div>

      {/* Main panel */}
      <div style={{ flex: 1, display: "flex", flexDirection: "column", background: T.bg }}>
        {view === "list" && (
          <div style={{ flex: 1, display: "flex", alignItems: "center", justifyContent: "center", flexDirection: "column", gap: 8 }}>
            <div style={{ fontSize: 32, opacity: 0.3 }}>✉</div>
            <div style={{ fontFamily: "DM Sans", fontSize: 12, color: T.muted }}>Select a thread or compose a new message</div>
          </div>
        )}

        {view === "compose" && (
          <div style={{ flex: 1, display: "flex", flexDirection: "column" }}>
            <div style={{ padding: "12px 18px", borderBottom: `1px solid ${T.border}`, display: "flex", alignItems: "center", gap: 10 }}>
              <button onClick={() => setView("list")} style={{ background: "none", border: "none", color: T.muted, cursor: "pointer", fontSize: 18, padding: 0 }}>←</button>
              <div style={{ fontFamily: "Bebas Neue, system-ui", fontSize: 16, letterSpacing: 2, color: T.text }}>NEW MESSAGE — {athleteName}</div>
            </div>
            <div style={{ padding: "12px 18px", borderBottom: `1px solid ${T.border}` }}>
              <div style={{ fontFamily: "DM Sans", fontSize: 9, color: T.muted, letterSpacing: 1, textTransform: "uppercase", marginBottom: 4 }}>Subject</div>
              <input
                autoFocus
                value={composeSubject}
                onChange={e => setComposeSubject(e.target.value)}
                placeholder="e.g. Weekly check-in, Plan update…"
                style={{ width: "100%", background: T.surface, border: `1px solid ${T.border}`, borderRadius: 8, padding: "8px 12px", color: T.text, fontFamily: "DM Sans", fontSize: 12, outline: "none" }}
              />
            </div>
            <div style={{ flex: 1, padding: "12px 18px" }}>
              <textarea
                value={input}
                onChange={e => setInput(e.target.value)}
                placeholder="Write your message…"
                style={{ width: "100%", height: "100%", background: T.surface, border: `1px solid ${T.border}`, borderRadius: 10, padding: "10px 14px", color: T.text, fontFamily: "DM Sans", fontSize: 12, outline: "none", resize: "none" }}
              />
            </div>
            <div style={{ padding: "10px 18px", borderTop: `1px solid ${T.border}`, display: "flex", justifyContent: "flex-end", gap: 8 }}>
              <button onClick={() => setView("list")} style={{
                background: "none", border: `1px solid ${T.border}`, borderRadius: 8,
                padding: "8px 14px", color: T.muted, fontFamily: "DM Sans", fontSize: 11, cursor: "pointer",
              }} type="button">Cancel</button>
              <button onClick={handleSend} disabled={sending || !input.trim() || !composeSubject.trim()} style={{
                background: input.trim() && composeSubject.trim() ? T.accent : T.border,
                color: input.trim() && composeSubject.trim() ? T.bg : T.muted,
                border: "none", borderRadius: 8, padding: "8px 16px",
                fontFamily: "Bebas Neue, system-ui", fontSize: 13, letterSpacing: 1.5,
                cursor: input.trim() && composeSubject.trim() ? "pointer" : "default",
              }} type="button">{sending ? "…" : "SEND"}</button>
            </div>
          </div>
        )}

        {view === "thread" && activeThread && (
          <div style={{ flex: 1, display: "flex", flexDirection: "column" }}>
            <div style={{ padding: "12px 18px", borderBottom: `1px solid ${T.border}`, display: "flex", alignItems: "center", gap: 10 }}>
              <button onClick={() => setView("list")} style={{ background: "none", border: "none", color: T.muted, cursor: "pointer", fontSize: 18, padding: 0 }}>←</button>
              <div style={{ flex: 1 }}>
                <div style={{ fontFamily: "Bebas Neue, system-ui", fontSize: 16, letterSpacing: 2, color: T.text }}>{activeThread.subject || "CONVERSATION"}</div>
                <div style={{ fontFamily: "DM Sans", fontSize: 10, color: T.muted }}>with {athleteName}</div>
              </div>
              <div style={{ display: "flex", gap: 10, alignItems: "center" }}>
                <div style={{ width: 6, height: 6, borderRadius: "50%", background: T.coachGreen, animation: "pulse 2s infinite" }} />
                <span style={{ fontFamily: "DM Sans", fontSize: 9, color: T.coachGreen }}>LIVE</span>
                <button
                  onClick={async () => {
                    if (!activeThread) return;
                    if (!window.confirm(`Delete this entire conversation for both you and ${athleteName}? This can't be undone.`)) return;
                    try {
                      await apiFetch(`/messages/threads/${athleteId}/${activeThread.threadId}`, token, { method: "DELETE" });
                      setView("list");
                      loadThreads();
                    } catch (e) { alert(e.message || "Could not delete the conversation"); }
                  }}
                  style={{ background: "none", border: "none", color: T.muted, fontSize: 15, cursor: "pointer", padding: 0 }}
                  title="Delete conversation for both sides"
                  type="button"
                >
                  🗑️
                </button>
              </div>
            </div>

            <div style={{ flex: 1, overflowY: "auto", padding: "12px 18px" }}>
              {threadLoading ? (
                <div style={{ color: T.muted, fontSize: 11, textAlign: "center", padding: 20 }}>Loading…</div>
              ) : threadMessages.length === 0 ? (
                <div style={{ color: T.muted, fontSize: 11, textAlign: "center", padding: 20 }}>No messages in this thread.</div>
              ) : threadMessages.map(m => {
                const isCoach = Number(m.fromId) !== Number(athleteId);
                return (
                  <div key={m.id} style={{ display: "flex", justifyContent: isCoach ? "flex-end" : "flex-start", marginBottom: 8 }}>
                    <div style={{
                      maxWidth: "75%", padding: "9px 13px", borderRadius: 14,
                      background: isCoach ? T.accent : T.surface,
                      color: isCoach ? T.bg : T.text,
                      borderBottomRightRadius: isCoach ? 4 : 14,
                      borderBottomLeftRadius: isCoach ? 14 : 4,
                    }}>
                      <div style={{ fontFamily: "DM Sans", fontSize: 9, color: isCoach ? `${T.bg}aa` : T.muted, marginBottom: 2 }}>
                        {m.fromName || (isCoach ? "You" : athleteName)}
                      </div>
                      <div style={{ fontFamily: "DM Sans", fontSize: 12, lineHeight: 1.4, whiteSpace: "pre-wrap" }}>{m.content}</div>
                      <div style={{ fontFamily: "JetBrains Mono, ui-monospace", fontSize: 8, color: isCoach ? `${T.bg}88` : T.muted, marginTop: 4, textAlign: "right" }}>
                        {m.created_at ? new Date(m.created_at).toLocaleString([], { day: "numeric", month: "short", hour: "2-digit", minute: "2-digit" }) : ""}
                      </div>
                    </div>
                  </div>
                );
              })}
              <div ref={bottomRef} />
            </div>

            <div style={{ padding: "10px 18px", borderTop: `1px solid ${T.border}`, display: "flex", gap: 8 }}>
              <input
                value={input}
                onChange={(e) => setInput(e.target.value)}
                onKeyDown={(e) => e.key === "Enter" && handleSend()}
                placeholder="Reply…"
                style={{
                  flex: 1, background: T.surface, border: `1px solid ${T.border}`, borderRadius: 10,
                  padding: "9px 13px", color: T.text, fontFamily: "DM Sans", fontSize: 12, outline: "none",
                }}
              />
              <button onClick={handleSend} disabled={sending || !input.trim()} style={{
                background: input.trim() ? T.accent : T.border, color: input.trim() ? T.bg : T.muted,
                border: "none", borderRadius: 10, padding: "9px 16px",
                fontFamily: "Bebas Neue, system-ui", fontSize: 13, letterSpacing: 1.5,
                cursor: input.trim() ? "pointer" : "default",
              }} type="button">{sending ? "…" : "REPLY"}</button>
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

/* ─────────────────────────────────────────────────────────────────────────────
   Broadcast Modal — send message to all athletes
────────────────────────────────────────────────────────────────────────────── */
function BroadcastModal({ token, athleteCount, onClose, endpoint, label }) {
  const [content, setContent] = useState("");
  const [sending, setSending] = useState(false);
  const [sent, setSent] = useState(false);
  const apiPath = endpoint || "/messages/broadcast";
  const desc = label || `Send to all ${athleteCount} athletes on your roster`;
  const btnLabel = label ? "SEND TO ALL CLIENTS" : "BROADCAST TO ALL";

  const send = async () => {
    if (!content.trim() || sending) return;
    setSending(true);
    try {
      await apiFetch(apiPath, token, {
        method: "POST",
        body: JSON.stringify({ content: content.trim() }),
      });
      setSent(true);
      setTimeout(() => onClose(), 1500);
    } catch (e) { alert(e.message); }
    setSending(false);
  };

  return (
    <div style={{ position: "fixed", inset: 0, background: "#000000d0", zIndex: 999, display: "flex", alignItems: "center", justifyContent: "center", padding: 20 }}
      onClick={(e) => e.target === e.currentTarget && onClose()}>
      <div style={{ width: "100%", maxWidth: 520, background: T.card, border: `1px solid ${T.accent}44`, borderRadius: 22, padding: 24, animation: "fadeUp .2s ease" }}>
        <div style={{ fontFamily: "Bebas Neue, system-ui", fontSize: 22, letterSpacing: 2, color: T.text, marginBottom: 6 }}>
          BROADCAST MESSAGE
        </div>
        <div style={{ fontFamily: "DM Sans", fontSize: 11, color: T.muted, marginBottom: 16 }}>
          {desc}
        </div>
        {sent ? (
          <div style={{ background: `${T.coachGreen}18`, border: `1px solid ${T.coachGreen}44`, borderRadius: 12, padding: 18, color: T.coachGreen, fontFamily: "DM Sans", fontSize: 13, textAlign: "center" }}>
            Message sent successfully
          </div>
        ) : (
          <>
            <textarea
              value={content}
              onChange={(e) => setContent(e.target.value)}
              placeholder="Type your message…"
              rows={4}
              style={{
                width: "100%", background: T.surface, border: `1px solid ${T.border}`, borderRadius: 12,
                padding: 14, color: T.text, fontFamily: "DM Sans", fontSize: 13, outline: "none", resize: "vertical",
              }}
            />
            <div style={{ display: "flex", gap: 10, marginTop: 14 }}>
              <button onClick={onClose} style={{
                flex: 1, background: "none", border: `1px solid ${T.border}`, borderRadius: 10, padding: 11,
                color: T.muted, fontFamily: "DM Sans", fontSize: 13, cursor: "pointer",
              }} type="button">Cancel</button>
              <button onClick={send} disabled={sending || !content.trim()} style={{
                flex: 2, background: content.trim() ? T.accent : T.border, color: content.trim() ? T.bg : T.muted,
                border: "none", borderRadius: 10, padding: 11,
                fontFamily: "Bebas Neue, system-ui", fontSize: 16, letterSpacing: 1.5,
                cursor: content.trim() && !sending ? "pointer" : "default",
              }} type="button">{sending ? "SENDING…" : btnLabel}</button>
            </div>
          </>
        )}
      </div>
    </div>
  );
}

/* ─────────────────────────────────────────────────────────────────────────────
   Broadcast Content Modal — send a YouTube video, PDF, or web link to
   specific clients or all clients at once.

   No backend changes required: this loops the existing per-athlete endpoint
   POST /coach-videos/:athleteId once for each selected recipient.

   The content `type` ("youtube" | "pdf" | "link") is folded into the existing
   `category` field as "type:<type>|<category>" so the client app can tell them
   apart without a schema change. (When you later add a real `type` column, you
   can send it as its own field and drop this encoding.)

   Props:
     - token         : auth token (same one used elsewhere)
     - athletes      : array of { id, name, ... } already loaded in the coach view
     - onClose       : () => void
────────────────────────────────────────────────────────────────────────────── */
function BroadcastContentModal({ token, athletes, onClose }) {
  const CATEGORIES = ["General", "Technique", "Nutrition", "Mindset", "Recovery", "Warmup"];
  const TYPES = [
    { key: "youtube", label: "🎬 YouTube", hint: "Paste a YouTube link" },
    { key: "pdf", label: "📄 PDF", hint: "Paste a shared PDF link (Drive/Dropbox — set to ‘anyone with link can view’)" },
    { key: "link", label: "🔗 Web Link", hint: "Paste any web address" },
  ];

  const [type, setType] = useState("youtube");
  const [form, setForm] = useState({ title: "", url: "", category: "General", notes: "" });
  const [selected, setSelected] = useState(() => new Set()); // athlete ids
  const [sendToAll, setSendToAll] = useState(true);
  const [sending, setSending] = useState(false);
  const [progress, setProgress] = useState({ done: 0, total: 0, failed: 0 });
  const [result, setResult] = useState(null); // null | { ok, failed }
  const [error, setError] = useState("");

  // YouTube ID extraction (same logic as the per-athlete video manager)
  const extractYouTubeId = (input) => {
    if (!input) return null;
    const s = String(input).trim();
    if (/^[A-Za-z0-9_-]{11}$/.test(s)) return s;
    let m = s.match(/[?&]v=([A-Za-z0-9_-]{11})/);
    if (m) return m[1];
    m = s.match(/youtu\.be\/([A-Za-z0-9_-]{11})/);
    if (m) return m[1];
    m = s.match(/\/(?:embed|shorts|v)\/([A-Za-z0-9_-]{11})/);
    if (m) return m[1];
    return null;
  };

  const previewId = type === "youtube" ? extractYouTubeId(form.url) : null;

  // Basic URL sanity check for pdf/link types
  const looksLikeUrl = (s) => {
    if (!s) return false;
    try { const u = new URL(s.trim()); return u.protocol === "http:" || u.protocol === "https:"; }
    catch { return false; }
  };

  const urlValid =
    type === "youtube" ? !!previewId : looksLikeUrl(form.url);

  const recipients = sendToAll ? athletes.map(a => a.id) : Array.from(selected);
  const canSend = form.title.trim() && urlValid && recipients.length > 0 && !sending;

  const toggleAthlete = (id) => {
    setSelected(prev => {
      const next = new Set(prev);
      if (next.has(id)) next.delete(id); else next.add(id);
      return next;
    });
  };

  const send = async () => {
    setError("");
    if (!form.title.trim()) { setError("Title is required"); return; }
    if (!urlValid) {
      setError(type === "youtube" ? "Paste a valid YouTube URL" : "Paste a valid http(s) URL"); return;
    }
    if (recipients.length === 0) { setError("Select at least one client (or choose ‘All clients’)"); return; }

    setSending(true);
    setProgress({ done: 0, total: recipients.length, failed: 0 });

    // Fold the content type into category so the client app can distinguish
    // videos / pdfs / links without a backend schema change.
    const encodedCategory = `type:${type}|${form.category}`;

    let ok = 0, failed = 0;
    for (const athleteId of recipients) {
      try {
        await apiFetch(`/coach-videos/${athleteId}`, token, {
          method: "POST",
          body: JSON.stringify({
            title: form.title.trim(),
            url: form.url.trim(),
            category: encodedCategory,
            notes: form.notes.trim() || null,
          }),
        });
        ok += 1;
      } catch (e) {
        failed += 1;
      }
      setProgress(p => ({ ...p, done: p.done + 1, failed }));
    }

    setSending(false);
    setResult({ ok, failed });
    if (failed === 0) {
      setTimeout(() => onClose(), 1600);
    }
  };

  const activeType = TYPES.find(t => t.key === type);

  return (
    <div
      style={{ position: "fixed", inset: 0, background: "#000000d0", zIndex: 999, display: "flex", alignItems: "center", justifyContent: "center", padding: 20 }}
      onClick={(e) => e.target === e.currentTarget && !sending && onClose()}
    >
      <div style={{ width: "100%", maxWidth: 620, maxHeight: "90vh", overflowY: "auto", background: T.card, border: `1px solid ${T.accent}44`, borderRadius: 22, padding: 24, animation: "fadeUp .2s ease" }}>
        <div style={{ fontFamily: "Bebas Neue, system-ui", fontSize: 22, letterSpacing: 2, color: T.text, marginBottom: 6 }}>
          SEND CONTENT TO CLIENTS
        </div>
        <div style={{ fontFamily: "DM Sans", fontSize: 11, color: T.muted, marginBottom: 18 }}>
          Share a video, PDF, or link with specific clients or your whole roster. It appears on their dashboard.
        </div>

        {result ? (
          <div style={{
            background: result.failed === 0 ? `${T.coachGreen}18` : `${T.warn}18`,
            border: `1px solid ${result.failed === 0 ? T.coachGreen : T.warn}44`,
            borderRadius: 12, padding: 18,
            color: result.failed === 0 ? T.coachGreen : T.warn,
            fontFamily: "DM Sans", fontSize: 13, textAlign: "center",
          }}>
            Sent to {result.ok} client{result.ok !== 1 ? "s" : ""}.
            {result.failed > 0 && <div style={{ marginTop: 6 }}>{result.failed} failed — you can try resending to those.</div>}
            {result.failed > 0 && (
              <button onClick={() => setResult(null)} style={{
                marginTop: 12, background: "none", border: `1px solid ${T.border}`, borderRadius: 8,
                padding: "8px 16px", color: T.text, fontFamily: "DM Sans", fontSize: 12, cursor: "pointer",
              }} type="button">Back</button>
            )}
          </div>
        ) : (
          <>
            {/* Content type selector */}
            <label style={labelStyle}>Content type</label>
            <div style={{ display: "flex", gap: 8, marginBottom: 14 }}>
              {TYPES.map(t => (
                <button
                  key={t.key}
                  onClick={() => { setType(t.key); setError(""); }}
                  type="button"
                  style={{
                    flex: 1,
                    background: type === t.key ? T.accent : T.surface,
                    color: type === t.key ? T.bg : T.text,
                    border: `1px solid ${type === t.key ? T.accent : T.border}`,
                    borderRadius: 10, padding: "10px 8px",
                    fontFamily: "DM Sans", fontSize: 12, fontWeight: 600, cursor: "pointer",
                  }}
                >{t.label}</button>
              ))}
            </div>

            {/* Title + Category */}
            <div style={{ display: "grid", gridTemplateColumns: "2fr 1fr", gap: 8, marginBottom: 10 }}>
              <div>
                <label style={labelStyle}>Title *</label>
                <input value={form.title} onChange={(e) => setForm(p => ({ ...p, title: e.target.value }))} placeholder="e.g. Squat technique breakdown" style={inputStyle} />
              </div>
              <div>
                <label style={labelStyle}>Category</label>
                <select value={form.category} onChange={(e) => setForm(p => ({ ...p, category: e.target.value }))} style={inputStyle}>
                  {CATEGORIES.map(c => <option key={c} value={c}>{c}</option>)}
                </select>
              </div>
            </div>

            {/* URL */}
            <div style={{ marginBottom: 10 }}>
              <label style={labelStyle}>{activeType.label.replace(/^[^ ]+ /, "")} URL *</label>
              <input
                value={form.url}
                onChange={(e) => setForm(p => ({ ...p, url: e.target.value }))}
                placeholder={activeType.hint}
                style={inputStyle}
              />
            </div>

            {/* YouTube preview */}
            {type === "youtube" && previewId && (
              <div style={{ marginBottom: 10, display: "flex", gap: 10, alignItems: "center", background: T.bg, border: `1px solid ${T.border}`, borderRadius: 8, padding: 8 }}>
                <img src={`https://img.youtube.com/vi/${previewId}/default.jpg`} alt="Preview" style={{ width: 80, height: 60, borderRadius: 4, objectFit: "contain" }} />
                <div style={{ fontFamily: "DM Sans", fontSize: 11, color: T.coachGreen }}>
                  ✓ Video detected — ID: <span style={{ fontFamily: "JetBrains Mono, ui-monospace" }}>{previewId}</span>
                </div>
              </div>
            )}

            {/* PDF / link validity hint */}
            {type !== "youtube" && form.url && (
              <div style={{ marginBottom: 10, fontFamily: "DM Sans", fontSize: 11, color: urlValid ? T.coachGreen : T.danger }}>
                {urlValid ? "✓ Looks like a valid link" : "Enter a full http(s):// address"}
              </div>
            )}

            {type === "pdf" && (
              <div style={{ marginBottom: 10, fontFamily: "DM Sans", fontSize: 10, color: T.muted, lineHeight: 1.5, background: T.surface, border: `1px solid ${T.border}`, borderRadius: 8, padding: 10 }}>
                Tip: upload your PDF to Google Drive or Dropbox, set sharing to “anyone with the link can view,” then paste that link here.
              </div>
            )}

            {/* Notes */}
            <div style={{ marginBottom: 16 }}>
              <label style={labelStyle}>Notes (optional)</label>
              <input value={form.notes} onChange={(e) => setForm(p => ({ ...p, notes: e.target.value }))} placeholder="Any context or instructions for the client" style={inputStyle} />
            </div>

            {/* Recipients */}
            <label style={labelStyle}>Recipients</label>
            <div style={{ display: "flex", gap: 8, marginBottom: 10 }}>
              <button
                onClick={() => setSendToAll(true)}
                type="button"
                style={{
                  flex: 1,
                  background: sendToAll ? T.coachGreen : T.surface,
                  color: sendToAll ? T.bg : T.text,
                  border: `1px solid ${sendToAll ? T.coachGreen : T.border}`,
                  borderRadius: 10, padding: "10px 8px",
                  fontFamily: "DM Sans", fontSize: 12, fontWeight: 600, cursor: "pointer",
                }}
              >All clients ({athletes.length})</button>
              <button
                onClick={() => setSendToAll(false)}
                type="button"
                style={{
                  flex: 1,
                  background: !sendToAll ? T.accent : T.surface,
                  color: !sendToAll ? T.bg : T.text,
                  border: `1px solid ${!sendToAll ? T.accent : T.border}`,
                  borderRadius: 10, padding: "10px 8px",
                  fontFamily: "DM Sans", fontSize: 12, fontWeight: 600, cursor: "pointer",
                }}
              >Specific clients{!sendToAll && selected.size > 0 ? ` (${selected.size})` : ""}</button>
            </div>

            {/* Specific-client picker */}
            {!sendToAll && (
              <div style={{ maxHeight: 200, overflowY: "auto", border: `1px solid ${T.border}`, borderRadius: 10, padding: 8, marginBottom: 14 }}>
                {athletes.length === 0 ? (
                  <div style={{ color: T.muted, fontSize: 12, textAlign: "center", padding: 12 }}>No clients on your roster yet.</div>
                ) : athletes.map(a => {
                  const checked = selected.has(a.id);
                  return (
                    <label key={a.id} style={{ display: "flex", alignItems: "center", gap: 10, padding: "8px 6px", cursor: "pointer", borderRadius: 8, background: checked ? `${T.accent}14` : "transparent" }}>
                      <input type="checkbox" checked={checked} onChange={() => toggleAthlete(a.id)} style={{ accentColor: T.accent, width: 16, height: 16 }} />
                      <span style={{ fontFamily: "DM Sans", fontSize: 13, color: T.text }}>{a.name}</span>
                      {a.email && <span style={{ fontFamily: "DM Sans", fontSize: 11, color: T.muted, marginLeft: "auto" }}>{a.email}</span>}
                    </label>
                  );
                })}
              </div>
            )}

            {error && (
              <div style={{ background: `${T.danger}18`, border: `1px solid ${T.danger}44`, borderRadius: 8, padding: "8px 12px", marginBottom: 12, fontSize: 11, color: T.danger, fontFamily: "DM Sans" }}>
                {error}
              </div>
            )}

            {sending && (
              <div style={{ marginBottom: 12, fontFamily: "DM Sans", fontSize: 12, color: T.muted }}>
                Sending… {progress.done}/{progress.total}{progress.failed > 0 ? ` (${progress.failed} failed)` : ""}
              </div>
            )}

            <div style={{ display: "flex", gap: 10 }}>
              <button onClick={() => !sending && onClose()} style={{
                flex: 1, background: "none", border: `1px solid ${T.border}`, borderRadius: 10, padding: 11,
                color: T.muted, fontFamily: "DM Sans", fontSize: 13, cursor: sending ? "default" : "pointer",
              }} type="button">Cancel</button>
              <button onClick={send} disabled={!canSend} style={{
                flex: 2, background: canSend ? T.accent : T.border, color: canSend ? T.bg : T.muted,
                border: "none", borderRadius: 10, padding: 11,
                fontFamily: "Bebas Neue, system-ui", fontSize: 16, letterSpacing: 1.5,
                cursor: canSend ? "pointer" : "default",
              }} type="button">
                {sending ? "SENDING…" : sendToAll ? `SEND TO ALL ${athletes.length}` : `SEND TO ${recipients.length || 0}`}
              </button>
            </div>
          </>
        )}
      </div>
    </div>
  );
}


/* ─────────────────────────────────────────────────────────────────────────────
   Admin Coach Overview — shows all coaches, their athletes, and reassignment
────────────────────────────────────────────────────────────────────────────── */
function AdminCoachOverview({ token, myId }) {
  const [coaches, setCoaches] = useState([]);
  const [loading, setLoading] = useState(true);
  const [selectedCoach, setSelectedCoach] = useState(null);
  const [athletes, setAthletes] = useState([]);
  const [loadingAthletes, setLoadingAthletes] = useState(false);
  const [reassigning, setReassigning] = useState(null); // athleteId being reassigned
  const [targetCoach, setTargetCoach] = useState("");
  const [showBroadcastAll, setShowBroadcastAll] = useState(false);

  const totalAthletes = coaches.reduce((s, c) => s + (c.athleteCount || 0), 0);

  const loadCoaches = async () => {
    try {
      const rows = await apiFetch("/admin/coach-overview", token);
      setCoaches(Array.isArray(rows) ? rows : []);
    } catch {}
    setLoading(false);
  };

  useEffect(() => { loadCoaches(); }, [token]);

  const openCoach = async (coach) => {
    setSelectedCoach(coach);
    setLoadingAthletes(true);
    try {
      const rows = await apiFetch(`/admin/coach/${coach.id}/athletes`, token);
      let list = Array.isArray(rows) ? rows : [];
      setAthletes(list);
      // Compute weekly adherence per athlete the same way the detail view does.
      list.forEach(async (athlete) => {
        const adh = await computeWeeklyAdherence(athlete.id, token);
        if (!adh) return;
        setAthletes((prev) => prev.map((a) => a.id === athlete.id ? { ...a, ...adh } : a));
      });
    } catch { setAthletes([]); }
    setLoadingAthletes(false);
  };

  const reassignAthlete = async (athleteId) => {
    if (!targetCoach) return;
    try {
      await apiFetch("/admin/reassign", token, {
        method: "PUT",
        body: JSON.stringify({ athleteId, newCoachId: Number(targetCoach) }),
      });
      setReassigning(null);
      setTargetCoach("");
      // Reload
      await openCoach(selectedCoach);
      await loadCoaches();
    } catch (e) { alert(e.message); }
  };

  if (loading) return <div style={{ color: T.muted, fontSize: 12, padding: 18 }}>Loading coaches…</div>;

  if (selectedCoach) {
    return (
      <div style={{ display: "flex", flexDirection: "column", gap: 16, animation: "fadeUp .2s ease" }}>
        <div style={{ display: "flex", alignItems: "center", gap: 14 }}>
          <button onClick={() => { setSelectedCoach(null); setAthletes([]); }} style={{
            background: T.card, border: `1px solid ${T.border}`, borderRadius: 8, padding: "6px 14px",
            color: T.muted, fontFamily: "DM Sans", fontSize: 12, cursor: "pointer",
          }} type="button">← All Coaches</button>
          <div>
            <span style={{ fontFamily: "Bebas Neue, system-ui", fontSize: 22, letterSpacing: 1.5, color: T.text }}>
              {selectedCoach.name.toUpperCase()}
            </span>
            <span style={{ fontFamily: "DM Sans", fontSize: 11, color: T.muted, marginLeft: 10 }}>
              {selectedCoach.athleteCount} athletes
              {selectedCoach.adherencePct !== null && <> · {selectedCoach.adherencePct}% adherence</>}
            </span>
          </div>
        </div>

        <div style={{ background: T.card, border: `1px solid ${T.border}`, borderRadius: 20, overflow: "hidden" }}>
          <div style={{ padding: "14px 18px", borderBottom: `1px solid ${T.border}` }}>
            <div style={{ fontFamily: "Bebas Neue, system-ui", fontSize: 16, letterSpacing: 2 }}>ATHLETES</div>
          </div>
          {loadingAthletes ? <div style={{ padding: 18, color: T.muted }}>Loading…</div> :
           athletes.length === 0 ? <div style={{ padding: 18, color: T.muted }}>No athletes assigned to this coach.</div> :
           athletes.map((a, idx) => (
            <div key={a.id} style={{
              padding: "14px 18px", borderBottom: idx < athletes.length - 1 ? `1px solid ${T.border}` : "none",
              display: "flex", alignItems: "center", gap: 12,
            }}>
              <Avatar initials={initialsOf(a.name)} color={T.accent} size={36} />
              <div style={{ flex: 1 }}>
                <span style={{ fontWeight: 700, color: T.text }}>{a.name}</span>
                <Badge label={a.sport || "ATHLETE"} color={T.coachGreen} />
                <div style={{ fontFamily: "JetBrains Mono, ui-monospace", fontSize: 10, color: T.muted, marginTop: 2 }}>{a.email}</div>
              </div>
              <AdherenceCells a={a} />
              {reassigning === a.id ? (
                <div style={{ display: "flex", gap: 6, alignItems: "center" }}>
                  <select value={targetCoach} onChange={(e) => setTargetCoach(e.target.value)} style={{
                    background: T.surface, border: `1px solid ${T.border}`, borderRadius: 6, padding: "4px 8px",
                    color: T.text, fontFamily: "DM Sans", fontSize: 11, outline: "none",
                  }}>
                    <option value="" style={{ background: T.bg }}>Select coach…</option>
                    {coaches.filter(c => c.id !== selectedCoach.id).map(c => (
                      <option key={c.id} value={c.id} style={{ background: T.bg }}>{c.name}</option>
                    ))}
                  </select>
                  <button onClick={() => reassignAthlete(a.id)} disabled={!targetCoach} style={{
                    background: targetCoach ? T.accent : T.border, color: targetCoach ? T.bg : T.muted,
                    border: "none", borderRadius: 6, padding: "4px 10px",
                    fontFamily: "Bebas Neue, system-ui", fontSize: 11, cursor: targetCoach ? "pointer" : "default",
                  }} type="button">MOVE</button>
                  <button onClick={() => { setReassigning(null); setTargetCoach(""); }} style={{
                    background: "none", border: `1px solid ${T.border}`, borderRadius: 6, padding: "4px 8px",
                    color: T.muted, fontSize: 10, cursor: "pointer",
                  }} type="button">✕</button>
                </div>
              ) : (
                <button onClick={() => setReassigning(a.id)} style={{
                  background: "none", border: `1px solid ${T.accent}44`, borderRadius: 8, padding: "6px 12px",
                  color: T.accent, fontFamily: "DM Sans", fontSize: 11, cursor: "pointer",
                }} type="button">Reassign</button>
              )}
            </div>
          ))}
        </div>
      </div>
    );
  }

  return (
    <div style={{ display: "flex", flexDirection: "column", gap: 16 }}>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
        <div>
          <div style={{ fontFamily: "Bebas Neue, system-ui", fontSize: 28, letterSpacing: 2 }}>COACH OVERVIEW</div>
          <div style={{ fontFamily: "DM Sans", fontSize: 12, color: T.muted, marginTop: 4 }}>
            Click a coach to see their athletes and reassign between coaches.
          </div>
        </div>
        <button
          onClick={() => setShowBroadcastAll(true)}
          disabled={totalAthletes === 0}
          style={{
            background: "none",
            border: `1px solid ${T.accent}44`,
            color: T.accent,
            borderRadius: 10,
            padding: "10px 18px",
            fontFamily: "Bebas Neue, system-ui",
            fontSize: 14,
            letterSpacing: 1.5,
            cursor: totalAthletes > 0 ? "pointer" : "default",
            opacity: totalAthletes > 0 ? 1 : 0.5,
          }}
          type="button"
        >
          📢 MESSAGE ALL CLIENTS ({totalAthletes})
        </button>
      </div>
      <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fill, minmax(260px, 1fr))", gap: 12 }}>
        {coaches.map(c => (
          <div key={c.id} onClick={() => openCoach(c)} style={{
            background: T.card, border: `1px solid ${T.border}`, borderRadius: 16, padding: 18,
            cursor: "pointer", transition: "border-color .2s",
          }}
            onMouseEnter={(e) => e.currentTarget.style.borderColor = T.accent + "55"}
            onMouseLeave={(e) => e.currentTarget.style.borderColor = T.border}>
            <div style={{ display: "flex", alignItems: "center", gap: 12, marginBottom: 12 }}>
              <Avatar initials={initialsOf(c.name)} color={c.role === "admin" ? T.accent : T.coachGreen} size={44} />
              <div>
                <div style={{ fontWeight: 700, color: T.text }}>{c.name}</div>
                <Badge label={c.role.toUpperCase()} color={c.role === "admin" ? T.accent : T.coachGreen} />
              </div>
            </div>
            <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 8 }}>
              <div style={{ background: T.surface, borderRadius: 10, padding: "8px 10px" }}>
                <div style={{ fontFamily: "Bebas Neue, system-ui", fontSize: 22, color: T.accent }}>{c.athleteCount}</div>
                <div style={{ fontFamily: "DM Sans", fontSize: 9, color: T.muted, letterSpacing: 0.8 }}>ATHLETES</div>
              </div>
              <div style={{ background: T.surface, borderRadius: 10, padding: "8px 10px" }}>
                <div style={{ fontFamily: "Bebas Neue, system-ui", fontSize: 22, color: c.adherencePct !== null && c.adherencePct >= 70 ? T.coachGreen : c.adherencePct !== null ? T.warn : T.muted }}>
                  {c.adherencePct !== null ? `${c.adherencePct}%` : "—"}
                </div>
                <div style={{ fontFamily: "DM Sans", fontSize: 9, color: T.muted, letterSpacing: 0.8 }}>ADHERENCE</div>
              </div>
            </div>
          </div>
        ))}
      </div>
      {showBroadcastAll && (
        <BroadcastModal
          token={token}
          athleteCount={totalAthletes}
          onClose={() => setShowBroadcastAll(false)}
          endpoint="/messages/broadcast-all"
          label={`Send to all ${totalAthletes} clients across all coaches`}
        />
      )}
    </div>
  );
}

/* ─────────────────────────────────────────────────────────────────────────────
   Coach Inbox — unified view of all athlete conversations
────────────────────────────────────────────────────────────────────────────── */
function CoachInbox({ athletes, token, onBroadcast, myId }) {
  const [activeId, setActiveId] = useState(null); // "athleteId-chat" or "athleteId-checkin"
  const [messages, setMessages] = useState([]);
  const [reactFor, setReactFor] = useState(null);
  const REACT_SET = ["\ud83d\udc4d", "\u2764\ufe0f", "\ud83d\udd25", "\ud83d\udcaa", "\ud83d\ude02"];
  const deleteMsg = async (messageId) => {
    setReactFor(null);
    if (!window.confirm("Delete this message for both you and the athlete?")) return;
    setMessages((prev) => prev.filter((m) => m.id !== messageId));
    try {
      await apiFetch(`/messages/${messageId}`, token, { method: "DELETE" });
    } catch (e) { alert(e.message || "Could not delete the message"); }
  };

  const reactTo = async (messageId, emoji) => {
    setReactFor(null);
    const current = messages.find((m) => m.id === messageId)?.reactions?.find((r) => Number(r.userId) === Number(myId));
    setMessages((prev) => prev.map((m) => {
      if (m.id !== messageId) return m;
      const others = (m.reactions || []).filter((r) => Number(r.userId) !== Number(myId));
      const next = current?.emoji === emoji ? others : [...others, { userId: myId, emoji }];
      return { ...m, reactions: next };
    }));
    try {
      await apiFetch(`/messages/${messageId}/reaction`, token, {
        method: "PUT",
        body: JSON.stringify({ emoji: current?.emoji === emoji ? null : emoji }),
      });
    } catch {}
  };
  const [unreadMap, setUnreadMap] = useState({}); // { athleteId: count }
  const [input, setInput] = useState("");
  const [sending, setSending] = useState(false);
  const [loadingChat, setLoadingChat] = useState(false);
  const bottomRef = useRef(null);

  // Load unread counts
  const loadUnread = async () => {
    try {
      const rows = await apiFetch("/messages-unread", token);
      const map = {};
      (Array.isArray(rows) ? rows : []).forEach(r => { map[r.fromId] = r.count; });
      setUnreadMap(map);
    } catch {}
  };
  useEffect(() => { loadUnread(); }, [token]);
  useEffect(() => {
    const interval = setInterval(loadUnread, 15 * 1000);
    return () => clearInterval(interval);
  }, [token]);

  const msgFilter = activeId && String(activeId).endsWith("-checkin") ? "checkin" : "chat";
  const athleteIdFromActive = activeId ? parseInt(String(activeId).replace(/-checkin$/, "").replace(/-chat$/, ""), 10) : null;

  // Load chat for active athlete (filter by type from thread id)
  const loadChat = async (aid) => {
    if (!aid) return;
    setLoadingChat(true);
    try {
      const url = msgFilter === "checkin" ? `/messages/${aid}?type=checkin` : `/messages/${aid}?type=chat`;
      const msgs = await apiFetch(url, token);
      if (Array.isArray(msgs)) setMessages(msgs);
      // Clear unread for this athlete
      setUnreadMap(prev => ({ ...prev, [aid]: 0 }));
    } catch { setMessages([]); }
    setLoadingChat(false);
  };

  useEffect(() => { if (athleteIdFromActive) loadChat(athleteIdFromActive); }, [activeId, athleteIdFromActive, msgFilter]);
  // Poll active chat
  useEffect(() => {
    if (!athleteIdFromActive) return;
    const interval = setInterval(() => loadChat(athleteIdFromActive), 12 * 1000);
    return () => clearInterval(interval);
  }, [activeId, athleteIdFromActive]);
  useEffect(() => { bottomRef.current?.scrollIntoView({ behavior: "smooth" }); }, [messages]);

  const send = async () => {
    if (!input.trim() || !athleteIdFromActive || sending) return;
    setSending(true);
    try {
      const msg = await apiFetch(`/messages/${athleteIdFromActive}`, token, {
        method: "POST", body: JSON.stringify({
          content: input.trim(),
          messageType: msgFilter === "checkin" ? "checkin" : "chat",
        }),
      });
      setMessages(prev => [...prev, msg]);
      setInput("");
    } catch (e) { alert(e.message); }
    setSending(false);
  };

  const totalUnread = Object.values(unreadMap).reduce((s, c) => s + c, 0);
  const activeAthlete = athletes.find(a => a.id === athleteIdFromActive);

  // Two threads per athlete: Chat and Check-ins (separate conversations)
  const sorted = [...athletes].sort((a, b) => {
    const ua = unreadMap[a.id] || 0, ub = unreadMap[b.id] || 0;
    if (ua > 0 && ub === 0) return -1;
    if (ub > 0 && ua === 0) return 1;
    return a.name.localeCompare(b.name);
  });
  const threadList = [];
  sorted.forEach((a) => {
    threadList.push({ id: `${a.id}-chat`, athleteId: a.id, name: a.name, sub: "Chat", avatar: a.avatar, avatarColor: a.avatarColor, unread: unreadMap[a.id] || 0 });
    threadList.push({ id: `${a.id}-checkin`, athleteId: a.id, name: a.name, sub: "Check-in notes", avatar: a.avatar, avatarColor: a.avatarColor, unread: 0 });
  });

  return (
    <div style={{ display: "flex", height: "calc(100vh - 140px)", borderRadius: 20, overflow: "hidden", border: `1px solid ${T.border}`, background: T.bg }}>
      {/* ── LEFT: Thread list ── */}
      <div style={{ width: 300, flexShrink: 0, borderRight: `1px solid ${T.border}`, display: "flex", flexDirection: "column", background: T.card }}>
        <div style={{ padding: "16px 18px", borderBottom: `1px solid ${T.border}`, display: "flex", justifyContent: "space-between", alignItems: "center" }}>
          <div>
            <div style={{ fontFamily: "Bebas Neue, system-ui", fontSize: 18, letterSpacing: 2, color: T.text }}>MESSAGES</div>
            <div style={{ fontFamily: "DM Sans", fontSize: 10, color: T.muted }}>{threadList.length} conversations</div>
          </div>
          <div style={{ display: "flex", gap: 6, alignItems: "center" }}>
            {totalUnread > 0 && (
              <div style={{ background: T.danger, borderRadius: 10, padding: "2px 8px", fontFamily: "JetBrains Mono, ui-monospace", fontSize: 10, color: "#fff", fontWeight: 700 }}>{totalUnread}</div>
            )}
            <button onClick={onBroadcast} style={{
              background: "none", border: `1px solid ${T.accent}44`, borderRadius: 6, padding: "4px 8px",
              color: T.accent, fontFamily: "DM Sans", fontSize: 9, cursor: "pointer",
            }} type="button">📢 All</button>
          </div>
        </div>

        <div style={{ overflowY: "auto", flex: 1 }}>
          {threadList.map((t, idx) => {
            const isActive = activeId === t.id;
            return (
              <div key={t.id} onClick={() => { setActiveId(t.id); setInput(""); }} style={{
                padding: "12px 18px", borderBottom: idx < threadList.length - 1 ? `1px solid ${T.border}` : "none",
                background: isActive ? T.surface : t.unread > 0 ? `${T.coachGreen}08` : "transparent",
                cursor: "pointer", display: "flex", gap: 10, alignItems: "center", transition: "background .15s",
              }}
                onMouseEnter={(e) => { if (!isActive) e.currentTarget.style.background = T.surface; }}
                onMouseLeave={(e) => { if (!isActive) e.currentTarget.style.background = t.unread > 0 ? `${T.coachGreen}08` : "transparent"; }}
              >
                {t.unread > 0 && <div style={{ position: "absolute", left: 0, top: 0, bottom: 0, width: 3, background: T.coachGreen, borderRadius: "4px 0 0 4px" }} />}
                <Avatar initials={t.avatar || initialsOf(t.name)} color={t.avatarColor || T.accent} size={36} />
                <div style={{ flex: 1, minWidth: 0 }}>
                  <div style={{ fontFamily: "DM Sans", fontSize: 12, fontWeight: t.unread > 0 ? 700 : 500, color: T.text }}>{t.name}</div>
                  <div style={{ fontFamily: "DM Sans", fontSize: 10, color: T.muted }}>{t.sub}</div>
                </div>
                {t.unread > 0 && (
                  <div style={{ background: T.coachGreen, borderRadius: "50%", width: 18, height: 18, display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0 }}>
                    <span style={{ fontFamily: "JetBrains Mono, ui-monospace", fontSize: 9, color: "#fff", fontWeight: 700 }}>{t.unread}</span>
                  </div>
                )}
              </div>
            );
          })}
        </div>
      </div>

      {/* ── RIGHT: Active chat ── */}
      <div style={{ flex: 1, display: "flex", flexDirection: "column" }}>
        {!activeId ? (
          <div style={{ flex: 1, display: "flex", alignItems: "center", justifyContent: "center", flexDirection: "column", gap: 12 }}>
            <div style={{ fontSize: 40, opacity: 0.3 }}>💬</div>
            <div style={{ fontFamily: "DM Sans", fontSize: 14, color: T.muted }}>Select an athlete to start messaging</div>
          </div>
        ) : (
          <>
            <div style={{ padding: "14px 20px", borderBottom: `1px solid ${T.border}`, display: "flex", alignItems: "center", gap: 12, flexWrap: "wrap" }}>
              <Avatar initials={activeAthlete?.avatar || "?"} color={activeAthlete?.avatarColor || T.accent} size={36} />
              <div style={{ flex: 1 }}>
                <div style={{ fontFamily: "DM Sans", fontSize: 14, fontWeight: 700, color: T.text }}>{activeAthlete?.name}</div>
                <div style={{ fontFamily: "DM Sans", fontSize: 10, color: T.muted }}>{activeAthlete?.sport || "Athlete"} · Live</div>
              </div>
              <div style={{ fontFamily: "DM Sans", fontSize: 10, color: T.muted }}>{msgFilter === "checkin" ? "Check-in notes" : "Chat"}</div>
              <div style={{ display: "flex", gap: 4, alignItems: "center", marginLeft: "auto" }}>
                <div style={{ width: 6, height: 6, borderRadius: "50%", background: T.coachGreen, animation: "pulse 2s infinite" }} />
                <span style={{ fontFamily: "DM Sans", fontSize: 9, color: T.coachGreen }}>LIVE</span>
              </div>
            </div>

            <div style={{ flex: 1, overflowY: "auto", padding: "16px 20px" }}>
              {loadingChat ? <div style={{ color: T.muted, fontSize: 12, textAlign: "center", padding: 20 }}>Loading…</div> :
               messages.length === 0 ? (
                <div style={{ textAlign: "center", color: T.muted, fontFamily: "DM Sans", fontSize: 12, padding: 30 }}>
                  No messages yet. Start the conversation with {activeAthlete?.name}!
                </div>
              ) : messages.map((m) => {
                const isCoach = Number(m.fromId) !== Number(athleteIdFromActive);
                const senderName = m.fromName || (isCoach ? "Coach" : activeAthlete?.name || "Athlete");
                return (
                  <div key={m.id} style={{ display: "flex", flexDirection: "column", alignItems: isCoach ? "flex-end" : "flex-start", marginBottom: 10 }}>
                    <div
                      onClick={() => setReactFor(reactFor === m.id ? null : m.id)}
                      style={{ maxWidth: "75%", padding: "10px 14px", borderRadius: 14, background: isCoach ? T.accent : T.surface, color: isCoach ? T.bg : T.text, borderBottomRightRadius: isCoach ? 4 : 14, borderBottomLeftRadius: isCoach ? 14 : 4, cursor: "pointer" }}>
                      <div style={{ fontFamily: "DM Sans", fontSize: 10, color: isCoach ? `${T.bg}aa` : T.muted, marginBottom: 2 }}>{senderName}</div>
                      <div style={{ fontFamily: "DM Sans", fontSize: 12, lineHeight: 1.5 }}>{m.content}</div>
                      <div style={{ fontFamily: "JetBrains Mono, ui-monospace", fontSize: 8, color: isCoach ? `${T.bg}88` : T.muted, marginTop: 4, textAlign: "right" }}>
                        {m.created_at ? new Date(m.created_at).toLocaleString([], { month: "short", day: "numeric", hour: "2-digit", minute: "2-digit" }) : ""}
                        {m.messageType === "broadcast" && " · 📢 Announcement"}
                      </div>
                    </div>
                    {(m.reactions || []).length > 0 && (
                      <div style={{ display: "flex", gap: 4, marginTop: 3 }}>
                        {(m.reactions || []).map((r, i) => (
                          <span key={i} onClick={() => Number(r.userId) === Number(myId) && reactTo(m.id, r.emoji)}
                            style={{ background: T.surface, border: `1px solid ${Number(r.userId) === Number(myId) ? T.accent : T.border}`, borderRadius: 10, padding: "1px 7px", fontSize: 12, cursor: Number(r.userId) === Number(myId) ? "pointer" : "default" }}>
                            {r.emoji}
                          </span>
                        ))}
                      </div>
                    )}
                    {reactFor === m.id && (
                      <div style={{ display: "flex", gap: 6, marginTop: 5, alignItems: "center", background: T.card, border: `1px solid ${T.border}`, borderRadius: 12, padding: "5px 10px" }}>
                        {REACT_SET.map((e) => (
                          <span key={e} onClick={() => reactTo(m.id, e)} style={{ fontSize: 18, cursor: "pointer" }}>{e}</span>
                        ))}
                        {isCoach && (
                          <span onClick={() => deleteMsg(m.id)} style={{ fontSize: 15, cursor: "pointer", marginLeft: 6, paddingLeft: 10, borderLeft: `1px solid ${T.border}` }} title="Delete for both sides">🗑️</span>
                        )}
                      </div>
                    )}
                  </div>
                );
              })}
              <div ref={bottomRef} />
            </div>

            <div style={{ padding: "12px 20px", borderTop: `1px solid ${T.border}`, display: "flex", gap: 8 }}>
              <input value={input} onChange={(e) => setInput(e.target.value)}
                onKeyDown={(e) => e.key === "Enter" && send()}
                placeholder={`Message ${activeAthlete?.name}…`}
                style={{ flex: 1, background: T.surface, border: `1px solid ${T.border}`, borderRadius: 10, padding: "10px 14px", color: T.text, fontFamily: "DM Sans", fontSize: 12, outline: "none" }}
              />
              <button onClick={send} disabled={sending || !input.trim()} style={{
                background: input.trim() ? T.accent : T.border, color: input.trim() ? T.bg : T.muted,
                border: "none", borderRadius: 10, padding: "10px 16px",
                fontFamily: "Bebas Neue, system-ui", fontSize: 14, letterSpacing: 1.5,
                cursor: input.trim() ? "pointer" : "default",
              }} type="button">{sending ? "…" : "SEND"}</button>
            </div>
          </>
        )}
      </div>
    </div>
  );
}

function AthleteDetail({ athlete, token, onBack, onDelete }) {
  const [tab, setTab] = useState("nutrition");
  const [editing, setEditing] = useState(false);
  const [deleting, setDeleting] = useState(false);
  const [confirmDelete, setConfirmDelete] = useState(false);
  const [resending, setResending] = useState(false);
  const [confirmResend, setConfirmResend] = useState(false);
  const [isActive, setIsActive] = useState(athlete.active !== false);
  const [showTransfer, setShowTransfer] = useState(false);
  const [coachList, setCoachList] = useState([]);
  const [transferTo, setTransferTo] = useState("");
  const [transferring, setTransferring] = useState(false);
  const [initialGoals, setInitialGoals] = useState(() => ({
    calories: athlete.macroGoals?.calories ?? 2500,
    protein: athlete.macroGoals?.protein ?? 180,
    carbs: athlete.macroGoals?.carbs ?? 280,
    fat: athlete.macroGoals?.fat ?? 75,
  }));
  const [goals, setGoals] = useState(() => initialGoals);
  const [saved, setSaved] = useState(false);

  // ── Header shows the PER-DAY plan target for TODAY (live) ────────────────────
  // The header used to show averaged/default targets, so a carb-load day never
  // bumped it. Now it reflects today's actual plan target. We refetch when the
  // plan is saved so edits show immediately.
  const DAYS_HDR = ["MON", "TUE", "WED", "THU", "FRI", "SAT", "SUN"];
  const todayKey = (() => { const d = new Date().getDay(); return DAYS_HDR[d === 0 ? 6 : d - 1]; })();
  const [planToday, setPlanToday] = useState(null);
  const [planRefreshTick, setPlanRefreshTick] = useState(0);

  useEffect(() => {
    let ignore = false;
    (async () => {
      if (!athlete?.id || !token) return;
      try {
        const rows = await apiFetch(`/macro-plans/${athlete.id}`, token);
        if (ignore) return;
        const row = (Array.isArray(rows) ? rows : []).find((r) => r.day_of_week === todayKey);
        if (row) {
          setPlanToday({
            calories: Number(row.calories || 0),
            protein: Number(row.protein_g || 0),
            carbs: Number(row.carbs_g || 0),
            fat: Number(row.fat_g || 0),
          });
        } else {
          setPlanToday(null);
        }
      } catch { /* keep showing defaults */ }
    })();
    return () => { ignore = true; };
  }, [athlete?.id, token, todayKey, planRefreshTick]);

  // The header prefers today's plan target; falls back to the athlete's
  // default targets if the coach hasn't set a plan for today.
  const headerGoals = planToday || goals;

  const handleSaveTargets = async () => {
    // Persist these targets by applying them to ALL days in the macro plan and saving to backend
    try {
      const payload = {
        plans: DAYS.map((d) => ({
          dayOfWeek: d,
          calories: goals.calories,
          protein_g: goals.protein,
          carbs_g: goals.carbs,
          fat_g: goals.fat,
        })),
      };
      await apiFetch(`/macro-plans/${athlete.id}`, token, {
        method: "PUT",
        body: JSON.stringify(payload),
      });
      setInitialGoals(goals);
      setEditing(false);
      setSaved(true);
      setTimeout(() => setSaved(false), 1800);
    } catch (e) {
      alert(e.message || "Could not save targets");
    }
  };

  const tabs = [
    { id: "nutrition", label: "NUTRITION" },
    { id: "macroplan", label: "MACRO PLAN" },
    { id: "mealplanner", label: "MEAL PLANNER" },
    { id: "messages", label: "MESSAGES" },
    { id: "foodlog", label: "FOOD LOG" },
    { id: "checkins", label: "CHECK-INS" },
    { id: "videos", label: "VIDEOS" },
    { id: "calendar", label: "CALENDAR" },
    { id: "wellbeing", label: "WELLBEING" },
  ];

  return (
    <div style={{ display: "flex", flexDirection: "column", gap: 16, animation: "fadeUp .2s ease" }}>
      <div style={{ display: "flex", alignItems: "center", gap: 14 }}>
        <button
          onClick={onBack}
          style={{
            background: T.card,
            border: `1px solid ${T.border}`,
            borderRadius: 8,
            padding: "6px 14px",
            color: T.muted,
            fontFamily: "DM Sans",
            fontSize: 12,
            cursor: "pointer",
          }}
          type="button"
        >
          ← Back
        </button>

        <Avatar initials={athlete.avatar} color={athlete.avatarColor} size={52} />

        <div style={{ flex: 1 }}>
          <div style={{ display: "flex", alignItems: "center", gap: 10, marginBottom: 2 }}>
            <span style={{ fontFamily: "Bebas Neue, system-ui", fontSize: 26, letterSpacing: 1.5, color: T.text }}>
              {athlete.name.toUpperCase()}
            </span>
            <Badge label={athlete.sport || "ATHLETE"} color={T.coachGreen} />
          </div>

          <div style={{ fontFamily: "JetBrains Mono, ui-monospace", fontSize: 11, color: T.muted }}>
            {athlete.email}
          </div>
        </div>

        {/* Delete athlete button */}
        {/* Pause / Unpause */}
        <button
          onClick={async () => {
            const next = !isActive;
            const msg = next
              ? `Reactivate ${athlete.name}'s account so they can log in again?`
              : `Pause ${athlete.name}'s account? They won't be able to log in, but ALL their data is kept and nothing is lost. You can unpause any time.`;
            if (!window.confirm(msg)) return;
            try {
              await apiFetch(`/athletes/${athlete.id}/status`, token, {
                method: "PATCH",
                body: JSON.stringify({ active: next }),
              });
              setIsActive(next);
            } catch (e) { alert(e.message || "Could not update account status"); }
          }}
          style={{
            background: "none",
            border: `1px solid ${isActive ? "#f59e0b66" : T.coachGreen + "66"}`,
            borderRadius: 8,
            padding: "6px 14px",
            color: isActive ? "#f59e0b" : T.coachGreen,
            fontFamily: "DM Sans",
            fontSize: 11,
            cursor: "pointer",
          }}
          type="button"
        >
          {isActive ? "⏸ Pause Account" : "▶ Unpause Account"}
        </button>

        {/* Transfer to another coach */}
        {!showTransfer ? (
          <button
            onClick={async () => {
              setShowTransfer(true);
              if (coachList.length === 0) {
                try {
                  const cs = await apiFetch(`/coaches`, token);
                  setCoachList(Array.isArray(cs) ? cs : []);
                } catch { setCoachList([]); }
              }
            }}
            style={{ background: "none", border: `1px solid ${T.border}`, borderRadius: 8, padding: "6px 14px", color: T.text, fontFamily: "DM Sans", fontSize: 11, cursor: "pointer" }}
            type="button"
          >
            ⇄ Transfer
          </button>
        ) : (
          <div style={{ display: "flex", gap: 6, alignItems: "center" }}>
            <select
              value={transferTo}
              onChange={(e) => setTransferTo(e.target.value)}
              style={{ background: T.surface, border: `1px solid ${T.border}`, borderRadius: 8, padding: "6px 8px", color: T.text, fontFamily: "DM Sans", fontSize: 11 }}
            >
              <option value="">Transfer to…</option>
              {coachList.map((c) => (
                <option key={c.id} value={c.id}>{c.name}</option>
              ))}
            </select>
            <button
              onClick={async () => {
                if (!transferTo) return;
                const target = coachList.find((c) => String(c.id) === String(transferTo));
                if (!window.confirm(`Transfer ${athlete.name} to ${target?.name}? All their data — food logs, weights, mood, habits, planned meals, calendar and notes — moves with them intact.`)) return;
                setTransferring(true);
                try {
                  await apiFetch(`/athletes/${athlete.id}/transfer`, token, {
                    method: "POST",
                    body: JSON.stringify({ newCoachId: Number(transferTo) }),
                  });
                  alert(`${athlete.name} transferred to ${target?.name}.`);
                  onDelete?.(athlete.id); // remove from this coach's roster view
                } catch (e) { alert(e.message || "Transfer failed"); }
                setTransferring(false);
                setShowTransfer(false);
              }}
              disabled={transferring || !transferTo}
              style={{ background: transferTo ? T.accent : T.border, color: transferTo ? T.bg : T.muted, border: "none", borderRadius: 6, padding: "6px 12px", fontFamily: "Bebas Neue, system-ui", fontSize: 11, letterSpacing: 1, cursor: transferTo && !transferring ? "pointer" : "default" }}
              type="button"
            >
              {transferring ? "…" : "GO"}
            </button>
            <button onClick={() => { setShowTransfer(false); setTransferTo(""); }} style={{ background: "none", border: "none", color: T.muted, fontSize: 11, cursor: "pointer", fontFamily: "DM Sans" }} type="button">cancel</button>
          </div>
        )}

        {!confirmResend ? (
          <button
            onClick={() => setConfirmResend(true)}
            style={{
              background: "none",
              border: `1px solid ${T.accent}44`,
              borderRadius: 8,
              padding: "6px 14px",
              color: T.accent,
              fontFamily: "DM Sans",
              fontSize: 11,
              cursor: "pointer",
            }}
            type="button"
          >
            🔑 Resend Login
          </button>
        ) : (
          <div style={{ display: "flex", gap: 6, alignItems: "center" }}>
            <span style={{ fontSize: 11, color: T.accent, fontFamily: "DM Sans" }}>Resets their password — sure?</span>
            <button
              onClick={async () => {
                setResending(true);
                try {
                  const res = await apiFetch(`/athletes/${athlete.id}/resend-credentials`, token, { method: "POST" });
                  if (res.emailed) {
                    alert(`New login details emailed to ${athlete.email}.`);
                  } else {
                    alert(`Email not sent (${res.emailEnabled ? "send failed" : "email not configured"}).\nNew password: ${res.password}\nPass it on to the athlete manually.`);
                  }
                } catch (e) {
                  alert(e.message || "Could not resend login details");
                }
                setResending(false);
                setConfirmResend(false);
              }}
              disabled={resending}
              style={{
                background: T.accent,
                border: "none",
                borderRadius: 6,
                padding: "5px 12px",
                color: T.bg,
                fontFamily: "Bebas Neue, system-ui",
                fontSize: 12,
                letterSpacing: 1,
                cursor: resending ? "default" : "pointer",
              }}
              type="button"
            >
              {resending ? "SENDING…" : "CONFIRM"}
            </button>
            <button
              onClick={() => setConfirmResend(false)}
              style={{ background: "none", border: "none", color: T.muted, fontSize: 11, cursor: "pointer", fontFamily: "DM Sans" }}
              type="button"
            >
              cancel
            </button>
          </div>
        )}
        {!confirmDelete ? (
          <button
            onClick={() => setConfirmDelete(true)}
            style={{
              background: "none",
              border: `1px solid ${T.danger}44`,
              borderRadius: 8,
              padding: "6px 14px",
              color: T.danger,
              fontFamily: "DM Sans",
              fontSize: 11,
              cursor: "pointer",
            }}
            type="button"
          >
            Delete Client
          </button>
        ) : (
          <div style={{ display: "flex", gap: 6, alignItems: "center" }}>
            <span style={{ fontSize: 11, color: T.danger, fontFamily: "DM Sans" }}>Permanently deletes ALL their data — sure? (Pause instead to keep it)</span>
            <button
              onClick={async () => {
                setDeleting(true);
                try {
                  await apiFetch(`/athletes/${athlete.id}`, token, { method: "DELETE" });
                  onDelete?.(athlete.id);
                } catch (e) {
                  alert(e.message || "Could not delete athlete");
                  setDeleting(false);
                  setConfirmDelete(false);
                }
              }}
              disabled={deleting}
              style={{
                background: T.danger,
                border: "none",
                borderRadius: 6,
                padding: "5px 12px",
                color: "#fff",
                fontFamily: "Bebas Neue, system-ui",
                fontSize: 12,
                letterSpacing: 1,
                cursor: deleting ? "default" : "pointer",
              }}
              type="button"
            >
              {deleting ? "DELETING…" : "YES, DELETE"}
            </button>
            <button
              onClick={() => setConfirmDelete(false)}
              style={{
                background: "none",
                border: `1px solid ${T.border}`,
                borderRadius: 6,
                padding: "5px 10px",
                color: T.muted,
                fontFamily: "DM Sans",
                fontSize: 11,
                cursor: "pointer",
              }}
              type="button"
            >
              Cancel
            </button>
          </div>
        )}
      </div>

      <div style={{ display: "grid", gridTemplateColumns: "repeat(4,1fr)", gap: 12 }}>
        <StatCard label={`CAL TARGET · ${todayKey}`} value={headerGoals.calories} color={T.accent} unit="kcal" />
        <StatCard label="PROTEIN" value={headerGoals.protein} color={T.protein} unit="g" />
        <StatCard label="CARBS" value={headerGoals.carbs} color={T.carbs} unit="g" />
        <StatCard label="FAT" value={headerGoals.fat} color={T.fat} unit="g" />
      </div>

      <div style={{ display: "flex", borderBottom: `1px solid ${T.border}`, gap: 1, overflowX: "auto" }}>
        {tabs.map((t) => (
          <button
            key={t.id}
            onClick={() => setTab(t.id)}
            style={{
              padding: "10px 16px",
              background: "none",
              border: "none",
              cursor: "pointer",
              fontFamily: "Bebas Neue, system-ui",
              fontSize: 13,
              letterSpacing: 1.5,
              color: tab === t.id ? T.accent : T.muted,
              whiteSpace: "nowrap",
              borderBottom: tab === t.id ? `2px solid ${T.accent}` : "2px solid transparent",
              marginBottom: -1,
              transition: "all .2s",
            }}
            type="button"
          >
            {t.label}
          </button>
        ))}
      </div>

      {tab === "nutrition" && (
        <>
        <div style={{ background: T.card, border: `1px solid ${T.border}`, borderRadius: 18, padding: 22 }}>
          {saved && (
            <div
              style={{
                background: `${T.coachGreen}18`,
                border: `1px solid ${T.coachGreen}44`,
                borderRadius: 10,
                padding: "10px 14px",
                fontFamily: "DM Sans",
                fontSize: 12,
                color: T.coachGreen,
                marginBottom: 12,
              }}
            >
              ✓ Targets updated (local defaults for macro overview).
            </div>
          )}

          <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 14 }}>
            <div>
              <div style={{ fontFamily: "Bebas Neue, system-ui", fontSize: 18, letterSpacing: 2, color: T.text }}>
                MACRO TARGETS (DEFAULTS)
              </div>
              <div style={{ fontFamily: "DM Sans", fontSize: 11, color: T.muted, marginTop: 4 }}>
                Used by “Populate all days” in the Macro Plan tab.
              </div>
            </div>

            <div style={{ display: "flex", gap: 8 }}>
              {editing ? (
                <>
                  <button
                    onClick={() => {
                      setGoals({
                        calories: athlete.macroGoals?.calories ?? 2500,
                        protein: athlete.macroGoals?.protein ?? 180,
                        carbs: athlete.macroGoals?.carbs ?? 280,
                        fat: athlete.macroGoals?.fat ?? 75,
                      });
                      setEditing(false);
                    }}
                    style={{
                      background: "none",
                      border: `1px solid ${T.border}`,
                      borderRadius: 10,
                      padding: "8px 12px",
                      color: T.muted,
                      fontFamily: "DM Sans",
                      fontSize: 12,
                      cursor: "pointer",
                    }}
                    type="button"
                  >
                    Cancel
                  </button>

                  <button
                    onClick={handleSaveTargets}
                    style={{
                      background: T.accent,
                      border: "none",
                      borderRadius: 10,
                      padding: "8px 14px",
                      color: T.bg,
                      fontFamily: "Bebas Neue, system-ui",
                      fontSize: 14,
                      letterSpacing: 1.5,
                      cursor: "pointer",
                    }}
                    type="button"
                  >
                    SAVE
                  </button>
                </>
              ) : (
                <button
                  onClick={() => setEditing(true)}
                  style={{
                    background: "none",
                    border: `1px solid ${T.accent}44`,
                    borderRadius: 10,
                    padding: "8px 14px",
                    color: T.accent,
                    fontFamily: "DM Sans",
                    fontSize: 12,
                    cursor: "pointer",
                  }}
                  type="button"
                >
                  ✏ Edit Targets
                </button>
              )}
            </div>
          </div>

          <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 12 }}>
            {[
              { key: "calories", label: "Calories", unit: "kcal", color: T.accent },
              { key: "protein", label: "Protein", unit: "g", color: T.protein },
              { key: "carbs", label: "Carbs", unit: "g", color: T.carbs },
              { key: "fat", label: "Fat", unit: "g", color: T.fat },
            ].map((m) => (
              <div key={m.key}>
                <label style={labelStyle}>{m.label}</label>
                {editing ? (
                  <input
                    type="number"
                    value={goals[m.key]}
                    onChange={(e) => setGoals((g) => ({ ...g, [m.key]: clamp(Number(e.target.value), 0, 20000) }))}
                    style={{
                      ...inputStyle,
                      border: `1px solid ${m.color}44`,
                      color: m.color,
                      fontFamily: "JetBrains Mono, ui-monospace",
                      fontSize: 14,
                      fontWeight: 700,
                    }}
                  />
                ) : (
                  <div style={{ display: "flex", alignItems: "baseline", gap: 6 }}>
                    <span style={{ fontFamily: "Bebas Neue, system-ui", fontSize: 30, color: m.color }}>{goals[m.key]}</span>
                    <span style={{ fontFamily: "DM Sans", fontSize: 12, color: T.muted }}>{m.unit}</span>
                  </div>
                )}
              </div>
            ))}
          </div>
        </div>

        {/* Weekly adherence dashboard */}
        <WeeklyAdherenceView athleteId={athlete.id} token={token} />
        </>
      )}

      {tab === "macroplan" && (
        <WeeklyMacroPlan athleteId={athlete.id} baseTargets={goals} token={token} onSaved={(p) => {
        // Refresh the header from the saved per-day plan (today's target),
        // rather than averaging the week — so a carb-load day shows correctly.
        if (p && p[todayKey]) {
          setPlanToday({
            calories: Number(p[todayKey].calories || 0),
            protein: Number(p[todayKey].protein || 0),
            carbs: Number(p[todayKey].carbs || 0),
            fat: Number(p[todayKey].fat || 0),
          });
        }
        setPlanRefreshTick((t) => t + 1); // also re-fetch from backend to stay in sync
      }} />
      )}

      {tab === "messages" && (
        <CoachMessaging athleteId={athlete.id} athleteName={athlete.name} token={token} />
      )}

      {tab === "foodlog" && (
        <AthleteFoodLogViewer athleteId={athlete.id} token={token} macroTarget={goals} />
      )}

      {tab === "checkins" && (
        <AthleteCheckInManager athleteId={athlete.id} token={token} />
      )}

      {tab === "videos" && (
        <AthleteVideoManager athleteId={athlete.id} token={token} />
      )}

      {tab === "calendar" && (
        <AthleteCalendarManager athleteId={athlete.id} token={token} />
      )}

      {tab === "wellbeing" && (
        <WellbeingManager athleteId={athlete.id} token={token} />
      )}

      {tab === "mealplanner" && (
        <MealPlannerTab athleteId={athlete.id} token={token} />
      )}
    </div>
  );
}

