/* ─────────────────────────────────────────────────────────────────────────────
   Admin Panel — manage coaches (admin only)
────────────────────────────────────────────────────────────────────────────── */
function AdminPanel({ token, myId }) {
  const [coaches, setCoaches] = useState([]);
  const [loading, setLoading] = useState(true);
  const [showAdd, setShowAdd] = useState(false);
  const [form, setForm] = useState({ name: "", email: "", password: "", role: "coach" });
  const [creating, setCreating] = useState(false);
  const [err, setErr] = useState("");

  const loadCoaches = async () => {
    try {
      const rows = await apiFetch("/admin/coaches", token);
      setCoaches(Array.isArray(rows) ? rows : []);
    } catch (e) { setErr(e.message); }
    setLoading(false);
  };

  useEffect(() => { if (token) loadCoaches(); }, [token]);

  const createCoach = async () => {
    if (!form.name.trim() || !form.email.trim() || !form.password.trim() || form.password.length < 6) return;
    setCreating(true); setErr("");
    try {
      await apiFetch("/admin/coaches", token, {
        method: "POST",
        body: JSON.stringify({
          name: form.name.trim(),
          email: form.email.trim().toLowerCase(),
          password: form.password,
          role: form.role,
        }),
      });
      setForm({ name: "", email: "", password: "", role: "coach" });
      setShowAdd(false);
      await loadCoaches();
    } catch (e) { setErr(e.message); }
    setCreating(false);
  };

  const deleteCoach = async (id) => {
    if (!confirm("Are you sure you want to remove this coach? Their athletes will be unassigned.")) return;
    try {
      await apiFetch(`/admin/coaches/${id}`, token, { method: "DELETE" });
      await loadCoaches();
    } catch (e) { alert(e.message); }
  };

  return (
    <div style={{ display: "flex", flexDirection: "column", gap: 16, animation: "fadeUp .2s ease" }}>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
        <div>
          <div style={{ fontFamily: "Bebas Neue, system-ui", fontSize: 28, letterSpacing: 2 }}>COACH MANAGEMENT</div>
          <div style={{ fontFamily: "DM Sans", fontSize: 12, color: T.muted, marginTop: 4 }}>
            Add or remove coaches. Removing a coach unassigns their athletes.
          </div>
        </div>
        <button onClick={() => setShowAdd(!showAdd)} style={{
          background: T.accent, color: T.bg, border: "none", borderRadius: 10, padding: "10px 18px",
          fontFamily: "Bebas Neue, system-ui", fontSize: 14, letterSpacing: 1.5, cursor: "pointer",
        }} type="button">{showAdd ? "CANCEL" : "+ ADD COACH"}</button>
      </div>

      {err && (
        <div style={{ background: `${T.danger}18`, border: `1px solid ${T.danger}44`, borderRadius: 12, padding: "12px 14px", color: T.danger, fontSize: 12 }}>{err}</div>
      )}

      {showAdd && (
        <div style={{ background: T.card, border: `1px solid ${T.accent}44`, borderRadius: 16, padding: 20 }}>
          <div style={{ fontFamily: "Bebas Neue, system-ui", fontSize: 16, letterSpacing: 2, color: T.text, marginBottom: 14 }}>NEW COACH ACCOUNT</div>
          <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 12 }}>
            <div>
              <label style={labelStyle}>Full Name *</label>
              <input value={form.name} onChange={(e) => setForm(p => ({...p, name: e.target.value}))} placeholder="Coach name" style={inputStyle} />
            </div>
            <div>
              <label style={labelStyle}>Email *</label>
              <input value={form.email} onChange={(e) => setForm(p => ({...p, email: e.target.value}))} placeholder="coach@norules.com" style={inputStyle} />
            </div>
            <div>
              <label style={labelStyle}>Password * (min 6)</label>
              <input value={form.password} onChange={(e) => setForm(p => ({...p, password: e.target.value}))} placeholder="Password" style={inputStyle} />
            </div>
            <div>
              <label style={labelStyle}>Role</label>
              <select value={form.role} onChange={(e) => setForm(p => ({...p, role: e.target.value}))} style={{ ...inputStyle, cursor: "pointer" }}>
                <option value="coach" style={{ background: T.bg }}>Coach</option>
                <option value="admin" style={{ background: T.bg }}>Admin</option>
              </select>
            </div>
          </div>
          <button onClick={createCoach} disabled={creating || !form.name.trim() || !form.email.trim() || form.password.length < 6}
            style={{
              marginTop: 14, background: T.accent, color: T.bg, border: "none", borderRadius: 10, padding: "10px 18px",
              fontFamily: "Bebas Neue, system-ui", fontSize: 14, letterSpacing: 1.5,
              cursor: creating ? "default" : "pointer", opacity: creating ? 0.6 : 1,
            }} type="button">{creating ? "CREATING…" : "CREATE COACH"}</button>
        </div>
      )}

      <div style={{ background: T.card, border: `1px solid ${T.border}`, borderRadius: 20, overflow: "hidden" }}>
        <div style={{ padding: "14px 18px", borderBottom: `1px solid ${T.border}`, display: "flex", justifyContent: "space-between" }}>
          <div style={{ fontFamily: "Bebas Neue, system-ui", fontSize: 16, letterSpacing: 2 }}>ALL COACHES</div>
          <Badge label={`${coaches.length} COACHES`} color={T.coachGreen} />
        </div>
        {loading ? (
          <div style={{ padding: 18, color: T.muted }}>Loading coaches…</div>
        ) : coaches.length === 0 ? (
          <div style={{ padding: 18, color: T.muted }}>No coaches found.</div>
        ) : (
          coaches.map((c, idx) => (
            <div key={c.id} style={{
              padding: "14px 18px", borderBottom: idx < coaches.length - 1 ? `1px solid ${T.border}` : "none",
              display: "flex", alignItems: "center", gap: 12,
            }}>
              <Avatar initials={initialsOf(c.name)} color={c.role === "admin" ? T.accent : T.coachGreen} size={40} />
              <div style={{ flex: 1 }}>
                <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
                  <span style={{ fontWeight: 700, color: T.text }}>{c.name}</span>
                  <Badge label={c.role.toUpperCase()} color={c.role === "admin" ? T.accent : T.coachGreen} />
                </div>
                <div style={{ fontFamily: "JetBrains Mono, ui-monospace", fontSize: 10, color: T.muted, marginTop: 2 }}>{c.email}</div>
              </div>
              {c.id !== myId && (
                <button onClick={() => deleteCoach(c.id)} style={{
                  background: "none", border: `1px solid ${T.danger}44`, borderRadius: 8, padding: "6px 12px",
                  color: T.danger, fontFamily: "DM Sans", fontSize: 11, cursor: "pointer",
                }} type="button">Remove</button>
              )}
              {c.id === myId && (
                <span style={{ fontSize: 10, color: T.muted, fontStyle: "italic" }}>You</span>
              )}
            </div>
          ))
        )}
      </div>
    </div>
  );
}

export default function CoachCMS() {
  const [me, setMe] = useState(null); // { id, email, name, role, token }
  const [token, setToken] = useState(null);
  const [loadingRoster, setLoadingRoster] = useState(false);
  const [rosterErr, setRosterErr] = useState("");
  const [athletes, setAthletes] = useState([]);
  const [view, setView] = useState("overview"); // overview | athlete | admin | inbox
  const [selected, setSelected] = useState(null);

  const [showAdd, setShowAdd] = useState(false);
  const [showBatch, setShowBatch] = useState(false);
  const [rosterRefresh, setRosterRefresh] = useState(0);
  const [creating, setCreating] = useState(false);
  const [showBroadcast, setShowBroadcast] = useState(false);
  const [showBroadcastContent, setShowBroadcastContent] = useState(false);
  useEffect(() => {
    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href =
      "https://fonts.googleapis.com/css2?family=Bebas+Neue&family=DM+Sans:wght@300;400;500;600;700&family=JetBrains+Mono:wght@400;600&display=swap";
    document.head.appendChild(link);
    return () => link.remove();
  }, []);

  // Try restore session token from localStorage, then /auth/me
  useEffect(() => {
    const t = localStorage.getItem(TOKEN_KEY);
    if (!t) return;

    setToken(t);
    (async () => {
      try {
        const user = await apiFetch("/auth/me", t); // backend supports this [1](https://github.com/orgs/community/discussions/151670)
        setMe({ ...user, token: t });
      } catch {
        localStorage.removeItem(TOKEN_KEY);
        setToken(null);
        setMe(null);
      }
    })();
  }, []);

  // Load roster after login
  useEffect(() => {
    if (!token || !me) return;
    if (me.role !== "coach" && me.role !== "admin") return;

    setRosterErr("");
    setLoadingRoster(true);

    (async () => {
      try {
        const rows = await apiFetch("/athletes", token); // backend supports this [1](https://github.com/orgs/community/discussions/151670)
        const mapped = rows.map((a) => ({
          id: a.id,
          name: a.name,
          email: a.email,
          sport: a.sport || "—",
          active: a.active !== false,
          avatar: initialsOf(a.name),
          avatarColor: randomAvatarColor(),
          macroGoals: { calories: 2500, protein: 180, carbs: 280, fat: 75 },
        }));
        setAthletes(mapped);

        // Compute weekly adherence the same way the athlete-detail view does, so
        // the roster and detail always agree. Done per-athlete (fine for typical
        // roster sizes); for very large rosters this could be moved server-side.
        mapped.forEach(async (athlete) => {
          const adh = await computeWeeklyAdherence(athlete.id, token);
          if (!adh) return;
          setAthletes((prev) => prev.map((a) => a.id === athlete.id ? { ...a, ...adh } : a));
        });
      } catch (e) {
        setRosterErr(e.message);
      } finally {
        setLoadingRoster(false);
      }
    })();
  }, [token, me, rosterRefresh]);

  const onLoggedIn = (userWithToken) => {
    setMe(userWithToken);
    setToken(userWithToken.token);
  };

  const logout = async () => {
    try {
      if (token) await apiFetch("/auth/logout", token, { method: "POST" }); // optional [1](https://github.com/orgs/community/discussions/151670)
    } catch {}
    localStorage.removeItem(TOKEN_KEY);
    setToken(null);
    setMe(null);
    setAthletes([]);
    setSelected(null);
    setView("overview");
  };

  const createAthlete = async (form) => {
    setCreating(true);
    try {
      const created = await apiFetch("/athletes", token, {
        method: "POST",
        body: JSON.stringify({
          email: form.loginEmail.trim().toLowerCase(),
          name: form.name.trim(),
          password: form.password,
          sport: form.sport,
        }),
      }); // backend supports POST /athletes [1](https://github.com/orgs/community/discussions/151670)

      const mapped = {
        id: created.id,
        name: created.name,
        email: created.email,
        sport: created.sport || form.sport || "—",
        avatar: initialsOf(created.name),
        avatarColor: randomAvatarColor(),
        macroGoals: { calories: 2500, protein: 180, carbs: 280, fat: 75 },
      };

      setAthletes((p) => [mapped, ...p].sort((a, b) => a.name.localeCompare(b.name)));
      setShowAdd(false);
    } catch (e) {
      alert(e.message);
    } finally {
      setCreating(false);
    }
  };

  if (!me || !token) {
    return <CoachLogin onLoggedIn={onLoggedIn} />;
  }

  // Basic coach/admin guard
  if (me.role !== "coach" && me.role !== "admin") {
    return (
      <div style={{ minHeight: "100vh", background: T.bg, color: T.text, fontFamily: "DM Sans", padding: 30 }}>
        <h2 style={{ fontFamily: "Bebas Neue, system-ui", letterSpacing: 2 }}>Access denied</h2>
        <p style={{ color: T.muted, marginTop: 10 }}>
          Your account role is <strong>{me.role}</strong>. This portal is for coaches only.
        </p>
        <button
          onClick={logout}
          style={{
            marginTop: 16,
            background: T.accent,
            border: "none",
            color: T.bg,
            borderRadius: 10,
            padding: "10px 16px",
            fontFamily: "Bebas Neue, system-ui",
            letterSpacing: 1.5,
            cursor: "pointer",
          }}
          type="button"
        >
          LOG OUT
        </button>
      </div>
    );
  }

  return (
    <div style={{ minHeight: "100vh", background: T.bg, color: T.text, fontFamily: "DM Sans" }}>
      <style>{`
        *{box-sizing:border-box}
        @keyframes fadeUp{from{opacity:0;transform:translateY(10px)}to{opacity:1;transform:translateY(0)}}
        @keyframes pulse{0%,100%{opacity:0.4}50%{opacity:1}}
      `}</style>

      {/* Top bar */}
      <div
        style={{
          position: "sticky",
          top: 0,
          zIndex: 50,
          background: `${T.bg}f0`,
          backdropFilter: "blur(8px)",
          borderBottom: `1px solid ${T.border}`,
        }}
      >
        <div style={{ maxWidth: 1200, margin: "0 auto", padding: "14px 18px", display: "flex", alignItems: "center", gap: 12 }}>
          <img src={LOGO_SRC} alt="NRN" style={{ width: 42, height: 42, borderRadius: "50%", border: `2px solid ${T.accent}44` }} />
          <div style={{ flex: 1 }}>
            <div style={{ fontFamily: "Bebas Neue, system-ui", fontSize: 22, letterSpacing: 2 }}>NO RULES NUTRITION</div>
            <div style={{ fontSize: 11, color: T.muted, marginTop: 2 }}>
              Coach: <span style={{ color: T.text, fontWeight: 600 }}>{me.name}</span> ·{" "}
              <span style={{ fontFamily: "JetBrains Mono, ui-monospace" }}>{me.email}</span>
            </div>
          </div>

          <Badge label={me.role === "admin" ? "ADMIN" : "COACH"} color={me.role === "admin" ? T.accent : T.coachGreen} />

          {me.role === "admin" && (
            <button
              onClick={() => setView(view === "admin" ? "overview" : "admin")}
              style={{
                background: view === "admin" ? `${T.accent}22` : "none",
                border: `1px solid ${view === "admin" ? T.accent + "55" : T.border}`,
                color: view === "admin" ? T.accent : T.muted,
                borderRadius: 10, padding: "8px 12px", cursor: "pointer",
                fontFamily: "DM Sans", fontSize: 12,
              }}
              type="button"
            >
              {view === "admin" ? "← Clients" : "⚙ Manage Coaches"}
            </button>
          )}

          <button
            onClick={() => setView(view === "inbox" ? "overview" : "inbox")}
            style={{
              background: view === "inbox" ? `${T.accent}22` : "none",
              border: `1px solid ${view === "inbox" ? T.accent + "55" : T.border}`,
              color: view === "inbox" ? T.accent : T.muted,
              borderRadius: 10, padding: "8px 12px", cursor: "pointer",
              fontFamily: "DM Sans", fontSize: 12,
            }}
            type="button"
          >
            {view === "inbox" ? "← Clients" : "💬 Inbox"}
          </button>

          <button
            onClick={logout}
            style={{
              background: "none",
              border: `1px solid ${T.border}`,
              color: T.muted,
              borderRadius: 10,
              padding: "8px 12px",
              cursor: "pointer",
              fontFamily: "DM Sans",
              fontSize: 12,
            }}
            type="button"
          >
            Log out
          </button>
        </div>
      </div>

      {/* Main */}
      <div style={{ maxWidth: 1200, margin: "0 auto", padding: "18px" }}>
        {view === "overview" && (
          <div style={{ display: "flex", flexDirection: "column", gap: 16 }}>
            <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
              <div>
                <div style={{ fontFamily: "Bebas Neue, system-ui", fontSize: 28, letterSpacing: 2 }}>
                  CLIENT ROSTER
                </div>
                <div style={{ fontFamily: "DM Sans", fontSize: 12, color: T.muted, marginTop: 4 }}>
                  Click an athlete to open their profile and macro plan.
                </div>
              </div>

              <div style={{ display: "flex", gap: 8 }}>
                <button
                  onClick={() => setShowBroadcast(true)}
                  disabled={athletes.length === 0}
                  style={{
                    background: "none",
                    border: `1px solid ${T.accent}44`,
                    color: T.accent,
                    borderRadius: 10,
                    padding: "10px 14px",
                    fontFamily: "Bebas Neue, system-ui",
                    fontSize: 14,
                    letterSpacing: 1.5,
                    cursor: athletes.length > 0 ? "pointer" : "default",
                    opacity: athletes.length > 0 ? 1 : 0.5,
                  }}
                  type="button"
                >
                  📢 BROADCAST
                </button>
                <button
                  onClick={() => setShowBroadcastContent(true)}
                  disabled={athletes.length === 0}
                  style={{
                    background: "none",
                    border: `1px solid ${T.accent}44`,
                    color: T.accent,
                    borderRadius: 10,
                    padding: "10px 14px",
                    fontFamily: "Bebas Neue, system-ui",
                    fontSize: 14,
                    letterSpacing: 1.5,
                    cursor: athletes.length > 0 ? "pointer" : "default",
                    opacity: athletes.length > 0 ? 1 : 0.5,
                  }}
                  type="button"
                >
                  📤 SEND CONTENT
                </button>
              <button
                onClick={() => setShowBatch(true)}
                style={{
                  background: T.surface,
                  color: T.accent,
                  border: `1px dashed ${T.accent}`,
                  borderRadius: 10,
                  padding: "10px 18px",
                  fontFamily: "Bebas Neue, system-ui",
                  fontSize: 14,
                  letterSpacing: 1.5,
                  cursor: "pointer",
                }}
                type="button"
              >
                📄 CSV UPLOAD
              </button>
              <button
                onClick={() => setShowAdd(true)}
                style={{
                  background: T.accent,
                  color: T.bg,
                  border: "none",
                  borderRadius: 10,
                  padding: "10px 18px",
                  fontFamily: "Bebas Neue, system-ui",
                  fontSize: 14,
                  letterSpacing: 1.5,
                  cursor: "pointer",
                }}
                type="button"
              >
                + ADD ATHLETE
              </button>
              </div>
            </div>

            {rosterErr && (
              <div
                style={{
                  background: `${T.danger}18`,
                  border: `1px solid ${T.danger}44`,
                  borderRadius: 12,
                  padding: "12px 14px",
                  color: T.danger,
                  fontSize: 12,
                }}
              >
                {rosterErr}
              </div>
            )}

            <div style={{ display: "grid", gridTemplateColumns: "repeat(4,1fr)", gap: 12 }}>
              <StatCard label="TOTAL ATHLETES" value={athletes.length} color={T.accent} />
              <StatCard label="API" value="CONNECTED" color={T.coachGreen} sub={API_BASE} />
              <StatCard label="TOKEN" value={token ? "ACTIVE" : "—"} color={token ? T.coachGreen : T.warn} />
              <StatCard label="STATUS" value={loadingRoster ? "LOADING…" : "READY"} color={loadingRoster ? T.warn : T.text} />
            </div>

            <div style={{ background: T.card, border: `1px solid ${T.border}`, borderRadius: 20, overflow: "hidden" }}>
              <div style={{ padding: "14px 18px", borderBottom: `1px solid ${T.border}`, display: "flex", justifyContent: "space-between" }}>
                <div style={{ fontFamily: "Bebas Neue, system-ui", fontSize: 16, letterSpacing: 2 }}>ATHLETES</div>
                <Badge label={`${athletes.length} ATHLETES`} color={T.accent} />
              </div>

              {loadingRoster ? (
                <div style={{ padding: 18, color: T.muted }}>Loading athletes…</div>
              ) : athletes.length === 0 ? (
                <div style={{ padding: 18, color: T.muted }}>
                  No athletes found for this coach yet. Click <b>+ ADD ATHLETE</b> to create one.
                </div>
              ) : (
                athletes.map((a, idx) => (
                  <div
                    key={a.id}
                    onClick={() => {
                      setSelected(a);
                      setView("athlete");
                    }}
                    style={{
                      padding: "14px 18px",
                      borderBottom: idx < athletes.length - 1 ? `1px solid ${T.border}` : "none",
                      display: "flex",
                      alignItems: "center",
                      gap: 12,
                      cursor: "pointer",
                      transition: "background .15s",
                    }}
                    onMouseEnter={(e) => (e.currentTarget.style.background = T.surface)}
                    onMouseLeave={(e) => (e.currentTarget.style.background = "transparent")}
                  >
                    <Avatar initials={a.avatar} color={a.avatarColor} size={40} />
                    <div style={{ flex: 1, minWidth: 0 }}>
                      <div style={{ display: "flex", alignItems: "center", gap: 10 }}>
                        <span style={{ fontWeight: 700 }}>{a.name}</span>
                        <Badge label={a.sport || "ATHLETE"} color={T.coachGreen} />
                        {a.active === false && <Badge label="PAUSED" color="#f59e0b" />}
                      </div>
                      <div style={{ fontFamily: "JetBrains Mono, ui-monospace", fontSize: 10, color: T.muted, marginTop: 3 }}>
                        {a.email}
                      </div>
                    </div>
                    <AdherenceCells a={a} />
                    <div style={{ color: T.muted, fontSize: 12 }}>›</div>
                  </div>
                ))
              )}
            </div>
          </div>
        )}

        {view === "athlete" && selected && (
          <AthleteDetail
            athlete={selected}
            token={token}
            onBack={() => {
              setView("overview");
              setSelected(null);
            }}
            onDelete={(deletedId) => {
              setAthletes((prev) => prev.filter((a) => a.id !== deletedId));
              setView("overview");
              setSelected(null);
            }}
          />
        )}

        {view === "admin" && me.role === "admin" && (
          <div style={{ display: "flex", flexDirection: "column", gap: 24 }}>
            <AdminCoachOverview token={token} myId={me.id} />
            <AdminPanel token={token} myId={me.id} />
          </div>
        )}

        {view === "inbox" && (
          <CoachInbox
            athletes={athletes}
            token={token}
            myId={me?.id}
            onBroadcast={() => setShowBroadcast(true)}
          />
        )}
      </div>

      {showAdd && (
        <AddAthleteModal
          onClose={() => setShowAdd(false)}
          onCreate={createAthlete}
          creating={creating}
        />
      )}

      {showBatch && (
        <BatchUploadModal
          token={token}
          onClose={() => setShowBatch(false)}
          onDone={() => setRosterRefresh((n) => n + 1)}
        />
      )}

      {showBroadcast && (
        <BroadcastModal
          token={token}
          athleteCount={athletes.length}
          onClose={() => setShowBroadcast(false)}
        />
      )}

      {showBroadcastContent && (
        <BroadcastContentModal
          token={token}
          athletes={athletes}
          onClose={() => setShowBroadcastContent(false)}
        />
      )}
    </div>
  );
}